B.anT=new A.c("\u0646\u0638\u0631\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0627\u062a \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0629",null,"\u0627\u0644\u062a\u0639\u0644\u0645 \u0630\u0648 \u0627\u0644\u0645\u0639\u0646\u0649 (Apprentissage significatif) \u0627\u0644\u0630\u064a \u064a\u0642\u0635\u062f \u0628\u0647 \u0631\u0628\u0637 \u0627\u0644\u0645\u0639\u0627\u0631\u0641 \u0627\u0644\u062c\u062f\u064a\u062f\u0629 \u0628\u0627\u0644\u0628\u0646\u064a\u0629 \u0627\u0644\u0645\u0639\u0631\u0641\u064a\u0629 \u0627\u0644\u0642\u0628\u0644\u064a\u0629 \u0644\u0644\u0645\u062a\u0639\u0644\u0645 \u064a\u0631\u062a\u0628\u0637 \u0628\u0640:",B.TG,0,"\u0623\u0648\u0632\u0648\u0628\u064a\u0644 \u0645\u064a\u0632 \u0628\u064a\u0646 \u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0644\u062d\u0641\u0638\u064a \u0648\u0627\u0644\u062a\u0639\u0644\u0645 \u0630\u064a \u0627\u0644\u0645\u0639\u0646\u0649: \u0647\u0630\u0627 \u0627\u0644\u0623\u062e\u064a\u0631 \u064a\u062f\u0645\u062c \u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0627\u0644\u062c\u062f\u064a\u062f\u0629 \u0641\u064a \u0627\u0644\u0628\u0646\u064a\u0629 \u0627\u0644\u0645\u0639\u0631\u0641\u064a\u0629 \u0627\u0644\u0642\u0627\u0626\u0645\u0629.",u.N)
B.a1K=s(["\u062a\u0631\u0627\u0628\u0637\u0627\u062a \u0645\u062d\u0641\u0632/\u0627\u0633\u062a\u062c\u0627\u0628\u0629","\u0625\u0639\u0627\u062f\u0629 \u062a\u0646\u0638\u064a\u0645 \u0627\u0644\u0625\u062f\u0631\u0627\u0643 \u0648\u0627\u0644\u0628\u0635\u064a\u0631\u0629","\u0645\u0644\u0627\u062d\u0638\u0629 \u0627\u0644\u0646\u0645\u0627\u0630\u062c \u0648\u062a\u0642\u0644\u064a\u062f\u0647\u0627","\u0628\u0646\u0627\u0621 \u0645\u0639\u0627\u0631\u0641 \u0630\u0627\u062a\u064a\u0629 \u0645\u0646 \u0627\u0644\u062a\u0645\u062b\u0644\u0627\u062a","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.anx=new A.c("\u0646\u0638\u0631\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0627\u062a \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0629",null,"\u0645\u062f\u0631\u0633\u0629 \u0627\u0644\u062c\u0634\u0637\u0627\u0644\u062a (\u0627\u0644\u0628\u0646\u064a\u0629 \u0627\u0644\u0634\u0643\u0644\u064a\u0629) \u062a\u0641\u0633\u0631 \u0627\u0644\u062a\u0639\u0644\u0645 \u0628\u0648\u0635\u0641\u0647:",B.a1K,1,"\u0627\u0644\u062c\u0634\u0637\u0627\u0644\u062a (\u0643\u0648\u0647\u0644\u0631 \u0648\u0641\u064a\u0631\u062a\u0647\u0627\u064a\u0645\u0631) \u062a\u0631\u0649 \u0623\u0646 \u0627\u0644\u062a\u0639\u0644\u0645 \u064a\u062a\u0645 \u0639\u0628\u0631 \u0627\u0644\u0628\u0635\u064a\u0631\u0629 \u0648\u0625\u0639\u0627\u062f\u0629 \u062a\u0646\u0638\u064a\u0645 \u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u0645\u0648\u0642\u0641\u060c \u0643\u0645\u0627 \u0641\u064a \u062a\u062c\u0631\u0628\u0629 \u0627\u0644\u0634\u0645\u0628\u0627\u0646\u0632\u064a.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629\xbb \u2014 \u0635 72")
B.Ta=s(["\u0623\u0644\u0628\u0631\u062a \u0628\u0627\u0646\u062f\u0648\u0631\u0627","\u0625\u064a\u0641\u0627\u0646 \u0628\u0627\u0641\u0644\u0648\u0641","\u062c\u0627\u0646 \u0628\u064a\u0627\u062c\u064a\u0647","\u0644\u064a\u0641 \u0641\u064a\u063a\u0648\u062a\u0633\u0643\u064a","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.amw=new A.c("\u0646\u0638\u0631\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0627\u062a \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0629",null,"\u0646\u0638\u0631\u064a\u0629 \u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a \u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u0639\u0644\u0649 \u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0629 \u0648\u0627\u0644\u0646\u0645\u0630\u062c\u0629 (\u0627\u0644\u062a\u0642\u0644\u064a\u062f) \u062a\u0646\u0633\u0628 \u0625\u0644\u0649:",B.Ta,0,"\u0628\u0627\u0646\u062f\u0648\u0631\u0627: \u0627\u0644\u062a\u0639\u0644\u0645 \u064a\u062d\u062f\u062b \u0628\u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0629 \u0648\u0627\u0644\u062a\u0642\u0644\u064a\u062f \u0648\u0627\u0644\u0646\u0645\u0630\u062c\u0629 \u062f\u0648\u0646 \u062d\u062a\u0645\u064a\u0629 \u062a\u0639\u0632\u064a\u0632 \u0645\u0628\u0627\u0634\u0631 (\u062a\u062c\u0631\u0628\u0629 \u062f\u0645\u064a\u0629 \u0628\u0648\u0628\u0648).",u.N)
B.Xj=s(["\u0643\u0627\u0631\u0644 \u0631\u0648\u062c\u0631\u0632","\u0623\u0628\u0631\u0627\u0647\u0627\u0645 \u0645\u0627\u0633\u0644\u0648","\u0633\u0643\u064a\u0646\u0631","\u0628\u064a\u0627\u062c\u064a\u0647","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.ajk=new A.c("\u0646\u0638\u0631\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0627\u062a \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0629",null,"\u0633\u0644\u0645 \u0627\u0644\u062d\u0627\u062c\u0627\u062a \u0627\u0644\u0625\u0646\u0633\u0627\u0646\u064a\u0629 (\u0627\u0644\u0641\u064a\u0632\u064a\u0648\u0644\u0648\u062c\u064a\u0629\u060c \u0627\u0644\u0623\u0645\u0646\u060c \u0627\u0644\u0627\u0646\u062a\u0645\u0627\u0621\u060c \u0627\u0644\u062a\u0642\u062f\u064a\u0631\u060c \u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u0630\u0627\u062a) \u064a\u0646\u0633\u0628 \u0625\u0644\u0649:",B.Xj,1,"\u0645\u0627\u0633\u0644\u0648 \u0635\u0627\u062d\u0628 \u0633\u0644\u0645 \u0627\u0644\u062d\u0627\u062c\u0627\u062a\u061b \u0648\u0644\u0627 \u064a\u0645\u0643\u0646 \u0644\u0644\u0645\u062a\u0639\u0644\u0645 \u0623\u0646 \u064a\u0635\u0644 \u0625\u0644\u0649 \u062d\u0627\u062c\u0627\u062a \u0627\u0644\u0639\u0644\u064a\u0627 (\u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u0630\u0627\u062a) \u062f\u0648\u0646 \u0625\u0634\u0628\u0627\u0639 \u0627\u0644\u062d\u0627\u062c\u0627\u062a \u0627\u0644\u062f\u0646\u064a\u0627.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629\xbb")
B.a7Z=s(["\u0643\u0627\u0631\u0644 \u0631\u0648\u062c\u0631\u0632","\u0628\u0627\u0641\u0644\u0648\u0641","\u062b\u0648\u0631\u0646\u062f\u0627\u064a\u0643","\u062f\u0648\u0631\u0643\u0627\u064a\u0645","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aiD=new A.c("\u0646\u0638\u0631\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0627\u062a \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0629",null,"\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0629 \u0627\u0644\u0645\u062a\u0645\u062d\u0648\u0631\u0629 \u062d\u0648\u0644 \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u060c \u0627\u0644\u062a\u064a \u062a\u0636\u0639 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0641\u064a \u0642\u0644\u0628 \u0627\u0644\u0639\u0645\u0644\u064a\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629 \u0648\u062a\u062f\u064a\u0631 \u0627\u0644\u0645\u0639\u0644\u0651\u0645 \u0641\u064a \u062f\u0648\u0631 \u0627\u0644\u0645\u064a\u0633\u0631\u060c \u062a\u0646\u0633\u0628 \u0625\u0644\u0649:",B.a7Z,0,"\u0631\u0648\u062c\u0631\u0632\u060c \u0631\u0627\u0626\u062f \u0627\u0644\u0645\u062f\u0631\u0633\u0629 \u0627\u0644\u0625\u0646\u0633\u0627\u0646\u064a\u0629\u060c \u064a\u0631\u0649 \u0623\u0646 \u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0644\u0641\u0639\u0627\u0644 \u064a\u062a\u062d\u0642\u0642 \u062d\u064a\u0646 \u064a\u0643\u0648\u0646 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0645\u0631\u0643\u0632 \u0627\u0644\u0627\u0647\u062a\u0645\u0627\u0645 \u0641\u064a \u0645\u0646\u0627\u062e \u0645\u0646 \u0627\u0644\u062b\u0642\u0629 \u0648\u0627\u0644\u0642\u0628\u0648\u0644.","\xab\u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0627\u062a \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0629\xbb")
