B.ar6=new A.c("\u0646\u0638\u0631\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0627\u062a \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0629",null,"\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0627\u0644\u0628\u0646\u0627\u0626\u064a\u0629 \u062a\u0633\u062a\u0646\u062f \u0641\u064a \u062c\u0648\u0647\u0631\u0647\u0627 \u0625\u0644\u0649 \u062a\u0635\u0648\u0631:",B.a_0,1,"\u0627\u0644\u0628\u0646\u0627\u0626\u064a\u0629 (\u0627\u0644\u0645\u062a\u0623\u062b\u0631\u0629 \u0628\u0628\u064a\u0627\u062c\u064a\u0647): \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0628\u0646\u0627\u0621 \u0646\u0634\u0637 \u0644\u0645\u0639\u0627\u0631\u0641\u0647 \u0639\u0628\u0631 \u0627\u0644\u062a\u0645\u062b\u0644\u0627\u062a \u0648\u0627\u0644\u062a\u0641\u0627\u0639\u0644\u060c \u0648\u0627\u0644\u0645\u0639\u0644\u0651\u0645 \u0645\u0646\u0638\u0645 \u0644\u0644\u0648\u0636\u0639\u064a\u0627\u062a.",u.c)
B.abo=s(["\u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0641\u0631\u062f\u064a \u0627\u0644\u0635\u0627\u0645\u062a \u0641\u0642\u0637","\u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a \u0648\u0627\u0644\u0644\u063a\u0629 \u0636\u0645\u0646 \u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u0646\u0645\u0648 \u0627\u0644\u0642\u0631\u064a\u0628","\u0627\u0644\u062a\u0639\u0632\u064a\u0632 \u0627\u0644\u0645\u062a\u0648\u0627\u0635\u0644 \u0644\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0627\u062a","\u0627\u0644\u0648\u0631\u0627\u062b\u0629 \u0641\u0642\u0637 \u062f\u0648\u0646 \u0627\u0644\u0645\u062d\u064a\u0637","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.amh=new A.c("\u0646\u0638\u0631\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0627\u062a \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0629",null,"\u0627\u0644\u0633\u0648\u0633\u0648\u0628\u0646\u0627\u0626\u064a\u0629 (\u0627\u0644\u0628\u0646\u0627\u0626\u064a\u0629 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a\u0629) \u062a\u0624\u0643\u062f \u0623\u0646 \u0627\u0644\u062a\u0639\u0644\u0645 \u064a\u062a\u0645 \u0639\u0628\u0631:",B.abo,1,"\u0627\u0644\u0633\u0648\u0633\u0648\u0628\u0646\u0627\u0626\u064a\u0629 \u0627\u0644\u0645\u0633\u062a\u0646\u062f\u0629 \u0625\u0644\u0649 \u0641\u064a\u063a\u0648\u062a\u0633\u0643\u064a: \u0627\u0644\u0645\u0639\u0627\u0631\u0641 \u062a\u064f\u0628\u0646\u0649 \u0627\u062c\u062a\u0645\u0627\u0639\u064a\u0627\u064b \u0639\u0628\u0631 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0648\u0627\u0644\u062d\u0648\u0627\u0631 \u0648\u0627\u0644\u062f\u0639\u0645 \u062f\u0627\u062e\u0644 \u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u0646\u0645\u0648 \u0627\u0644\u0642\u0631\u064a\u0628.",u.bz)
B.UR=s(["\u0645\u062c\u0645\u0648\u0639\u0629 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0627\u0644\u062a\u064a \u064a\u062d\u0641\u0638\u0647\u0627 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0639\u0646 \u0638\u0647\u0631 \u0642\u0644\u0628","\u0642\u062f\u0631\u0629 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0639\u0644\u0649 \u062a\u0648\u0638\u064a\u0641 \u0645\u062c\u0645\u0648\u0639\u0629 \u0645\u0646 \u0627\u0644\u0645\u0648\u0627\u0631\u062f (\u0645\u0639\u0627\u0631\u0641\u060c \u0645\u0647\u0627\u0631\u0627\u062a\u060c \u0645\u0648\u0627\u0642\u0641) \u0644\u062d\u0644 \u0648\u0636\u0639\u064a\u0629-\u0645\u0634\u0643\u0644","\u0639\u062f\u062f \u0627\u0644\u0646\u0642\u0637 \u0627\u0644\u062a\u064a \u064a\u062d\u0635\u0644 \u0639\u0644\u064a\u0647\u0627 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0641\u064a \u0627\u0644\u0627\u0645\u062a\u062d\u0627\u0646","\u0627\u0644\u0633\u0644\u0648\u0643\u0627\u062a \u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0629 \u0627\u0644\u062e\u0627\u0631\u062c\u064a\u0629 \u0641\u0642\u0637","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aq9=new A.c("\u0646\u0638\u0631\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0627\u062a \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0629",null,"\u0627\u0644\u0643\u0641\u0627\u064a\u0629 \u0641\u064a \u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0629 \u0628\u0627\u0644\u0643\u0641\u0627\u064a\u0627\u062a \u062a\u064f\u0639\u0631\u064e\u0651\u0641 \u0628\u0623\u0646\u0647\u0627:",B.UR,1,"\u0627\u0644\u0643\u0641\u0627\u064a\u0629 = \u062a\u0639\u0628\u0626\u0629 \u0627\u0644\u0645\u0648\u0627\u0631\u062f \u0627\u0644\u0645\u062a\u0639\u062f\u062f\u0629 (\u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0648\u0627\u0644\u0645\u0647\u0627\u0631\u0629 \u0648\u0627\u0644\u0645\u0648\u0642\u0641) \u0648\u062d\u0644\u0647\u0627 \u0644\u0648\u0636\u0639\u064a\u0629 \u0645\u0639\u0642\u062f\u0629 \u0641\u064a \u0633\u064a\u0627\u0642 \u062d\u0642\u064a\u0642\u064a.","\xab\u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0627\u062a \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0629\xbb")
