B.a0J=s(["\u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a \u0627\u0644\u0646\u0641\u0633\u064a\u0629 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 (\u0627\u0644\u0627\u0646\u062a\u0628\u0627\u0647\u060c \u0627\u0644\u0625\u062f\u0631\u0627\u0643\u060c \u0627\u0644\u0630\u0627\u0643\u0631\u0629\u060c \u0627\u0644\u0644\u063a\u0629)","\u0627\u0644\u0628\u0646\u064a\u0629 \u0627\u0644\u0639\u0638\u0645\u064a\u0629 \u0644\u0644\u062c\u0633\u0645","\u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0629 \u0641\u0642\u0637","\u0627\u0644\u0646\u0638\u0627\u0645 \u0627\u0644\u063a\u0630\u0627\u0626\u064a \u0627\u0644\u064a\u0648\u0645\u064a","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.anz=new A.c("\u0635\u0639\u0648\u0628\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0639\u0648\u0627\u0626\u0642\u0647",null,"\u0635\u0639\u0648\u0628\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0644\u0646\u0645\u0627\u0626\u064a\u0629 \u062a\u064f\u0639\u0631\u0641 \u0628\u0623\u0646\u0647\u0627 \u0627\u0636\u0637\u0631\u0627\u0628 \u0641\u064a:",B.a0J,0,"\u0635\u0639\u0648\u0628\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0644\u0646\u0645\u0627\u0626\u064a\u0629 \u0627\u0636\u0637\u0631\u0627\u0628 \u0641\u064a \u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a \u0627\u0644\u0646\u0641\u0633\u064a\u0629 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0627\u0644\u0644\u0627\u0632\u0645\u0629 \u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0631\u063a\u0645 \u0630\u0643\u0627\u0621 \u0639\u0627\u062f\u064a \u0648\u062d\u0648\u0627\u0633 \u0633\u0644\u064a\u0645\u0629.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\xbb")
B.a0t=s(["\u0635\u0639\u0648\u0628\u0629 \u0641\u064a \u0641\u0643 \u0627\u0644\u0631\u0645\u0648\u0632 \u0648\u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0648\u0627\u0644\u0631\u0628\u0637 \u0628\u064a\u0646 \u0627\u0644\u062d\u0631\u0648\u0641 \u0648\u0623\u0635\u0648\u0627\u062a\u0647\u0627","\u0635\u0639\u0648\u0628\u0629 \u0641\u064a \u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a \u0627\u0644\u062d\u0633\u0627\u0628\u064a\u0629 \u0641\u0642\u0637","\u0635\u0639\u0648\u0628\u0629 \u0641\u064a \u0627\u0644\u0633\u0628\u0627\u062d\u0629","\u0636\u0639\u0641 \u0641\u064a \u062d\u0627\u0633\u0629 \u0627\u0644\u0633\u0645\u0639","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aih=new A.c("\u0635\u0639\u0648\u0628\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0639\u0648\u0627\u0626\u0642\u0647",null,"\u0639\u0633\u0631 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 (\u0627\u0644\u062f\u064a\u0633\u0644\u0643\u0633\u064a\u0627) \u064a\u0638\u0647\u0631 \u0644\u062f\u0649 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0641\u064a \u0635\u0648\u0631\u0629:",B.a0t,0,"\u0627\u0644\u062f\u064a\u0633\u0644\u0643\u0633\u064a\u0627 \u0635\u0639\u0648\u0628\u0629 \u0642\u0631\u0627\u0621\u0629 \u062e\u0627\u0635\u0629 \u0628\u0627\u0644\u0641\u0643 \u0627\u0644\u0631\u0645\u0648\u0632 \u0648\u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0635\u0648\u062a\u064a\u0629 \u0631\u063a\u0645 \u0630\u0643\u0627\u0621 \u0639\u0627\u062f\u064a \u0648\u062a\u0645\u062f\u0631\u0633 \u0639\u0627\u062f\u064a.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\xbb")
B.a5a=s(["\u0635\u0639\u0648\u0628\u0629 \u0641\u064a \u0641\u0647\u0645 \u0627\u0644\u0623\u0639\u062f\u0627\u062f \u0648\u0625\u0646\u062c\u0627\u0632 \u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a \u0627\u0644\u062d\u0633\u0627\u0628\u064a\u0629","\u0635\u0639\u0648\u0628\u0629 \u0641\u064a \u0627\u0644\u062a\u0639\u0628\u064a\u0631 \u0627\u0644\u0643\u062a\u0627\u0628\u064a \u0641\u0642\u0637","\u0635\u0639\u0648\u0628\u0629 \u0641\u064a \u062d\u0641\u0638 \u0627\u0644\u0646\u0635\u0648\u0635 \u0627\u0644\u0634\u0639\u0631\u064a\u0629","\u0627\u0636\u0637\u0631\u0627\u0628 \u0641\u064a \u0627\u0644\u0643\u062a\u0627\u0628\u0629 \u0627\u0644\u064a\u062f\u0648\u064a\u0629 \u0641\u0642\u0637","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.ar9=new A.c("\u0635\u0639\u0648\u0628\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0639\u0648\u0627\u0626\u0642\u0647",null,"\u0639\u0633\u0631 \u0627\u0644\u062d\u0633\u0627\u0628 (\u0627\u0644\u062f\u064a\u0633\u0643\u0627\u0644\u0643\u0648\u0644\u064a\u0627) \u064a\u062a\u062c\u0644\u0649 \u0641\u064a:",B.a5a,0,"\u0627\u0644\u062f\u064a\u0633\u0643\u0627\u0644\u0643\u0648\u0644\u064a\u0627 \u0635\u0639\u0648\u0628\u0629 \u062e\u0627\u0635\u0629 \u0641\u064a \u0627\u0644\u0645\u0641\u0627\u0647\u064a\u0645 \u0627\u0644\u0639\u062f\u062f\u064a\u0629 \u0648\u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a \u0627\u0644\u062d\u0633\u0627\u0628\u064a\u0629 \u0648\u0627\u0644\u0639\u0644\u0627\u0642\u0627\u062a \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0629.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\xbb")
B.abL=s(["\u0636\u0639\u0641 \u0627\u0644\u062e\u0637 \u0648\u062a\u0634\u0648\u0647 \u0627\u0644\u062d\u0631\u0648\u0641 \u0648\u0635\u0639\u0648\u0628\u0629 \u0625\u0646\u062a\u0627\u062c \u0627\u0644\u0643\u062a\u0627\u0628\u0629 \u0628\u0634\u0643\u0644 \u0645\u0642\u0631\u0648\u0621","\u0635\u0639\u0648\u0628\u0629 \u0641\u064a \u0627\u0644\u0633\u0645\u0639","\u0636\u0639\u0641 \u0641\u064a \u0627\u0644\u0628\u0635\u0631","\u0635\u0639\u0648\u0628\u0629 \u0641\u064a \u0627\u0644\u062d\u0641\u0638 \u0627\u0644\u0635\u0648\u062a\u064a \u0641\u0642\u0637","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.anZ=new A.c("\u0635\u0639\u0648\u0628\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0639\u0648\u0627\u0626\u0642\u0647",null,"\u0639\u0633\u0631 \u0627\u0644\u0643\u062a\u0627\u0628\u0629 (\u0627\u0644\u062f\u064a\u0633\u063a\u0631\u0627\u0641\u064a\u0627) \u064a\u062a\u062c\u0644\u0649 \u0641\u064a:",B.abL,0,"\u0627\u0644\u062f\u064a\u0633\u063a\u0631\u0627\u0641\u064a\u0627 \u0627\u0636\u0637\u0631\u0627\u0628 \u0641\u064a \u0627\u0644\u0643\u062a\u0627\u0628\u0629 \u0627\u0644\u064a\u062f\u0648\u064a\u0629: \u0634\u0643\u0644 \u0627\u0644\u062d\u0631\u0648\u0641\u060c \u0627\u0644\u062a\u0646\u0627\u0633\u0642\u060c \u0627\u0644\u0627\u062a\u062c\u0627\u0647\u060c \u0648\u0627\u0644\u0625\u0646\u062a\u0627\u062c \u0627\u0644\u0643\u062a\u0627\u0628\u064a.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\xbb")
B.a4s=s(["\u0628\u0637\u0621 \u0627\u0644\u062a\u0639\u0644\u0645 \u064a\u0624\u062b\u0631 \u0639\u0644\u0649 \u062c\u0645\u064a\u0639 \u0627\u0644\u0645\u0648\u0627\u062f \u0628\u064a\u0646\u0645\u0627 \u0635\u0639\u0648\u0628\u0629 \u0627\u0644\u062a\u0639\u0644\u0645 \u062e\u0627\u0635\u0629 \u0628\u0645\u062c\u0627\u0644 \u0645\u062d\u062f\u062f \u063a\u0627\u0644\u0628\u0627\u064b","\u0635\u0639\u0648\u0628\u0629 \u0627\u0644\u062a\u0639\u0644\u0645 \u0623\u0633\u0631\u0639 \u0648\u0623\u0633\u0647\u0644 \u0641\u064a \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629","\u0628\u0637\u0621 \u0627\u0644\u062a\u0639\u0644\u0645 \u0646\u062a\u064a\u062c\u0629 \u0641\u0642\u0631 \u0627\u0644\u0648\u0627\u0644\u062f\u064a\u0646 \u062d\u0635\u0631\u0627\u064b","\u0644\u0627 \u0641\u0631\u0642 \u0628\u064a\u0646\u0647\u0645\u0627 \u0625\u0637\u0644\u0627\u0642\u0627\u064b","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.ajy=new A.c("\u0635\u0639\u0648\u0628\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0639\u0648\u0627\u0626\u0642\u0647",null,"\u0627\u0644\u0641\u0631\u0642 \u0627\u0644\u062c\u0648\u0647\u0631\u064a \u0628\u064a\u0646 \xab\u0628\u0637\u0621 \u0627\u0644\u062a\u0639\u0644\u0645\xbb \u0648\xab\u0635\u0639\u0648\u0628\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645\xbb \u0623\u0646:",B.a4s,0,"\u0628\u0637\u0621 \u0627\u0644\u062a\u0639\u0644\u0645 \u0636\u0639\u0641 \u0639\u0627\u0645 \u0641\u064a \u0648\u062a\u064a\u0631\u0629 \u0627\u0644\u062a\u0639\u0644\u0645 \u0628\u0643\u0644 \u0627\u0644\u0645\u0648\u0627\u062f\u060c \u0628\u064a\u0646\u0645\u0627 \u0635\u0639\u0648\u0628\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0636\u0637\u0631\u0627\u0628\u0627\u062a \u062e\u0627\u0635\u0629 \u0628\u0623\u0643\u0627\u062f\u064a\u0645\u064a\u0629/\u0646\u0645\u0627\u0626\u064a\u0629 \u0645\u062d\u062f\u062f\u0629.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\xbb")
B.SD=s(["\u0639\u0648\u0627\u0645\u0644 \u0639\u0635\u0628\u064a\u0629\u060c \u0648\u0631\u0627\u062b\u064a\u0629\u060c \u0648\u0628\u064a\u0626\u064a\u0629/\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0629","\u0644\u0648\u0646 \u0645\u0642\u0627\u0639\u062f \u0627\u0644\u0642\u0633\u0645 \u0641\u0642\u0637","\u062c\u0646\u0633 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0641\u0642\u0637","\u0641\u0635\u0648\u0644 \u0627\u0644\u0633\u0646\u0629 \u0641\u0642\u0637","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aks=new A.c("\u0635\u0639\u0648\u0628\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0639\u0648\u0627\u0626\u0642\u0647",null,"\u0645\u0646 \u0623\u0647\u0645 \u0627\u0644\u0639\u0648\u0627\u0645\u0644 \u0627\u0644\u0645\u0641\u0633\u0631\u0629 \u0644\u0635\u0639\u0648\u0628\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645:",B.SD,0,"\u062a\u062a\u062f\u0627\u062e\u0644 \u0639\u0648\u0627\u0645\u0644 \u0639\u0635\u0628\u064a\u0629 \u0648\u0638\u064a\u0641\u064a\u0629 \u0648\u0648\u0631\u0627\u062b\u064a\u0629 \u0645\u0639 \u0639\u0648\u0627\u0645\u0644 \u0628\u064a\u0626\u064a\u0629 (\u0645\u062d\u064a\u0637\u060c \u0637\u0631\u064a\u0642\u0629 \u062a\u062f\u0631\u064a\u0633\u060c \u0648\u0636\u0639 \u0623\u0633\u0631\u064a) \u0641\u064a \u0625\u062d\u062f\u0627\u062b \u0635\u0639\u0648\u0628\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\xbb")
B.a49=s(["\u0627\u0644\u0631\u0627\u0635\u062f \u0627\u0644\u0623\u0648\u0644 \u0648\u0627\u0644\u0645\u0644\u0627\u062d\u0638 \u0627\u0644\u0645\u0633\u062a\u0645\u0631 \u0644\u0633\u0644\u0648\u0643\u0627\u062a \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646","\u0627\u0644\u0637\u0628\u064a\u0628 \u0627\u0644\u0645\u062e\u062a\u0635 \u0627\u0644\u0645\u0639\u0627\u0644\u062c \u062d\u0635\u0631\u064a\u0627\u064b","\u0627\u0644\u0642\u0627\u0636\u064a \u0627\u0644\u062d\u0627\u0633\u0645 \u0641\u064a \u062a\u0635\u0646\u064a\u0641 \u0627\u0644\u0645\u062a\u0639\u0644\u0645","\u062c\u0647\u0629 \u062a\u0647\u0645\u0644 \u0627\u0644\u062a\u0639\u062b\u0631\u0627\u062a","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.ao_=new A.c("\u0635\u0639\u0648\u0628\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0639\u0648\u0627\u0626\u0642\u0647",null,"\u0641\u064a \u0627\u0644\u0643\u0634\u0641 \u0639\u0646 \u0635\u0639\u0648\u0628\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u062f\u0627\u062e\u0644 \u0627\u0644\u0642\u0633\u0645\u060c \u064a\u0644\u0639\u0628 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u062f\u0648\u0631:",B.a49,0,"\u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0645\u0631\u0627\u0642\u0628 \u0623\u0648\u0644 \u064a\u0631\u0635\u062f \u0627\u0644\u0639\u0644\u0627\u0645\u0627\u062a \u0639\u0628\u0631 \u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0629 \u0648\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u064a\u062d\u064a\u0644 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0625\u0644\u0649 \u0627\u0644\u0645\u062a\u062e\u0635\u0635\u064a\u0646 \u062f\u0648\u0646 \u0648\u0635\u0645.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\xbb")
B.Ve=s(["\u0623\u0641\u0643\u0627\u0631 \u0645\u0633\u0628\u0642\u0629 \u062e\u0627\u0637\u0626\u0629 \u062a\u0639\u064a\u0642 \u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0627\u0644\u062c\u062f\u064a\u062f\u0629 \u0625\u0646 \u0644\u0645 \u062a\u0633\u062a\u062b\u0645\u0631","\u0645\u0639\u0631\u0641\u0629 \u0635\u062d\u064a\u062d\u0629 \u0644\u0627 \u062a\u062d\u062a\u0627\u062c \u0625\u0644\u0649 \u062a\u0639\u062f\u064a\u0644","\u063a\u064a\u0627\u0628 \u062a\u0627\u0645 \u0644\u0623\u064a \u062a\u0635\u0648\u0631","\u062d\u0635\u064a\u0644\u0629 \u062a\u0645\u0627\u0631\u064a\u0646 \u0645\u062d\u0641\u0648\u0638\u0629","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
