B.amk=new A.c("\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0627\u0646",null,"\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0634\u062e\u064a\u0635\u064a \u064a\u064f\u0646\u062c\u0632 \u0639\u0627\u062f\u0629:",B.a1w,0,"\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0634\u062e\u064a\u0635\u064a \u0642\u0628\u0644\u064a: \u064a\u0631\u0635\u062f \u0627\u0644\u0645\u0643\u062a\u0633\u0628\u0627\u062a \u0648\u0627\u0644\u062a\u0645\u062b\u0644\u0627\u062a \u0627\u0644\u0642\u0628\u0644\u064a\u0629 \u0644\u0636\u0628\u0637 \u0646\u0642\u0637\u0629 \u0627\u0644\u0627\u0646\u0637\u0644\u0627\u0642 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\xbb")
B.a3f=s(["\u064a\u062c\u0631\u064a \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u062a\u0639\u0644\u0645 \u0628\u0647\u062f\u0641 \u062a\u0639\u062f\u064a\u0644\u0647 \u0648\u0636\u0628\u0637\u0647","\u064a\u062c\u0631\u064a \u0645\u0631\u0629 \u0648\u0627\u062d\u062f\u0629 \u0641\u064a \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u0648\u062d\u062f\u0629","\u064a\u0647\u062f\u0641 \u0625\u0644\u0649 \u0627\u0646\u062a\u0642\u0627\u0621 \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u0641\u0642\u0637","\u0644\u0627 \u064a\u062a\u0628\u0639\u0647 \u0623\u064a \u062f\u0639\u0645","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.ao4=new A.c("\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0627\u0646",null,"\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0643\u0648\u064a\u0646\u064a \u064a\u062a\u0645\u064a\u0632 \u0628\u0623\u0646\u0647:",B.a3f,0,"\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0643\u0648\u064a\u0646\u064a \u0645\u0631\u0627\u0641\u0642 \u0644\u0633\u064a\u0631\u0648\u0631\u0629 \u0627\u0644\u062a\u0639\u0644\u0645: \u064a\u0632\u0648\u062f \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0648\u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0628\u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0644\u0636\u0628\u0637 \u0627\u0644\u062a\u062f\u0631\u064a\u0633 \u0648\u0627\u0644\u062f\u0639\u0645.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\xbb")
B.a4H=s(["\u0625\u0635\u062f\u0627\u0631 \u062d\u0643\u0645 \u062e\u062a\u0627\u0645\u064a \u0639\u0644\u0649 \u062d\u0635\u064a\u0644\u0629 \u0627\u0644\u062a\u0639\u0644\u0645 \u0628\u0639\u062f \u0627\u0644\u0648\u062d\u062f\u0629 \u0623\u0648 \u0627\u0644\u062f\u0648\u0631\u0629","\u0643\u0634\u0641 \u0627\u0644\u0645\u0643\u062a\u0633\u0628\u0627\u062a \u0642\u0628\u0644 \u0627\u0644\u062a\u0639\u0644\u0645","\u062a\u0639\u062f\u064a\u0644 \u0633\u064a\u0631\u0648\u0631\u0629 \u0627\u0644\u062a\u0639\u0644\u0645 \u0623\u062b\u0646\u0627\u0621\u0647\u0627","\u062a\u0646\u0634\u064a\u0637 \u0627\u0644\u0642\u0633\u0645 \u0627\u0644\u062a\u0631\u0641\u064a\u0647\u064a","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.an2=new A.c("\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0627\u0646",null,"\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u0625\u062c\u0645\u0627\u0644\u064a (\u0627\u0644\u062e\u062a\u0627\u0645\u064a) \u0648\u0638\u064a\u0641\u062a\u0647 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629:",B.a4H,0,"\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u0625\u062c\u0645\u0627\u0644\u064a \u064a\u0642\u0639 \u0628\u0639\u062f \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a (\u0646\u0647\u0627\u064a\u0629 \u0648\u062d\u062f\u0629/\u062f\u0648\u0631\u0629/\u0633\u0646\u0629) \u0648\u064a\u0633\u0648\u063a \u0642\u0631\u0627\u0631\u0627\u062a \u0627\u0644\u0634\u0647\u0627\u062f\u0629 \u0648\u0627\u0644\u0627\u0646\u062a\u0642\u0627\u0644.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\xbb")
B.a58=s(["\u0627\u0644\u0642\u064a\u0627\u0633 \u0648\u0635\u0641 \u0643\u0645\u064a \u0628\u064a\u0646\u0645\u0627 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u064a\u0634\u0645\u0644 \u0648\u0635\u0641\u0627\u064b \u0648\u062d\u0643\u0645\u0627\u064b \u0642\u064a\u0645\u064a\u0627\u064b \u0648\u0642\u0631\u0627\u0631\u0627\u064b","\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0643\u0645\u064a \u0628\u064a\u0646\u0645\u0627 \u0627\u0644\u0642\u064a\u0627\u0633 \u062d\u0643\u0645 \u0642\u064a\u0645\u064a","\u0643\u0644\u0627\u0647\u0645\u0627 \u064a\u0639\u0646\u064a\u0627\u0646 \u0625\u0635\u062f\u0627\u0631 \u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u0641\u0642\u0637","\u0644\u0627 \u0641\u0631\u0642 \u0628\u064a\u0646\u0647\u0645\u0627","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.asq=new A.c("\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0627\u0646",null,"\u0627\u0644\u0641\u0631\u0642 \u0627\u0644\u062c\u0648\u0647\u0631\u064a \u0628\u064a\u0646 \xab\u0627\u0644\u0642\u064a\u0627\u0633\xbb \u0648\xab\u0627\u0644\u062a\u0642\u0648\u064a\u0645\xbb \u0623\u0646:",B.a58,0,"\u0627\u0644\u0642\u064a\u0627\u0633 \u0625\u0633\u0646\u0627\u062f \u0623\u0631\u0642\u0627\u0645 \u0644\u0644\u0638\u0627\u0647\u0631\u0629\u060c \u0623\u0645\u0627 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0641\u064a\u0636\u064a\u0641 \u0627\u0644\u062d\u0643\u0645 \u0639\u0644\u0649 \u0627\u0644\u0642\u064a\u0645\u0629 \u0648\u0627\u062a\u062e\u0627\u0630 \u0627\u0644\u0642\u0631\u0627\u0631 \u0627\u0644\u062a\u0631\u0628\u0648\u064a.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\xbb")
B.a75=s(["\u0623\u0646 \u064a\u0642\u0648\u0651\u0645 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u062a\u0639\u0644\u0645\u0627\u062a\u0647 \u0628\u0646\u0641\u0633\u0647 \u0648\u0641\u0642 \u0645\u0639\u0627\u064a\u064a\u0631 \u0648\u0627\u0636\u062d\u0629","\u0623\u0646 \u064a\u0642\u0648\u0651\u0645 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0646\u0641\u0633\u0647 \u0641\u0642\u0637","\u0623\u0646 \u064a\u0645\u0646\u062d \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0646\u0641\u0633\u0647 \u0627\u0644\u0646\u0642\u0637","\u0625\u0644\u063a\u0627\u0621 \u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0646\u0647\u0627\u0626\u064a\u0627\u064b","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.asl=new A.c("\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0627\u0646",null,"\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u0630\u0627\u062a\u064a (\u0627\u0644\u0645\u0631\u0627\u0642\u0628\u0629 \u0627\u0644\u0630\u0627\u062a\u064a\u0629) \u064a\u0639\u0646\u064a:",B.a75,0,"\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u0630\u0627\u062a\u064a \u064a\u0646\u0645\u064a \u0644\u062f\u0649 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0627\u0644\u0648\u0639\u064a \u0628\u062a\u0639\u0644\u0645\u0627\u062a\u0647 \u0648\u0636\u0628\u0637\u0647\u0627 \u0648\u062a\u0635\u062d\u064a\u062d \u0645\u0633\u0627\u0631\u0647\u0627 \u0648\u0641\u0642 \u0645\u0639\u0627\u064a\u064a\u0631 \u0645\u0628\u0644\u0648\u0631\u0629.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\xbb")
B.a0D=s(["\u0634\u0628\u0643\u0629 \u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0629\u060c \u0633\u0644\u0645 \u0627\u0644\u062a\u0642\u062f\u064a\u0631\u060c \u0648\u0631\u0642\u0629 \u0627\u0644\u0642\u064a\u0627\u062f\u0629","\u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631\u0627\u062a \u0627\u0644\u0648\u0631\u0642\u064a\u0629 \u0641\u0642\u0637","\u0627\u0644\u0628\u062d\u062b \u0639\u0644\u0649 \u0627\u0644\u0625\u0646\u062a\u0631\u0646\u062a","\u0627\u0644\u0648\u0627\u062c\u0628\u0627\u062a \u0627\u0644\u0645\u0646\u0632\u0644\u064a\u0629 \u0627\u0644\u062d\u0641\u0638\u064a\u0629 \u0641\u0642\u0637","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aic=new A.c("\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0627\u0646",null,"\u0645\u0646 \u0623\u062f\u0648\u0627\u062a \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0629 \u0627\u0644\u0645\u064a\u062f\u0627\u0646\u064a\u0629 \u0646\u062c\u062f:",B.a0D,0,"\u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0629 \u0627\u0644\u0645\u0646\u0638\u0645\u0629 \u062a\u0633\u062a\u062e\u062f\u0645 \u0634\u0628\u0643\u0627\u062a \u0648\u0633\u0644\u0627\u0644\u0645 \u062a\u0642\u062f\u064a\u0631 \u062a\u0642\u064a\u062f \u0627\u0644\u0633\u0644\u0648\u0643\u0627\u062a \u0648\u0627\u0644\u0645\u0648\u0627\u0642\u0641 \u0627\u0644\u062a\u0639\u0644\u0645\u064a\u0629.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\xbb")
B.a7l=s(["\u062a\u062c\u0645\u064a\u0639 \u0645\u0646\u0638\u0645 \u0644\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0648\u0623\u062f\u0627\u0621\u0627\u062a\u0647 \u064a\u0628\u0631\u0632 \u062a\u0642\u062f\u0645\u0647","\u0633\u062c\u0644 \u0639\u0642\u0648\u0628\u0627\u062a \u0627\u0644\u0642\u0633\u0645","\u0645\u0644\u0641 \u0627\u0644\u0623\u0631\u0634\u064a\u0641 \u0627\u0644\u0625\u062f\u0627\u0631\u064a \u0644\u0644\u0645\u0624\u0633\u0633\u0629","\u062f\u0641\u062a\u0631 \u0627\u0644\u0646\u0635\u0648\u0635 \u0627\u0644\u0642\u0631\u0627\u0626\u064a\u0629 \u0641\u0642\u0637","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.arX=new A.c("\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0627\u0646",null,"\u0645\u0644\u0641 \u0627\u0644\u0625\u0646\u062c\u0627\u0632 (Portfolio) \u0641\u064a \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0647\u0648:",B.a7l,0,"\u0645\u0644\u0641 \u0627\u0644\u0625\u0646\u062c\u0627\u0632 \u064a\u0648\u062b\u0642 \u0633\u064a\u0631\u0648\u0631\u0629 \u062a\u0639\u0644\u0645 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0648\u0623\u0639\u0645\u0627\u0644\u0647 \u0648\u0627\u0646\u0639\u0643\u0627\u0633\u0627\u062a\u0647 \u0627\u0644\u0630\u0627\u062a\u064a\u0629\u060c \u0648\u064a\u0639\u062a\u0645\u062f \u0641\u064a \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u0628\u062f\u064a\u0644.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\xbb")
B.aad=s(["\u062a\u062b\u0628\u064a\u062a \u0648\u0625\u063a\u0646\u0627\u0621 \u0645\u0643\u062a\u0633\u0628\u0627\u062a \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u0627\u0644\u0645\u062a\u0641\u0648\u0642\u064a\u0646","\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u062a\u0639\u062b\u0631\u0627\u062a \u0627\u0644\u0634\u062f\u064a\u062f\u0629 \u0641\u0642\u0637","\u0645\u0639\u0627\u0642\u0628\u0629 \u0627\u0644\u0645\u062a\u0639\u062b\u0631\u064a\u0646","\u0625\u0644\u063a\u0627\u0621 \u0627\u0644\u062f\u0631\u0648\u0633 \u0627\u0644\u062c\u062f\u064a\u062f\u0629","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.akb=new A.c("\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0627\u0646",null,"\u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u062a\u062b\u0628\u064a\u062a\u064a \u064a\u0647\u062f\u0641 \u0623\u0633\u0627\u0633\u0627\u064b \u0625\u0644\u0649:",B.aad,0,"\u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u062a\u062b\u0628\u064a\u062a\u064a \u0645\u0648\u062c\u0647 \u0644\u0645\u0646 \u0627\u0643\u062a\u0633\u0628\u0648\u0627 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a \u0644\u062a\u062b\u0628\u064a\u062a\u0647\u0627 \u0648\u0625\u063a\u0646\u0627\u0626\u0647\u0627 \u0648\u062a\u0639\u0645\u064a\u0642\u0647\u0627\u060c \u0645\u0642\u0627\u0628\u0644 \u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u0627\u0633\u062a\u062f\u0631\u0627\u0643\u064a \u0644\u0644\u0645\u062a\u0639\u062b\u0631\u064a\u0646.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\xbb")
B.a4u=s(["\u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0644\u0645 \u064a\u0633\u062a\u0648\u0639\u0628\u0648\u0627 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a \u0627\u0644\u0645\u0642\u0631\u0631\u0629","\u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u0627\u0644\u0645\u062a\u0641\u0648\u0642\u064a\u0646 \u0641\u0642\u0637","\u062c\u0645\u064a\u0639 \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u062f\u0648\u0646 \u062a\u0645\u064a\u064a\u0632","\u0623\u0648\u0644\u064a\u0627\u0621 \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aif=new A.c("\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0627\u0646",null,"\u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u0627\u0633\u062a\u062f\u0631\u0627\u0643\u064a \u0645\u0648\u062c\u0651\u0647 \u0625\u0644\u0649:",B.a4u,0,"\u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u0627\u0633\u062a\u062f\u0631\u0627\u0643\u064a \u064a\u0639\u0627\u0644\u062c \u062a\u0639\u062b\u0631\u0627\u062a \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u0641\u064a \u0627\u0644\u0645\u0643\u062a\u0633\u0628\u0627\u062a \u063a\u064a\u0631 \u0627\u0644\u0645\u062d\u0642\u0642\u0629 \u0628\u0639\u062f \u0627\u0644\u062a\u0634\u062e\u064a\u0635.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\xbb")
B.a_a=s(["\u062d\u0627\u062c\u064a\u0627\u062a \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u0627\u0644\u0645\u062d\u062f\u062f\u0629 \u0628\u0627\u0644\u062a\u0634\u062e\u064a\u0635","\u0627\u0644\u062a\u0648\u0632\u064a\u0639 \u0627\u0644\u0639\u0634\u0648\u0627\u0626\u064a \u0644\u0644\u062d\u0635\u0635","\u0631\u063a\u0628\u0629 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0627\u0644\u062e\u0627\u0635\u0629 \u0641\u0642\u0637","\u0639\u062f\u062f \u0623\u0648\u0644\u064a\u0627\u0621 \u0627\u0644\u0623\u0645\u0648\u0631 \u0627\u0644\u062d\u0627\u0636\u0631\u064a\u0646","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.amf=new A.c("\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0627\u0646",null,"\u062a\u064f\u0646\u0638\u0645 \u062d\u0635\u0635 \u0627\u0644\u062f\u0639\u0645 \u062f\u0627\u062e\u0644 \u0627\u0644\u063a\u0644\u0627\u0641 \u0627\u0644\u0632\u0645\u0646\u064a \u0627\u0644\u0623\u0633\u0628\u0648\u0639\u064a \u0648\u0641\u0642:",B.a_a,0,"\u062d\u0635\u0635 \u0627\u0644\u062f\u0639\u0645 \u062a\u064f\u0628\u0631\u0645\u062c \u0641\u064a \u0625\u0637\u0627\u0631 \u0627\u0644\u063a\u0644\u0627\u0641 \u0627\u0644\u0632\u0645\u0646\u064a \u0648\u062a\u062f\u0628\u0631 \u0648\u0641\u0642 \u0646\u062a\u0627\u0626\u062c \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0634\u062e\u064a\u0635\u064a \u0648\u0627\u0644\u062a\u0643\u0648\u064a\u0646\u064a.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\xbb")
