B.amI=new A.c("\u0627\u0644\u0625\u0635\u0644\u0627\u062d \u0627\u0644\u062a\u0631\u0628\u0648\u064a \u0648\u0627\u0644\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629",null,"\u0645\u0624\u0633\u0633\u0629 \u062d\u0633\u0627\u0628 \u062a\u062d\u062f\u064a \u0627\u0644\u0623\u0644\u0641\u064a\u0629 MCA/MCC \u0647\u064a:",B.a9o,1,"\u0645\u0624\u0633\u0633\u0629 \u062a\u062d\u062f\u064a \u0627\u0644\u0623\u0644\u0641\u064a\u0629 MCA/MCC \u0648\u0643\u0627\u0644\u0629 \u0623\u0645\u0631\u064a\u0643\u064a\u0629 \u0623\u0628\u0631\u0645\u062a \u0634\u0631\u0627\u0643\u0629 \u0645\u0639 \u0627\u0644\u062d\u0643\u0648\u0645\u0629 \u0627\u0644\u0645\u063a\u0631\u0628\u064a\u0629 \u0633\u0646\u0629 2016.",u.A)
B.a8E=s(["\u0645\u0634\u0631\u0648\u0639 \u0627\u0644\u0645\u0624\u0633\u0633\u0629 \u0627\u0644\u0645\u0646\u062f\u0645\u062c","\u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a","\u0645\u062d\u0627\u0631\u0628\u0629 \u0627\u0644\u0647\u062f\u0631 \u0627\u0644\u0645\u062f\u0631\u0633\u064a","\u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u0645\u0648\u0627\u0632\u064a\u0629 \u0648\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0629","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.apd=new A.c("\u0627\u0644\u0625\u0635\u0644\u0627\u062d \u0627\u0644\u062a\u0631\u0628\u0648\u064a \u0648\u0627\u0644\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629",null,'\u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0645\u0624\u0633\u0633\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629 \u064a\u0633\u062a\u0647\u062f\u0641 \u0628\u0631\u0646\u0627\u0645\u062c "\u0627\u0644\u0625\u0639\u062f\u0627\u062f\u064a\u0627\u062a \u0627\u0644\u0631\u0627\u0626\u062f\u0629" \u0627\u0644\u0645\u062c\u0627\u0644\u0627\u062a \u0627\u0644\u062a\u0627\u0644\u064a\u0629 \u0645\u0627 \u0639\u062f\u0627 :',B.a8E,0,"\u0645\u0634\u0631\u0648\u0639 \u0627\u0644\u0645\u0624\u0633\u0633\u0629 \u0627\u0644\u0645\u0646\u062f\u0645\u062c \u0644\u064a\u0633 \u0645\u0646 \u0627\u0644\u0645\u062c\u0627\u0644\u0627\u062a \u0627\u0644\u062a\u064a \u064a\u0633\u062a\u0647\u062f\u0641\u0647\u0627 \u0628\u0631\u0646\u0627\u0645\u062c \u0627\u0644\u0625\u0639\u062f\u0627\u062f\u064a\u0627\u062a \u0627\u0644\u0631\u0627\u0626\u062f\u0629.",u.A)
B.a2S=s(["\u062a\u0646\u062a\u0645\u064a \u0627\u0644\u0645\u0624\u0633\u0633\u0629 \u0644\u0646\u0641\u0633 \u0627\u0644\u062d\u0648\u0636 \u0627\u0644\u0645\u062f\u0631\u0633\u064a \u0644\u0644\u0645\u062f\u0627\u0631\u0633 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a\u0629 \u0627\u0644\u0631\u0627\u0626\u062f\u0629","\u0627\u0646\u062e\u0641\u0627\u0636 \u0646\u0633\u0628 \u0627\u0644\u0647\u062f\u0631 \u0627\u0644\u0645\u062f\u0631\u0633\u064a","\u0627\u0631\u062a\u0641\u0627\u0639 \u0646\u0633\u0628 \u0627\u0644\u0646\u062c\u0627\u062d","\u0627\u0644\u0645\u062a\u0648\u0641\u0631\u0629 \u0639\u0644\u0649 \u0642\u0627\u0639\u0627\u062a \u062c\u064a\u0646\u064a GENIE","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.ala=new A.c("\u0627\u0644\u0625\u0635\u0644\u0627\u062d \u0627\u0644\u062a\u0631\u0628\u0648\u064a \u0648\u0627\u0644\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629",null,"\u0645\u0646 \u0628\u064a\u0646 \u0645\u0639\u0627\u064a\u064a\u0631 \u0627\u0646\u062a\u0642\u0627\u0621 \u0627\u0644\u062b\u0627\u0646\u0648\u064a\u0627\u062a \u0627\u0644\u062a\u0623\u0647\u064a\u0644\u064a\u0629 \u0644\u0644\u062a\u0645\u064a\u0632 \u0641\u064a \u0625\u0637\u0627\u0631 \u0627\u0644\u062a\u062c\u0631\u064a\u0628",B.a2S,0,"\u0645\u0646 \u0645\u0639\u0627\u064a\u064a\u0631 \u0627\u0646\u062a\u0642\u0627\u0621 \u0627\u0644\u062b\u0627\u0646\u0648\u064a\u0627\u062a \u0627\u0644\u062a\u0623\u0647\u064a\u0644\u064a\u0629 \u0644\u0644\u062a\u0645\u064a\u0632 \u0623\u0646 \u062a\u0646\u062a\u0645\u064a \u0644\u0646\u0641\u0633 \u0627\u0644\u062d\u0648\u0636 \u0627\u0644\u0645\u062f\u0631\u0633\u064a \u0644\u0644\u0645\u062f\u0627\u0631\u0633 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a\u0629 \u0627\u0644\u0631\u0627\u0626\u062f\u0629.",u.A)
B.a7C=s(["\u0625\u062f\u0645\u0627\u062c \u0627\u0644\u062a\u0646\u0634\u064a\u0637 \u0641\u064a \u0633\u0644\u0643 \u0627\u0644\u0625\u062c\u0627\u0632\u0629 \u0641\u064a \u0627\u0644\u062a\u0631\u0628\u064a\u0629","\u0625\u0628\u0631\u0627\u0645 \u0634\u0631\u0627\u0643\u0629 \u0645\u0639 \u062c\u0645\u0639\u064a\u0627\u062a \u0645\u062e\u062a\u0635\u0629","\u062a\u0643\u0648\u064a\u0646 \u0627\u0644\u0623\u0633\u0627\u062a\u0630\u0629 \u0641\u064a \u0645\u062c\u0627\u0644 \u0627\u0644\u062a\u0646\u0634\u064a\u0637 \u0627\u0644\u062a\u0631\u0628\u0648\u064a","\u0627\u0644\u0646\u0647\u0648\u0636 \u0628\u0639\u0645\u0644 \u0627\u0644\u0623\u0646\u062f\u064a\u0629 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0629","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.amT=new A.c("\u0627\u0644\u0625\u0635\u0644\u0627\u062d \u0627\u0644\u062a\u0631\u0628\u0648\u064a \u0648\u0627\u0644\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629",null,"\u062d\u062f\u062f \u0623\u0647\u0645 \u0625\u062c\u0631\u0627\u0621 \u0633\u064a\u062a\u0645 \u0627\u062a\u062e\u0627\u0630\u0647 \u0644\u0644\u0646\u0647\u0648\u0636 \u0628\u0627\u0644\u062a\u0646\u0634\u064a\u0637 \u0627\u0644\u062a\u0631\u0628\u0648\u064a \u0628\u0627\u0644\u0645\u0624\u0633\u0633\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629",B.a7C,0,"\u0623\u0647\u0645 \u0625\u062c\u0631\u0627\u0621 \u0644\u0644\u0646\u0647\u0648\u0636 \u0628\u0627\u0644\u062a\u0646\u0634\u064a\u0637 \u0627\u0644\u062a\u0631\u0628\u0648\u064a \u0647\u0648 \u0625\u062f\u0645\u0627\u062c \u0627\u0644\u062a\u0646\u0634\u064a\u0637 \u0641\u064a \u0633\u0644\u0643 \u0627\u0644\u0625\u062c\u0627\u0632\u0629 \u0641\u064a \u0627\u0644\u062a\u0631\u0628\u064a\u0629.",u.A)
B.Sz=s(["\u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u0645\u0648\u0627\u0632\u064a\u0629",u.g,"\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u0623\u0646\u062f\u064a\u0629 \u0648\u0627\u0644\u0645\u0646\u0627\u0633\u0628\u0627\u062a \u0627\u0644\u062f\u064a\u0646\u064a\u0629 \u0648\u0627\u0644\u0648\u0637\u0646\u064a\u0629 \u0648\u0627\u0644\u062f\u0648\u0644\u064a\u0629","\u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u064a \u0644\u0627 \u062a\u0631\u062a\u0628\u0637 \u0628\u0639\u0645\u0644\u064a\u0629 \u0627\u0644\u062a\u062f\u0631\u064a\u0633 \u0627\u0644\u0635\u0641\u064a \u0627\u0644\u064a\u0648\u0645\u064a (\u0627\u0644\u0628\u0646\u0627\u0621\u060c \u0627\u0644\u062a\u0642\u0648\u064a\u0645\u060c \u0627\u0644\u062f\u0639\u0645...)","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
