B.arG=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u0635\u062d\u064a\u062d \u0644\u0645\u0631\u0627\u062d\u0644 \u0625\u0646\u062c\u0627\u0632 \u0645\u0647\u0627\u0631\u0629 \u0627\u0644\u062a\u0639\u0628\u064a\u0631 \u0627\u0644\u0643\u062a\u0627\u0628\u064a \u0639\u0628\u0631 \u0627\u0644\u062d\u0635\u0635 \u0627\u0644\u0623\u0631\u0628\u0639 \u0647\u0648:",B.a9T,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u0646\u0645\u0630\u062c\u0629 \u2190 \u0627\u0644\u0625\u0646\u062c\u0627\u0632 (\u0645\u062d\u0627\u0648\u0644\u0629 \u0623\u0648\u0644\u0649) \u2190 \u0627\u0644\u0645\u0631\u0627\u062c\u0639\u0629 \u0648\u0627\u0644\u062a\u0646\u0642\u064a\u062d \u2190 \u0627\u0644\u062a\u0635\u062d\u064a\u062d \u0648\u0627\u0644\u0639\u0631\u0636.",u.C)
B.a1G=s(["\u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0623\u0647\u062f\u0627\u0641 \u0648\u062a\u0648\u0632\u064a\u0639 \u0627\u0644\u0645\u0647\u0627\u0645 \u0628\u064a\u0646 \u0627\u0644\u0645\u062c\u0645\u0648\u0639\u0627\u062a.","\u0627\u0644\u0625\u0646\u062c\u0627\u0632 \u0627\u0644\u0623\u0648\u0644\u064a \u0648\u062a\u062c\u0645\u064a\u0639 \u0627\u0644\u0648\u062b\u0627\u0626\u0642 \u0648\u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a.","\u062a\u062a\u0645\u0629 \u0627\u0644\u0625\u0646\u062c\u0627\u0632 \u0648\u0635\u064a\u0627\u063a\u062a\u0647 \u0648\u062a\u062c\u0648\u064a\u062f\u0647.","\u0627\u0644\u062a\u062c\u0648\u064a\u062f \u0627\u0644\u0646\u0647\u0627\u0626\u064a \u0648\u0627\u0644\u0639\u0631\u0636."],t.s)
B.aq6=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u062a\u062e\u0635\u0635 \u0627\u0644\u062d\u0635\u0629 \u0627\u0644\u0631\u0627\u0628\u0639\u0629 \u0645\u0646 \u0645\u0634\u0631\u0648\u0639 \u0627\u0644\u0648\u062d\u062f\u0629 \u0644\u0640:",B.a1G,3,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u062a\u062c\u0648\u064a\u062f \u0627\u0644\u0646\u0647\u0627\u0626\u064a \u0648\u0627\u0644\u0639\u0631\u0636.",u.C)
B.Ub=s(["\u062a\u0642\u062f\u064a\u0645 \u0645\u0648\u0627\u0636\u064a\u0639 \u0645\u0639\u0642\u062f\u0629 \u0641\u064a \u0627\u0644\u0638\u0648\u0627\u0647\u0631 \u0627\u0644\u0644\u063a\u0648\u064a\u0629.","\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645 \u0648\u0627\u0644\u062a\u0648\u0644\u064a\u0641 \u0648\u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u062a\u0648\u062c\u064a\u0647.","\u0625\u062c\u0631\u0627\u0621 \u0627\u0644\u0627\u0645\u062a\u062d\u0627\u0646\u0627\u062a \u0627\u0644\u0648\u0637\u0646\u064a\u0629 \u0648\u0627\u0644\u0625\u0634\u0647\u0627\u062f\u064a\u0629.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.all=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u064a\u064f\u062e\u0635\u0635 \u0627\u0644\u0623\u0633\u0628\u0648\u0639 \u0627\u0644\u062e\u0627\u0645\u0633 \u0645\u0646 \u0643\u0644 \u0648\u062d\u062f\u0629 \u062f\u0631\u0627\u0633\u064a\u0629 \u0641\u064a \u062a\u0646\u0638\u064a\u0645 \u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u062f\u0631\u0627\u0633\u064a\u0629 \u0644\u0640:",B.Ub,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645 \u0648\u0627\u0644\u062a\u0648\u0644\u064a\u0641 \u0648\u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u062a\u0648\u062c\u064a\u0647.",u.C)
B.acj=s(["\u0634\u0628\u0643\u0629 \u0627\u0644\u0645\u0641\u0631\u062f\u0627\u062a \u0648\u062a\u0648\u0644\u064a\u062f \u0627\u0644\u0645\u0639\u0627\u062c\u0645.","\u0635\u064a\u0627\u063a\u0629 \u0627\u0644\u062a\u0648\u0642\u0639\u0627\u062a \u0628\u0646\u0627\u0621\u064b \u0639\u0644\u0649 \u0627\u0644\u0645\u0634\u064a\u0631\u0627\u062a \u0627\u0644\u062a\u0631\u0643\u064a\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u0635\u0631\u064a\u0629 (\u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0648\u0627\u0644\u0635\u0648\u0631\u0629).","\u0639\u0627\u0626\u0644\u0629 \u0627\u0644\u0643\u0644\u0645\u0629 \u0648\u0627\u0644\u0627\u0634\u062a\u0642\u0627\u0642 \u0627\u0644\u0635\u0631\u0641\u064a.","\u0645\u0644\u062e\u0635 \u0627\u0644\u0646\u0635 \u0627\u0644\u0641\u0643\u0631\u064a."],t.s)
B.aoF=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u062a\u064a \u062a\u064f\u0639\u062a\u0645\u062f \u0642\u0628\u064a\u0644 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0644\u0627\u0633\u062a\u0643\u0634\u0627\u0641 \u0627\u0644\u0645\u0648\u0636\u0648\u0639 \u062a\u0639\u062a\u0645\u062f \u0639\u0644\u0649:",B.acj,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0635\u064a\u0627\u063a\u0629 \u0627\u0644\u062a\u0648\u0642\u0639\u0627\u062a \u0628\u0646\u0627\u0621\u064b \u0639\u0644\u0649 \u0627\u0644\u0645\u0634\u064a\u0631\u0627\u062a \u0627\u0644\u062a\u0631\u0643\u064a\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u0635\u0631\u064a\u0629 (\u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0648\u0627\u0644\u0635\u0648\u0631\u0629).",u.C)
B.Zj=s(["\u0642\u0631\u0627\u0621\u0629 \u0623\u0633\u0631\u0639 \u062a\u0644\u0645\u064a\u0630 \u0641\u064a \u0627\u0644\u0641\u0635\u0644 \u0644\u064a\u0642\u062a\u062f\u064a \u0628\u0647 \u0628\u0627\u0642\u064a \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630.","\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0627\u0644\u062c\u0647\u0631\u064a\u0629 \u0627\u0644\u0645\u062a\u0623\u0646\u064a\u0629 \u0648\u0627\u0644\u0645\u062a\u0645\u062b\u0644\u0629 \u0644\u0644\u0645\u0639\u0646\u0649 \u0644\u062a\u0643\u0648\u0646 \u0645\u0639\u064a\u0627\u0631\u0627\u064b \u064a\u064f\u0642\u062a\u062f\u0649 \u0628\u0647.","\u0642\u0631\u0627\u0621\u0629 \u062c\u0645\u064a\u0639 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0641\u064a \u0648\u0642\u062a \u0648\u0627\u062d\u062f \u0628\u0635\u0648\u062a \u0645\u0631\u062a\u0641\u0639.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.ar_=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u0645\u0642\u0635\u0648\u062f \u0628\u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0646\u0645\u0630\u062c\u064a\u0629 \u0641\u064a \u062d\u0635\u0635 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0647\u0648:",B.Zj,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0627\u0644\u062c\u0647\u0631\u064a\u0629 \u0627\u0644\u0645\u062a\u0623\u0646\u064a\u0629 \u0648\u0627\u0644\u0645\u062a\u0645\u062b\u0644\u0629 \u0644\u0644\u0645\u0639\u0646\u0649 \u0644\u062a\u0643\u0648\u0646 \u0645\u0639\u064a\u0627\u0631\u0627\u064b \u064a\u064f\u0642\u062a\u062f\u0649 \u0628\u0647.",u.C)
B.a8G=s(["\u062a\u0642\u062f\u064a\u0645 \u0642\u0648\u0627\u0639\u062f \u0627\u0644\u0625\u0639\u0631\u0627\u0628 \u0627\u0644\u0635\u0631\u064a\u062d\u0629 \u062f\u0648\u0646 \u0623\u0645\u062b\u0644\u0629.","\u062a\u0645\u0631\u064a\u0631 \u0627\u0644\u0638\u0627\u0647\u0631\u0629 \u0627\u0644\u0644\u063a\u0648\u064a\u0629 \u0628\u0634\u0643\u0644 \u0636\u0645\u0646\u064a \u0648\u0645\u062f\u0645\u062c \u0641\u064a \u0627\u0644\u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u062f\u0648\u0646 \u062a\u0635\u0631\u064a\u062d \u0628\u0627\u0644\u0642\u0627\u0639\u062f\u0629.","\u0625\u0644\u063a\u0627\u0621 \u0627\u0644\u0638\u0648\u0627\u0647\u0631 \u0627\u0644\u0644\u063a\u0648\u064a\u0629 \u0646\u0647\u0627\u0626\u064a\u0627\u064b \u0645\u0646 \u0627\u0644\u062a\u062e\u0637\u064a\u0637.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.arN=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u0627\u0633\u062a\u0636\u0645\u0627\u0631 \u0641\u064a \u062a\u062f\u0631\u064a\u0633 \u0627\u0644\u0638\u0648\u0627\u0647\u0631 \u0627\u0644\u0644\u063a\u0648\u064a\u0629 \u0628\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a \u0627\u0644\u0623\u0648\u0644\u0649 \u0645\u0646 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a \u064a\u0639\u0646\u064a:",B.a8G,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u0645\u0631\u064a\u0631 \u0627\u0644\u0638\u0627\u0647\u0631\u0629 \u0627\u0644\u0644\u063a\u0648\u064a\u0629 \u0628\u0634\u0643\u0644 \u0636\u0645\u0646\u064a \u0648\u0645\u062f\u0645\u062c \u0641\u064a \u0627\u0644\u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u062f\u0648\u0646 \u062a\u0635\u0631\u064a\u062d \u0628\u0627\u0644\u0642\u0627\u0639\u062f\u0629.",u.C)
B.Yx=s(["\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0623\u0648\u0644 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a.","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u062b\u0627\u0644\u062b \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a.","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a.","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u062e\u0627\u0645\u0633 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a."],t.s)
B.aqM=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u062a\u0635\u0631\u064a\u062d \u0628\u0627\u0644\u0638\u0648\u0627\u0647\u0631 \u0627\u0644\u0644\u063a\u0648\u064a\u0629 (\u0635\u0631\u0641 \u0648\u062a\u062d\u0648\u064a\u0644\u060c \u062a\u0631\u0627\u0643\u064a\u0628\u060c \u0625\u0645\u0644\u0627\u0621) \u0641\u064a \u0647\u064a\u0643\u0644\u0629 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u064a\u0628\u062f\u0623 \u0631\u0633\u0645\u064a\u0627\u064b \u0645\u0646:",B.Yx,2,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a.",u.C)
B.a3H=s(["\u064a\u064f\u0648\u0638\u0641 \u0644\u062e\u062f\u0645\u0629 \u0648\u0638\u064a\u0641\u0629 \u0645\u0633\u062a\u0642\u0628\u0644\u064a\u0651\u0629 \u0644\u0644\u062a\u0644\u0645\u064a\u0630.","\u064a\u064f\u0648\u0638\u0641 \u0644\u0627\u0633\u062a\u062b\u0645\u0627\u0631 \u0638\u0648\u0627\u0647\u0631 \u0644\u063a\u0648\u064a\u0629 \u0648\u0645\u062c\u0627\u0644\u064a\u0629 \u0645\u062d\u062f\u062f\u0629 \u0628\u0637\u0631\u064a\u0642\u0629 \u0645\u062f\u0645\u062c\u0629 \u0645\u0639 \u0627\u0644\u0641\u0647\u0645.","\u064a\u064f\u0643\u062a\u0628 \u0628\u0623\u0633\u0644\u0648\u0628 \u0625\u062f\u0627\u0631\u064a \u0648\u0631\u0633\u0645\u064a \u0641\u0642\u0637.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aqy=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u064a\u064f\u0633\u0645\u0649 \u0627\u0644\u0646\u0635 \u0627\u0644\u0648\u0638\u064a\u0641\u064a \u0628\u0647\u0630\u0627 \u0627\u0644\u0627\u0633\u0645 \u0644\u0623\u0646\u0647:",B.a3H,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u064a\u064f\u0648\u0638\u0641 \u0644\u0627\u0633\u062a\u062b\u0645\u0627\u0631 \u0638\u0648\u0627\u0647\u0631 \u0644\u063a\u0648\u064a\u0629 \u0648\u0645\u062c\u0627\u0644\u064a\u0629 \u0645\u062d\u062f\u062f\u0629 \u0628\u0637\u0631\u064a\u0642\u0629 \u0645\u062f\u0645\u062c\u0629 \u0645\u0639 \u0627\u0644\u0641\u0647\u0645.",u.C)
B.a98=s(["\u062d\u0635\u0629 \u0648\u0627\u062d\u062f\u0629 \u0641\u064a \u0627\u0644\u0633\u0646\u0629.","4 \u062d\u0635\u0635 \u0628\u0648\u0627\u0642\u0639 \u062d\u0635\u0629 \u0641\u064a \u0643\u0644 \u0623\u0633\u0628\u0648\u0639 \u0645\u0646 \u0623\u0633\u0627\u0628\u064a\u0639 \u0625\u0631\u0633\u0627\u0621 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a.","\u0623\u0633\u0628\u0648\u0639 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645 \u0641\u0642\u0637.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.ap7=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u062a\u064f\u0642\u062f\u0645 \u0627\u0644\u0645\u0647\u0627\u0631\u0629 \u0627\u0644\u0648\u0627\u062d\u062f\u0629 \u0641\u064a \u0645\u0643\u0648\u0646 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0645\u0633\u062a\u0631\u0633\u0644\u0629 \u0639\u0644\u0649 \u0645\u062f\u0649:",B.a98,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: 4 \u062d\u0635\u0635 \u0628\u0648\u0627\u0642\u0639 \u062d\u0635\u0629 \u0641\u064a \u0643\u0644 \u0623\u0633\u0628\u0648\u0639 \u0645\u0646 \u0623\u0633\u0627\u0628\u064a\u0639 \u0625\u0631\u0633\u0627\u0621 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a.",u.C)
B.a_i=s(["\u0635\u064a\u0627\u063a\u0629 \u062a\u0648\u0642\u0639\u0627\u062a \u062d\u0648\u0644 \u0627\u0644\u0646\u0635 \u0642\u0628\u0644 \u0642\u0631\u0627\u0621\u062a\u0647.","\u0627\u0644\u0628\u062d\u062b \u0639\u0646 \u0645\u0634\u062a\u0642\u0627\u062a \u0627\u0644\u0643\u0644\u0645\u0629 \u0645\u0646 \u0646\u0641\u0633 \u0627\u0644\u062c\u0630\u0631 \u0627\u0644\u0644\u063a\u0648\u064a \u0644\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0631\u0635\u064a\u062f \u0627\u0644\u0645\u0639\u062c\u0645\u064a.","\u062a\u062d\u062f\u064a\u062f \u0623\u0636\u062f\u0627\u062f \u0627\u0644\u0645\u0631\u0627\u062f\u0641\u0627\u062a \u0627\u0644\u0644\u063a\u0648\u064a\u0629 \u0641\u0642\u0637.","\u0625\u0639\u0631\u0627\u0628 \u0627\u0644\u0643\u0644\u0645\u0629 \u0625\u0639\u0631\u0627\u0628\u0627\u064b \u062a\u0627\u0645\u0627\u064b."],t.s)
B.amS=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a",'\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 "\u0639\u0627\u0626\u0644\u0629 \u0627\u0644\u0643\u0644\u0645\u0629" \u062a\u0647\u062f\u0641 \u0628\u0627\u0644\u0623\u0633\u0627\u0633 \u0625\u0644\u0649:',B.a_i,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0628\u062d\u062b \u0639\u0646 \u0645\u0634\u062a\u0642\u0627\u062a \u0627\u0644\u0643\u0644\u0645\u0629 \u0645\u0646 \u0646\u0641\u0633 \u0627\u0644\u062c\u0630\u0631 \u0627\u0644\u0644\u063a\u0648\u064a \u0644\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0631\u0635\u064a\u062f \u0627\u0644\u0645\u0639\u062c\u0645\u064a.",u.C)
B.ZH=s(["\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0648\u0627\u0644\u0625\u0646\u062c\u0627\u0632.","\u0645\u0631\u062d\u0644\u0629 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u0637\u0644\u0627\u0642 / \u0627\u0644\u062a\u0645\u0647\u064a\u062f.","\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062a\u0639\u062f\u064a\u0644 \u0627\u0644\u0646\u0647\u0627\u0626\u064a.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.as4=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u0645\u062d\u0648\u0631 \u0627\u0644\u062b\u0627\u0646\u064a: \u0647\u0646\u062f\u0633\u0629 \u0627\u0644\u062c\u0630\u0627\u0630\u0629 \u0648\u0645\u0631\u0627\u062d\u0644 \u0628\u0646\u0627\u0621 \u0627\u0644\u062f\u0631\u0633 \u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u0641\u064a \u0647\u064a\u0643\u0644\u0629 \u0623\u064a \u062c\u0630\u0627\u0630\u0629 \u062f\u0631\u0633 \u062a\u0646\u062a\u0645\u064a \u0644\u0645\u062f\u062e\u0644 \u0627\u0644\u0648\u0636\u0639\u064a\u0627\u062a \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a\u0629 \u0647\u064a:",B.ZH,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0645\u0631\u062d\u0644\u0629 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u0637\u0644\u0627\u0642 / \u0627\u0644\u062a\u0645\u0647\u064a\u062f.",u.C)
B.a5s=s(["\u0648\u0636\u0639 \u0627\u0644\u0639\u0644\u0627\u0645\u0627\u062a \u0648\u0627\u0644\u062f\u0631\u062c\u0627\u062a \u0644\u0644\u062a\u0644\u0627\u0645\u064a\u0630.","\u0625\u062d\u062f\u0627\u062b \u0635\u0631\u0627\u0639 \u0645\u0639\u0631\u0641\u064a \u0648\u062a\u0634\u062e\u064a\u0635 \u0627\u0644\u0645\u0643\u062a\u0633\u0628\u0627\u062a \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0648\u0627\u0644\u0631\u0628\u0637 \u0628\u0627\u0644\u062f\u0631\u0633 \u0627\u0644\u062c\u062f\u064a\u062f.","\u0625\u0639\u0637\u0627\u0621 \u0642\u0627\u0639\u062f\u0629 \u0627\u0644\u062f\u0631\u0633 \u0645\u0643\u062a\u0648\u0628\u0629 \u0639\u0644\u0649 \u0627\u0644\u0633\u0628\u0648\u0631\u0629 \u0644\u0646\u0642\u0644\u0647\u0627.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.akO=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a",'\u062a\u0633\u062a\u0647\u062f\u0641 "\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u0637\u0644\u0627\u0642" \u0641\u064a \u0628\u062f\u0627\u064a\u0629 \u0627\u0644\u062f\u0631\u0633 \u0628\u0634\u0643\u0644 \u0631\u0626\u064a\u0633\u064a:',B.a5s,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0625\u062d\u062f\u0627\u062b \u0635\u0631\u0627\u0639 \u0645\u0639\u0631\u0641\u064a \u0648\u062a\u0634\u062e\u064a\u0635 \u0627\u0644\u0645\u0643\u062a\u0633\u0628\u0627\u062a \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0648\u0627\u0644\u0631\u0628\u0637 \u0628\u0627\u0644\u062f\u0631\u0633 \u0627\u0644\u062c\u062f\u064a\u062f.",u.C)
B.Ty=s(["\u0646\u0642\u0644 \u0627\u0644\u0642\u0627\u0639\u062f\u0629 \u0627\u0644\u0645\u0643\u062a\u0648\u0628\u0629 \u0641\u064a \u0627\u0644\u0643\u062a\u0627\u0628 \u0627\u0644\u0645\u062f\u0631\u0633\u064a \u0645\u0628\u0627\u0634\u0631\u0629.","\u0639\u0631\u0636 \u0627\u0644\u0634\u0648\u0627\u0647\u062f\u060c \u0642\u0631\u0627\u0621\u062a\u0647\u0627\u060c \u062a\u062d\u0644\u064a\u0644\u0647\u0627\u060c \u0627\u0644\u0645\u0648\u0627\u0632\u0646\u0629 \u0628\u064a\u0646\u0647\u0627 \u0644\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0627\u0633\u062a\u0646\u062a\u0627\u062c \u0627\u0644\u0642\u0627\u0639\u062f\u0629.","\u0625\u0646\u062c\u0627\u0632 \u062a\u0645\u0627\u0631\u064a\u0646 \u0643\u062a\u0627\u0628\u064a\u0629 \u062f\u0627\u0639\u0645\u0629 \u0641\u064a \u062f\u0641\u062a\u0631 \u0627\u0644\u062f\u0639\u0645.","\u062a\u0635\u062d\u064a\u062d \u0623\u062e\u0637\u0627\u0621 \u0627\u0644\u0641\u0631\u0636 \u0627\u0644\u0645\u0646\u0632\u0644\u064a."],t.s)
B.asK=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a",'\u0645\u0631\u062d\u0644\u0629 "\u0627\u0644\u0628\u0646\u0627\u0621 \u0648\u0627\u0644\u0627\u0643\u062a\u0634\u0627\u0641" \u0641\u064a \u062f\u0631\u0633 \u0627\u0644\u0638\u0648\u0627\u0647\u0631 \u0627\u0644\u0644\u063a\u0648\u064a\u0629 \u062a\u0634\u0645\u0644 \u0623\u0646\u0634\u0637\u0629:',B.Ty,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0639\u0631\u0636 \u0627\u0644\u0634\u0648\u0627\u0647\u062f\u060c \u0642\u0631\u0627\u0621\u062a\u0647\u0627\u060c \u062a\u062d\u0644\u064a\u0644\u0647\u0627\u060c \u0627\u0644\u0645\u0648\u0627\u0632\u0646\u0629 \u0628\u064a\u0646\u0647\u0627 \u0644\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0627\u0633\u062a\u0646\u062a\u0627\u062c \u0627\u0644\u0642\u0627\u0639\u062f\u0629.",u.C)
B.YJ=s(["\u0628\u0646\u0627\u0621 \u0645\u0641\u0647\u0648\u0645 \u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a \u062c\u062f\u064a\u062f \u0644\u0645 \u064a\u0633\u0628\u0642 \u0634\u0631\u062d\u0647.","\u0646\u0642\u0644 \u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0645\u0646 \u0627\u0644\u0641\u0647\u0645 \u0627\u0644\u0646\u0638\u0631\u064a \u0625\u0644\u0649 \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0639\u0628\u0631 \u062a\u0645\u0627\u0631\u064a\u0646 \u0648\u0625\u0646\u062c\u0627\u0632\u0627\u062a \u0645\u062d\u062f\u062f\u0629.","\u0635\u064a\u0627\u063a\u0629 \u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u0648\u062d\u062f\u0629 \u0627\u0644\u0642\u0627\u062f\u0645\u0629.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.amo=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a",'\u0627\u0644\u0647\u062f\u0641 \u0627\u0644\u0631\u0626\u064a\u0633\u064a \u0645\u0646 \u0645\u0631\u062d\u0644\u0629 "\u0627\u0644\u062a\u062b\u0628\u064a\u062a \u0648\u0627\u0644\u062a\u0637\u0628\u064a\u0642" \u062f\u0627\u062e\u0644 \u0627\u0644\u0641\u0635\u0644 \u0647\u0648:',B.YJ,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0646\u0642\u0644 \u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0645\u0646 \u0627\u0644\u0641\u0647\u0645 \u0627\u0644\u0646\u0638\u0631\u064a \u0625\u0644\u0649 \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0639\u0628\u0631 \u062a\u0645\u0627\u0631\u064a\u0646 \u0648\u0625\u0646\u062c\u0627\u0632\u0627\u062a \u0645\u062d\u062f\u062f\u0629.",u.C)
B.T9=s(["\u0627\u0644\u0628\u0646\u0627\u0621 \u2190 \u0627\u0644\u062a\u0645\u0647\u064a\u062f \u2190 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u2190 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645.","\u0627\u0644\u062a\u0645\u0647\u064a\u062f \u0648\u0627\u0644\u0648\u0636\u0639 \u0627\u0644\u0645\u0634\u0643\u0644 \u2190 \u0627\u0644\u0628\u0646\u0627\u0621 \u0648\u0627\u0644\u0627\u0643\u062a\u0634\u0627\u0641 \u2190 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0648\u0627\u0644\u062a\u062b\u0628\u064a\u062a \u2190 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645.","\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u2190 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u2190 \u0627\u0644\u0628\u0646\u0627\u0621 \u2190 \u0627\u0644\u062a\u0645\u0647\u064a\u062f.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.as6=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a \u0627\u0644\u0639\u0644\u0645\u064a \u0627\u0644\u0645\u0646\u0637\u0642\u064a \u0644\u0645\u0642\u0627\u0637\u0639 \u062c\u0630\u0627\u0630\u0629 \u062f\u0631\u0633 \u0644\u063a\u0648\u064a \u0647\u0648:",B.T9,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u062a\u0645\u0647\u064a\u062f \u0648\u0627\u0644\u0648\u0636\u0639 \u0627\u0644\u0645\u0634\u0643\u0644 \u2190 \u0627\u0644\u0628\u0646\u0627\u0621 \u0648\u0627\u0644\u0627\u0643\u062a\u0634\u0627\u0641 \u2190 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0648\u0627\u0644\u062a\u062b\u0628\u064a\u062a \u2190 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645.",u.C)
B.abC=s(["\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0648\u0645\u0644\u0627\u062d\u0638\u0629 \u0627\u0644\u0635\u0648\u0631 \u0641\u0642\u0637.","\u0627\u0644\u062a\u0633\u0645\u064a\u0639 \u0627\u0644\u0623\u0648\u0644\u064a \u0644\u0644\u0623\u0633\u062a\u0627\u0630 \u0648\u0635\u064a\u0627\u063a\u0629 \u0627\u0644\u062a\u0648\u0642\u0639\u0627\u062a.","\u0627\u0644\u0627\u0633\u062a\u062b\u0645\u0627\u0631\u060c \u0627\u0644\u062a\u0631\u0643\u064a\u0628\u060c \u0627\u0644\u062a\u0644\u062e\u064a\u0635\u060c \u0648\u0625\u0628\u062f\u0627\u0621 \u0627\u0644\u0631\u0623\u064a \u0641\u064a \u0642\u0636\u0627\u064a\u0627 \u0627\u0644\u0646\u0635.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.ama=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a",'\u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u064a \u062a\u064f\u0646\u062c\u0632 \u062e\u0644\u0627\u0644 \u0645\u0631\u062d\u0644\u0629 "\u0645\u0627 \u0628\u0639\u062f \u0627\u0644\u0642\u0631\u0627\u0621\u0629" \u0641\u064a \u0645\u0643\u0648\u0646 \u0627\u0644\u0646\u0635 \u0627\u0644\u0648\u0638\u064a\u0641\u064a \u062a\u0634\u0645\u0644:',B.abC,2,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0627\u0633\u062a\u062b\u0645\u0627\u0631\u060c \u0627\u0644\u062a\u0631\u0643\u064a\u0628\u060c \u0627\u0644\u062a\u0644\u062e\u064a\u0635\u060c \u0648\u0625\u0628\u062f\u0627\u0621 \u0627\u0644\u0631\u0623\u064a \u0641\u064a \u0642\u0636\u0627\u064a\u0627 \u0627\u0644\u0646\u0635.",u.C)
B.Vw=s(["\u0639\u0627\u0645\u0629 \u062c\u062f\u0627\u064b \u0648\u0634\u0627\u0645\u0644\u0629 \u0644\u062c\u0645\u064a\u0639 \u0633\u0646\u0648\u0627\u062a \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a.","\u0645\u062d\u062f\u062f\u0629\u060c \u062f\u0642\u064a\u0642\u0629\u060c \u0648\u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u0645\u0644\u0627\u062d\u0638\u0629 \u0648\u0627\u0644\u0642\u064a\u0627\u0633 \u0644\u062f\u0649 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u062e\u0644\u0627\u0644 \u0627\u0644\u062d\u0635\u0629.","\u062e\u0627\u0635\u0629 \u0628\u0645\u0647\u0627\u0645 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0641\u0642\u0637 \u062f\u0648\u0646 \u0627\u0644\u062a\u0644\u0645\u064a\u0630.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.ajC=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a",'\u062a\u064f\u0635\u0627\u063a "\u0627\u0644\u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u062a\u0639\u0644\u0645\u064a\u0629" \u0641\u064a \u0627\u0644\u062c\u0630\u0627\u0630\u0629 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0629 \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646:',B.Vw,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0645\u062d\u062f\u062f\u0629\u060c \u062f\u0642\u064a\u0642\u0629\u060c \u0648\u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u0645\u0644\u0627\u062d\u0638\u0629 \u0648\u0627\u0644\u0642\u064a\u0627\u0633 \u0644\u062f\u0649 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u062e\u0644\u0627\u0644 \u0627\u0644\u062d\u0635\u0629.",u.C)
B.ZI=s(["\u0627\u062e\u062a\u0628\u0627\u0631 \u062d\u0641\u0638 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0644\u0644\u0645\u0641\u0627\u0647\u064a\u0645 \u0639\u0646 \u0638\u0647\u0631 \u0642\u0644\u0628.","\u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0645\u062f\u0649 \u062a\u062d\u0642\u0642 \u0627\u0644\u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u0645\u0633\u0637\u0631\u0629 \u0648\u0631\u0635\u062f \u0627\u0644\u062a\u0639\u062b\u0631\u0627\u062a \u0627\u0644\u0641\u0648\u0631\u064a\u0629 \u0644\u0645\u0639\u0627\u0644\u062c\u062a\u0647\u0627.","\u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u062d\u0633\u0628 \u0627\u0644\u062a\u0641\u0648\u0642 \u0627\u0644\u062f\u0631\u0627\u0633\u064a.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.arA=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u062a\u064f\u062e\u0635\u0635 \u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0642\u0648\u064a\u0645\u064a\u0629 \u0627\u0644\u0645\u062f\u0645\u062c\u0629 \u0641\u064a \u062e\u062a\u0627\u0645 \u0627\u0644\u062d\u0635\u0629 \u0627\u0644\u062f\u0631\u0627\u0633\u064a\u0629 \u0644\u0640:",B.ZI,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0645\u062f\u0649 \u062a\u062d\u0642\u0642 \u0627\u0644\u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u0645\u0633\u0637\u0631\u0629 \u0648\u0631\u0635\u062f \u0627\u0644\u062a\u0639\u062b\u0631\u0627\u062a \u0627\u0644\u0641\u0648\u0631\u064a\u0629 \u0644\u0645\u0639\u0627\u0644\u062c\u062a\u0647\u0627.",u.C)
B.SH=s(["\u063a\u0627\u064a\u0629 \u0645\u0633\u062a\u0647\u062f\u0641\u0629 \u0628\u062d\u062f \u0630\u0627\u062a\u0647\u0627 \u064a\u062c\u0628 \u062a\u062d\u0635\u064a\u0644\u0647\u0627.","\u0623\u062f\u0627\u0629 \u0645\u0639\u064a\u0646\u0629 \u0648\u0645\u0633\u0627\u0639\u062f\u0629 \u0644\u062a\u064a\u0633\u064a\u0631 \u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u0641\u0647\u0648\u0645 \u0648\u062a\u062d\u0642\u064a\u0642 \u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u062f\u0631\u0633.","\u0639\u0646\u0635\u0631 \u0634\u0643\u0644\u064a \u0644\u0627 \u0639\u0644\u0627\u0642\u0629 \u0644\u0647 \u0628\u0637\u0628\u064a\u0639\u0629 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.ajN=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u0648\u0633\u064a\u0644\u0629 \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a\u0629 \u0627\u0644\u0645\u062f\u0631\u062c\u0629 \u0641\u064a \u0627\u0644\u062c\u0630\u0627\u0630\u0629 \u062a\u064f\u0639\u062a\u0628\u0631:",B.SH,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0623\u062f\u0627\u0629 \u0645\u0639\u064a\u0646\u0629 \u0648\u0645\u0633\u0627\u0639\u062f\u0629 \u0644\u062a\u064a\u0633\u064a\u0631 \u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u0641\u0647\u0648\u0645 \u0648\u062a\u062d\u0642\u064a\u0642 \u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u062f\u0631\u0633.",u.C)
B.a1o=s(["\u0645\u0647\u0627\u0645 \u0645\u062f\u064a\u0631 \u0627\u0644\u0645\u0624\u0633\u0633\u0629 \u0648\u0645\u0647\u0627\u0645 \u0627\u0644\u0645\u0641\u062a\u0634 \u0627\u0644\u062a\u0631\u0628\u0648\u064a.","\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u0645\u062f\u0631\u0633 (\u0627\u0644\u062a\u0648\u062c\u064a\u0647 \u0648\u0627\u0644\u062a\u064a\u0633\u064a\u0631) \u0648\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 (\u0627\u0644\u0628\u0646\u0627\u0621 \u0648\u0627\u0644\u0625\u0646\u062c\u0627\u0632).","\u063a\u0644\u0627\u0641 \u0627\u0644\u062d\u0635\u0629 \u0648\u0627\u0644\u063a\u0644\u0627\u0641 \u0627\u0644\u0632\u0645\u0646\u064a \u0627\u0644\u0633\u0646\u0648\u064a.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.akw=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u062a\u0648\u0632\u064a\u0639 \u0627\u0644\u0623\u062f\u0648\u0627\u0631 \u062f\u0627\u062e\u0644 \u0627\u0644\u062c\u0630\u0627\u0630\u0629 \u064a\u0642\u062a\u0636\u064a \u0627\u0644\u0641\u0635\u0644 \u0627\u0644\u062f\u0642\u064a\u0642 \u0628\u064a\u0646:",B.a1o,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u0645\u062f\u0631\u0633 (\u0627\u0644\u062a\u0648\u062c\u064a\u0647 \u0648\u0627\u0644\u062a\u064a\u0633\u064a\u0631) \u0648\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 (\u0627\u0644\u0628\u0646\u0627\u0621 \u0648\u0627\u0644\u0625\u0646\u062c\u0627\u0632).",u.C)
B.TO=s(["\u0627\u0644\u0646\u0638\u0631\u064a\u0629 \u0627\u0644\u0633\u0644\u0648\u0643\u064a\u0629 (\u0628\u0627\u0641\u0644\u0648\u0641/\u0633\u0643\u064a\u0646\u0631).","\u0627\u0644\u0646\u0638\u0631\u064a\u0629 \u0627\u0644\u0628\u0646\u0627\u0626\u064a\u0629 (\u062c\u0627\u0646 \u0628\u064a\u0627\u062c\u064a\u0647).","\u0627\u0644\u0646\u0638\u0631\u064a\u0629 \u0627\u0644\u062c\u064a\u0634\u0637\u0644\u062a\u064a\u0629 (\u0643\u0648\u0647\u0644\u0631).","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aqL=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u0645\u062d\u0648\u0631 \u0627\u0644\u062b\u0627\u0644\u062b: \u0646\u0638\u0631\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627\u062a \u0627\u0644\u062d\u062f\u064a\u062b\u0629 \u0627\u0644\u0646\u0638\u0631\u064a\u0629 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0629 \u0627\u0644\u062a\u064a \u062a\u0639\u062a\u0628\u0631 \u0623\u0646 \u0627\u0644\u062a\u0639\u0644\u0645 \u064a\u062d\u062f\u062b \u0646\u062a\u064a\u062c\u0629 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0628\u064a\u0646 \u0627\u0644\u0630\u0627\u062a \u0648\u0627\u0644\u0645\u062d\u064a\u0637 \u0639\u0628\u0631 \u0639\u0645\u0644\u064a\u062a\u064a \u0627\u0644\u062a\u0645\u062b\u0644 \u0648\u0627\u0644\u0645\u0644\u0627\u0621\u0645\u0629 \u0647\u064a:",B.TO,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0646\u0638\u0631\u064a\u0629 \u0627\u0644\u0628\u0646\u0627\u0626\u064a\u0629 (\u062c\u0627\u0646 \u0628\u064a\u0627\u062c\u064a\u0647).",u.C)
B.a2D=s(["\u0627\u0644\u0628\u0646\u0627\u0626\u064a\u0629.","\u0627\u0644\u0633\u0648\u0633\u064a\u0648-\u0628\u0646\u0627\u0626\u064a\u0629 (\u0641\u064a\u063a\u0648\u062a\u0633\u0643\u064a).","\u0627\u0644\u0633\u0644\u0648\u0643\u064a\u0629 \u0627\u0644\u0643\u0644\u0627\u0633\u064a\u0643\u064a\u0629.","\u0627\u0644\u0645\u0639\u0631\u0641\u064a\u0629 \u0627\u0644\u0630\u0627\u062a\u064a\u0629."],t.s)
B.alI=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a",'\u0645\u0641\u0647\u0648\u0645 "\u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u0646\u0645\u0648 \u0627\u0644\u0642\u0631\u064a\u0628" (Zone of Proximal Development) \u064a\u0646\u062a\u0645\u064a \u0644\u0644\u0646\u0638\u0631\u064a\u0629:',B.a2D,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0633\u0648\u0633\u064a\u0648-\u0628\u0646\u0627\u0626\u064a\u0629 (\u0641\u064a\u063a\u0648\u062a\u0633\u0643\u064a).",u.C)
B.Ye=s(["\u0627\u0644\u062c\u064a\u0634\u0637\u0644\u062a\u064a\u0629.","\u0627\u0644\u0633\u0644\u0648\u0643\u064a\u0629 \u0627\u0644\u0625\u062c\u0631\u0627\u0626\u064a\u0629.","\u0627\u0644\u0628\u0646\u0627\u0626\u064a\u0629 \u0627\u0644\u0631\u0627\u062f\u064a\u0643\u0627\u0644\u064a\u0629.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.al3=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u062a\u0639\u0644\u0645 \u0628\u0627\u0644\u0627\u0633\u062a\u0628\u0635\u0627\u0631 \u0648\u0627\u0644\u0625\u062f\u0631\u0627\u0643 \u0627\u0644\u0643\u0644\u064a \u0644\u0644\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0645\u0639\u0642\u062f\u0629 \u0645\u0646 \u0645\u0628\u0627\u062f\u0626 \u0627\u0644\u0646\u0638\u0631\u064a\u0629:",B.Ye,0,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u062c\u064a\u0634\u0637\u0644\u062a\u064a\u0629.",u.C)
B.a8i=s(["\u0627\u0644\u0647\u062f\u0641 \u0627\u0644\u0625\u062c\u0631\u0627\u0626\u064a.","\u0627\u0644\u0643\u0641\u0627\u064a\u0629.","\u0627\u0644\u0645\u0647\u0627\u0631\u0629 \u0627\u0644\u0628\u0633\u064a\u0637\u0629.","\u0627\u0644\u062a\u0645\u062b\u0644\u0627\u062a \u0627\u0644\u0642\u0628\u064a\u0644\u064a\u0629."],t.s)
B.ajs=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a",'\u0627\u0644\u0645\u0641\u0647\u0648\u0645 \u0627\u0644\u0630\u064a \u064a\u064f\u0639\u0628\u0631 \u0639\u0646 "\u0627\u0644\u0642\u062f\u0631\u0629 \u0639\u0644\u0649 \u062a\u0639\u0628\u0626\u0629 \u0645\u062c\u0645\u0648\u0639\u0629 \u0645\u062f\u0645\u062c\u0629 \u0645\u0646 \u0627\u0644\u0645\u0648\u0627\u0631\u062f \u0644\u062d\u0644 \u0648\u0636\u0639\u064a\u0629 \u0645\u0634\u0643\u0644\u0629" \u0647\u0648:',B.a8i,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0643\u0641\u0627\u064a\u0629.",u.C)
B.XC=s(["\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0627\u0644\u0645\u0634\u0631\u0648\u0639.","\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0627\u0644\u0641\u0627\u0631\u0642\u064a\u0629.","\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0627\u0644\u0639\u0642\u062f.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.anD=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0627\u0644\u062a\u064a \u062a\u0642\u0648\u0645 \u0639\u0644\u0649 \u0645\u0631\u0627\u0639\u0627\u0629 \u0627\u0644\u0641\u0631\u0648\u0642 \u0627\u0644\u0641\u0631\u062f\u064a\u0629 \u0628\u064a\u0646 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0648\u062a\u0646\u0648\u064a\u0639 \u0645\u0633\u0627\u0631\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u062f\u0627\u062e\u0644 \u0627\u0644\u0641\u0635\u0644 \u0647\u064a:",B.XC,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0627\u0644\u0641\u0627\u0631\u0642\u064a\u0629.",u.C)
B.a4I=s(["\u0633\u0644\u0648\u0643 \u0633\u0644\u0628\u064a \u064a\u062c\u0628 \u0645\u0639\u0627\u0642\u0628\u0629 \u0627\u0644\u062a\u0644\u0645\u064a\u0630 \u0639\u0644\u064a\u0647 \u0641\u0648\u0631\u0627\u064b.","\u0645\u0624\u0634\u0631 \u0625\u064a\u062c\u0627\u0628\u064a \u064a\u0646\u0628\u063a\u064a \u0627\u0633\u062a\u062b\u0645\u0627\u0631\u0647 \u0643\u0634\u0627\u0647\u062f \u0639\u0644\u0649 \u0633\u064a\u0631\u0648\u0631\u0629 \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u0639\u0631\u0641\u0629.","\u062f\u0644\u064a\u0644 \u0642\u0627\u0637\u0639 \u0639\u0644\u0649 \u0639\u062f\u0645 \u0635\u0644\u0627\u062d\u064a\u0629 \u0627\u0644\u0645\u0642\u0631\u0631 \u0627\u0644\u062f\u0631\u0627\u0633\u064a.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aos=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u062a\u0639\u062a\u0628\u0631 \u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0627\u0644\u062e\u0637\u0623 \u0623\u0646 \u0623\u062e\u0637\u0627\u0621 \u0627\u0644\u0645\u062a\u0639\u0644\u0645:",B.a4I,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0645\u0624\u0634\u0631 \u0625\u064a\u062c\u0627\u0628\u064a \u064a\u0646\u0628\u063a\u064a \u0627\u0633\u062a\u062b\u0645\u0627\u0631\u0647 \u0643\u0634\u0627\u0647\u062f \u0639\u0644\u0649 \u0633\u064a\u0631\u0648\u0631\u0629 \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u0639\u0631\u0641\u0629.",u.C)
B.a8k=s(["\u0633\u0647\u0644\u0629 \u0648\u0628\u0633\u064a\u0637\u0629 \u064a\u0645\u0643\u0646 \u062d\u0644\u0647\u0627 \u0645\u0628\u0627\u0634\u0631\u0629 \u062f\u0648\u0646 \u062a\u0641\u0643\u064a\u0631.","\u0645\u0639\u0642\u062f\u0629 \u0648\u0630\u0627\u062a \u0645\u0639\u0646\u0649 \u0644\u0644\u0645\u062a\u0639\u0644\u0645 \u0648\u062a\u062a\u062d\u062f\u0649 \u0642\u062f\u0631\u0627\u062a\u0647 \u0648\u062a\u0633\u062a\u062f\u0639 \u062a\u0639\u0628\u0626\u0629 \u0627\u0644\u0645\u0648\u0627\u0631\u062f.","\u0645\u0633\u062a\u062d\u064a\u0644\u0629 \u0627\u0644\u062d\u0644 \u0644\u0628\u064a\u0627\u0646 \u0636\u0639\u0641 \u0627\u0644\u0645\u062a\u0639\u0644\u0645.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.amc=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a",'\u0645\u0646 \u0634\u0631\u0648\u0637 "\u0627\u0644\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0645\u0634\u0643\u0644\u0629" \u0627\u0644\u0641\u0639\u0627\u0644\u0629 \u0641\u064a \u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0629 \u0628\u0627\u0644\u0643\u0641\u0627\u064a\u0627\u062a \u0623\u0646 \u062a\u0643\u0648\u0646:',B.a8k,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0645\u0639\u0642\u062f\u0629 \u0648\u0630\u0627\u062a \u0645\u0639\u0646\u0649 \u0644\u0644\u0645\u062a\u0639\u0644\u0645 \u0648\u062a\u062a\u062d\u062f\u0649 \u0642\u062f\u0631\u0627\u062a\u0647 \u0648\u062a\u0633\u062a\u062f\u0639 \u062a\u0639\u0628\u0626\u0629 \u0627\u0644\u0645\u0648\u0627\u0631\u062f.",u.C)
B.WD=s(["\u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0645\u0633\u062a\u0642\u0644\u0629 \u2190 \u0627\u0644\u0646\u0645\u0630\u062c\u0629 \u2190 \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0645\u0648\u062c\u0647\u0629.","\u0627\u0644\u0646\u0645\u0630\u062c\u0629 (\u0627\u0644\u0634\u0631\u062d \u0627\u0644\u0645\u0628\u0627\u0634\u0631) \u2190 \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0645\u0648\u062c\u0647\u0629 \u2190 \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0645\u0633\u062a\u0642\u0644\u0629.","\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u0625\u062c\u0645\u0627\u0644\u064a \u2190 \u0627\u0644\u0646\u0645\u0630\u062c\u0629 \u2190 \u0627\u0644\u062a\u0645\u0647\u064a\u062f.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.ato=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a",'\u0623\u0633\u0644\u0648\u0628 "\u0627\u0644\u062a\u062f\u0631\u064a\u0633 \u0627\u0644\u0635\u0631\u064a\u062d" (Explicit Teaching) \u064a\u062a\u0643\u0648\u0646 \u0628\u0627\u0644\u062a\u0631\u062a\u064a\u0628 \u0645\u0646 \u062e\u0637\u0648\u0627\u062a:',B.WD,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0646\u0645\u0630\u062c\u0629 (\u0627\u0644\u0634\u0631\u062d \u0627\u0644\u0645\u0628\u0627\u0634\u0631) \u2190 \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0645\u0648\u062c\u0647\u0629 \u2190 \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0645\u0633\u062a\u0642\u0644\u0629.",u.C)
B.a1j=s(["\u062a\u0635\u0646\u064a\u0641 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u062d\u0633\u0628 \u0627\u0644\u0633\u0646 \u0648\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u062f\u0631\u0627\u0633\u064a \u0627\u0644\u0646\u0638\u0627\u0645\u064a.","\u062a\u0634\u062e\u064a\u0635 \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0641\u0639\u0644\u064a \u0644\u0644\u0645\u062a\u0639\u0644\u0645 \u0641\u064a \u0627\u0644\u0645\u0647\u0627\u0631\u0627\u062a \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0648\u062a\u0643\u064a\u064a\u0641 \u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0648\u0641\u0642 \u0645\u0633\u062a\u0648\u0627\u0647 \u0627\u0644\u062d\u0642\u064a\u0642\u064a.","\u0625\u0644\u063a\u0627\u0621 \u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0648\u0627\u0644\u062d\u0633\u0627\u0628 \u0648\u0625\u0642\u0635\u0627\u0626\u0647\u0627.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.atl=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u062a\u0639\u062a\u0645\u062f \u0645\u0642\u0627\u0631\u0628\u0629 (TaRL) - \u0627\u0644\u062a\u062f\u0631\u064a\u0633 \u0648\u0641\u0642 \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0645\u0646\u0627\u0633\u0628 \u0628\u0627\u0644\u0623\u0633\u0627\u0633 \u0639\u0644\u0649:",B.a1j,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u0634\u062e\u064a\u0635 \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0641\u0639\u0644\u064a \u0644\u0644\u0645\u062a\u0639\u0644\u0645 \u0641\u064a \u0627\u0644\u0645\u0647\u0627\u0631\u0627\u062a \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0648\u062a\u0643\u064a\u064a\u0641 \u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0648\u0641\u0642 \u0645\u0633\u062a\u0648\u0627\u0647 \u0627\u0644\u062d\u0642\u064a\u0642\u064a.",u.C)
B.VS=s(["\u0642\u0636\u0627\u0621 \u0648\u0642\u062a \u0627\u0644\u0641\u0631\u0627\u063a \u062f\u0648\u0646 \u0623\u0647\u062f\u0627\u0641 \u062a\u0631\u0628\u0648\u064a\u0629.","\u062a\u062d\u0648\u064a\u0644 \u0627\u0644\u062a\u0639\u0644\u0645 \u0625\u0644\u0649 \u0623\u0646\u0634\u0637\u0629 \u0645\u0645\u062a\u0639\u0629 \u0647\u0627\u062f\u0641\u0629 \u062a\u0646\u0645\u064a \u0627\u0644\u0645\u0647\u0627\u0631\u0627\u062a \u0627\u0644\u0630\u0647\u0646\u064a\u0629 \u0648\u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a\u0629 \u0648\u0627\u0644\u0645\u0647\u0627\u0631\u064a\u0629.","\u0625\u0639\u0641\u0627\u0621 \u0627\u0644\u0645\u062f\u0631\u0633 \u0645\u0646 \u062a\u062d\u0636\u064a\u0631 \u0627\u0644\u062c\u0630\u0627\u0630\u0627\u062a.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.ast=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0627\u0644\u0644\u0639\u0628 \u062a\u0647\u062f\u0641 \u0641\u064a \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0641\u0635\u0644\u064a\u0629 \u0625\u0644\u0649:",B.VS,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u062d\u0648\u064a\u0644 \u0627\u0644\u062a\u0639\u0644\u0645 \u0625\u0644\u0649 \u0623\u0646\u0634\u0637\u0629 \u0645\u0645\u062a\u0639\u0629 \u0647\u0627\u062f\u0641\u0629 \u062a\u0646\u0645\u064a \u0627\u0644\u0645\u0647\u0627\u0631\u0627\u062a \u0627\u0644\u0630\u0647\u0646\u064a\u0629 \u0648\u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a\u0629 \u0648\u0627\u0644\u0645\u0647\u0627\u0631\u064a\u0629.",u.C)
B.a9f=s(["\u0627\u0644\u0639\u0642\u062f \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a.","\u0627\u0644\u0646\u0642\u0644 \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a (Transposition didactique).","\u0627\u0644\u0639\u0627\u0626\u0642 \u0627\u0644\u0627\u0628\u0633\u062a\u0645\u0648\u0644\u0648\u062c\u064a.","\u0627\u0644\u062a\u0645\u062b\u0644 \u0627\u0644\u0645\u0639\u0631\u0641\u064a."],t.s)
B.aoV=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a",'\u0627\u0644\u0645\u062d\u0648\u0631 \u0627\u0644\u0631\u0627\u0628\u0639: \u0627\u0644\u0645\u0641\u0627\u0647\u064a\u0645 \u0648\u0627\u0644\u0627\u0635\u0637\u0644\u0627\u062d\u0627\u062a \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a\u0629 \u062a\u062d\u0648\u064a\u0644 "\u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0627\u0644\u0639\u0627\u0644\u0645\u0629" \u0625\u0644\u0649 "\u0645\u0639\u0631\u0641\u0629 \u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u062a\u062f\u0631\u064a\u0633" \u062a\u062a\u0646\u0627\u0633\u0628 \u0645\u0639 \u0627\u0644\u0646\u0645\u0648 \u0627\u0644\u0645\u0639\u0631\u0641\u064a \u0644\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u064a\u0633\u0645\u0649:',B.a9f,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0646\u0642\u0644 \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a (Transposition didactique).",u.C)
B.To=s(["\u0627\u0644\u0645\u062b\u0644\u062b \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a.","\u0627\u0644\u0639\u0642\u062f \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a (Contrat didactique).","\u0627\u0644\u0645\u0646\u0647\u0627\u062c \u0627\u0644\u062f\u0631\u0627\u0633\u064a.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.an8=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0645\u062c\u0645\u0648\u0639 \u0627\u0644\u0642\u0648\u0627\u0639\u062f \u0648\u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645\u0627\u062a \u0627\u0644\u0635\u0631\u064a\u062d\u0629 \u0648\u0627\u0644\u0636\u0645\u0646\u064a\u0629 \u0627\u0644\u062a\u064a \u062a\u0646\u0638\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u0627\u062a \u0628\u064a\u0646 \u0627\u0644\u0645\u062f\u0631\u0633 \u0648\u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0648\u0627\u0644\u0645\u0627\u062f\u0629 \u064a\u0633\u0645\u0649:",B.To,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0639\u0642\u062f \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a (Contrat didactique).",u.C)
B.a9Q=s(["\u0627\u0644\u0635\u0648\u0631 \u0648\u0627\u0644\u0631\u0633\u0648\u0645 \u0627\u0644\u0628\u064a\u0627\u0646\u064a\u0629 \u0627\u0644\u0645\u0637\u0628\u0648\u0642\u0629 \u0641\u064a \u0627\u0644\u0643\u062a\u0627\u0628 \u0627\u0644\u0645\u062f\u0631\u0633\u064a.","\u0627\u0644\u062a\u0635\u0648\u0631\u0627\u062a \u0648\u0627\u0644\u0645\u0639\u062a\u0642\u062f\u0627\u062a \u0648\u0627\u0644\u0645\u0639\u0627\u0631\u0641 \u0627\u0644\u0642\u0628\u0644\u064a\u0629 \u0627\u0644\u0645\u062e\u0632\u0646\u0629 \u0641\u064a \u0630\u0647\u0646 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u062d\u0648\u0644 \u0645\u0641\u0647\u0648\u0645 \u0645\u0639\u064a\u0646.","\u0627\u0644\u0639\u0631\u0648\u0636 \u0627\u0644\u0645\u0633\u0631\u062d\u064a\u0629 \u0627\u0644\u062a\u064a \u064a\u0642\u062f\u0645\u0647\u0627 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0641\u064a \u0627\u0644\u0641\u0635\u0644.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.asU=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a",'\u0627\u0644\u0645\u0642\u0635\u0648\u062f \u0628\u0640 "\u0627\u0644\u062a\u0645\u062b\u0644\u0627\u062a" (Repr\xe9sentations) \u0644\u062f\u0649 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0647\u0648:',B.a9Q,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u062a\u0635\u0648\u0631\u0627\u062a \u0648\u0627\u0644\u0645\u0639\u062a\u0642\u062f\u0627\u062a \u0648\u0627\u0644\u0645\u0639\u0627\u0631\u0641 \u0627\u0644\u0642\u0628\u0644\u064a\u0629 \u0627\u0644\u0645\u062e\u0632\u0646\u0629 \u0641\u064a \u0630\u0647\u0646 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u062d\u0648\u0644 \u0645\u0641\u0647\u0648\u0645 \u0645\u0639\u064a\u0646.",u.C)
B.abk=s(["\u0627\u0644\u0627\u0646\u0632\u0644\u0627\u0642 \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a.","\u0627\u0644\u0635\u0631\u0627\u0639 \u0627\u0644\u0645\u0639\u0631\u0641\u064a (Conflit cognitif).","\u0627\u0644\u0641\u0634\u0644 \u0627\u0644\u062f\u0631\u0627\u0633\u064a.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.anc=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u064a\u0633\u0645\u0649 \u0627\u0644\u0627\u0636\u0637\u0631\u0627\u0628 \u0627\u0644\u0645\u0639\u0631\u0641\u064a \u0623\u0648 \u0627\u0644\u0630\u0647\u0646\u064a \u0627\u0644\u0630\u064a \u064a\u062d\u062f\u062b \u0644\u0644\u0645\u062a\u0639\u0644\u0645 \u0639\u0646\u062f \u0645\u0648\u0627\u062c\u0647\u0629 \u0648\u0636\u0639\u064a\u0629 \u0645\u0634\u0643\u0644\u0629 \u062a\u062a\u062d\u062f\u0649 \u062a\u0645\u062b\u0644\u062a\u0647 \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0628\u0640:",B.abk,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0635\u0631\u0627\u0639 \u0627\u0644\u0645\u0639\u0631\u0641\u064a (Conflit cognitif).",u.C)
B.a8U=s(["\u0627\u0644\u0645\u062f\u064a\u0631 - \u0627\u0644\u0623\u0633\u062a\u0627\u0630 - \u0627\u0644\u0645\u0641\u062a\u0634.","\u0627\u0644\u0645\u062f\u0631\u0633 - \u0627\u0644\u0645\u062a\u0639\u0644\u0645 - \u0627\u0644\u0645\u0639\u0631\u0641\u0629 (\u0627\u0644\u0645\u0627\u062f\u0629 \u0627\u0644\u062f\u0631\u0627\u0633\u064a\u0629).","\u0627\u0644\u0643\u062a\u0627\u0628 \u0627\u0644\u0645\u062f\u0631\u0633\u064a - \u0627\u0644\u0633\u0628\u0648\u0631\u0629 - \u062f\u0641\u062a\u0631 \u0627\u0644\u062f\u0631\u0648\u0633.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.apy=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a",'\u0627\u0644\u0645\u0643\u0648\u0646\u0627\u062a \u0627\u0644\u062b\u0644\u0627\u062b\u0629 \u0644\u0640 "\u0627\u0644\u0645\u062b\u0644\u062b \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a" \u0647\u064a:',B.a8U,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0645\u062f\u0631\u0633 - \u0627\u0644\u0645\u062a\u0639\u0644\u0645 - \u0627\u0644\u0645\u0639\u0631\u0641\u0629 (\u0627\u0644\u0645\u0627\u062f\u0629 \u0627\u0644\u062f\u0631\u0627\u0633\u064a\u0629).",u.C)
B.W_=s(["\u0627\u0644\u062a\u0642\u064a\u064a\u0645 \u2190 \u0627\u0644\u062a\u062d\u0644\u064a\u0644 \u2190 \u0627\u0644\u062a\u0637\u0628\u064a\u0642.","\u0627\u0644\u062a\u0630\u0643\u0631 \u2190 \u0627\u0644\u0641\u0647\u0645 \u2190 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u2190 \u0627\u0644\u062a\u062d\u0644\u064a\u0644 \u2190 \u0627\u0644\u062a\u0631\u0643\u064a\u0628 \u2190 \u0627\u0644\u062a\u0642\u064a\u064a\u0645.","\u0627\u0644\u0625\u0628\u062f\u0627\u0639 \u2190 \u0627\u0644\u062a\u0630\u0643\u0631 \u2190 \u0627\u0644\u062a\u0631\u0643\u064a\u0628.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.ame=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a",'\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a \u0627\u0644\u0645\u062d\u062f\u062f\u0629 \u0644\u0644\u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u0625\u062c\u0631\u0627\u0626\u064a\u0629 \u0648\u0641\u0642 \u062a\u0635\u0646\u064a\u0641 "\u0628\u0644\u0648\u0645" \u0644\u0644\u0645\u062c\u0627\u0644 \u0627\u0644\u0645\u0639\u0631\u0641\u064a \u062a\u0628\u062f\u0623 \u0628\u0640:',B.W_,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u062a\u0630\u0643\u0631 \u2190 \u0627\u0644\u0641\u0647\u0645 \u2190 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u2190 \u0627\u0644\u062a\u062d\u0644\u064a\u0644 \u2190 \u0627\u0644\u062a\u0631\u0643\u064a\u0628 \u2190 \u0627\u0644\u062a\u0642\u064a\u064a\u0645.",u.C)
B.a9_=s(["\u0627\u0644\u0645\u0639\u062f\u0627\u062a \u0648\u0627\u0644\u0644\u0648\u062c\u0633\u062a\u064a\u0643 \u0627\u0644\u0645\u0627\u062f\u064a \u0627\u0644\u0645\u062a\u0648\u0641\u0631 \u0628\u0627\u0644\u0645\u0624\u0633\u0633\u0629 \u0641\u0642\u0637.","\u0627\u0644\u0645\u0639\u0627\u0631\u0641\u060c \u0627\u0644\u0645\u0647\u0627\u0631\u0627\u062a\u060c \u0627\u0644\u0627\u062a\u062c\u0627\u0647\u0627\u062a\u060c \u0648\u0627\u0644\u0633\u0644\u0648\u0643\u064a\u0627\u062a \u0627\u0644\u062a\u064a \u064a\u062c\u0646\u062f\u0647\u0627 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0644\u062d\u0644 \u0627\u0644\u0648\u0636\u0639\u064a\u0629.","\u0627\u0644\u0645\u064a\u0632\u0627\u0646\u064a\u0629 \u0627\u0644\u0645\u0627\u0644\u064a\u0629 \u0627\u0644\u0645\u062e\u0635\u0635\u0629 \u0644\u062c\u0645\u0639\u064a\u0629 \u062f\u0639\u0645 \u0627\u0644\u0646\u062c\u0627\u062d.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.alk=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a",'\u0627\u0644\u0645\u0642\u0635\u0648\u062f \u0628\u0640 "\u0627\u0644\u0645\u0648\u0627\u0631\u062f" (Ressources) \u0641\u064a \u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0629 \u0628\u0627\u0644\u0643\u0641\u0627\u064a\u0627\u062a:',B.a9_,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0645\u0639\u0627\u0631\u0641\u060c \u0627\u0644\u0645\u0647\u0627\u0631\u0627\u062a\u060c \u0627\u0644\u0627\u062a\u062c\u0627\u0647\u0627\u062a\u060c \u0648\u0627\u0644\u0633\u0644\u0648\u0643\u064a\u0627\u062a \u0627\u0644\u062a\u064a \u064a\u062c\u0646\u062f\u0647\u0627 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0644\u062d\u0644 \u0627\u0644\u0648\u0636\u0639\u064a\u0629.",u.C)
B.a9n=s(["\u0645\u0634\u0643\u0644\u0629 \u0641\u064a \u0627\u0644\u0625\u0636\u0627\u0621\u0629 \u0623\u0648 \u0627\u0644\u0637\u0627\u0648\u0644\u0627\u062a \u062f\u0627\u062e\u0644 \u0627\u0644\u062d\u062c\u0631\u0629 \u0627\u0644\u062f\u0631\u0627\u0633\u064a\u0629.","\u0635\u0639\u0648\u0628\u0629 \u0623\u0648 \u0645\u0641\u0647\u0648\u0645 \u062e\u0627\u0637\u0626 \u064a\u0639\u062a\u0631\u0636 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u062a\u0639\u0644\u0645 \u0646\u062a\u064a\u062c\u0629 \u0646\u0645\u0637 \u0627\u0644\u062a\u062f\u0631\u064a\u0633 \u0623\u0648 \u0637\u0628\u064a\u0639\u0629 \u0627\u0644\u0645\u0641\u0647\u0648\u0645.","\u063a\u064a\u0627\u0628 \u0627\u0644\u062a\u0644\u0645\u064a\u0630 \u0639\u0646 \u0627\u0644\u062d\u0635\u0635 \u0627\u0644\u062f\u0631\u0627\u0633\u064a\u0629.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.ap0=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u0639\u0627\u0626\u0642 \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a \u0647\u0648:",B.a9n,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0635\u0639\u0648\u0628\u0629 \u0623\u0648 \u0645\u0641\u0647\u0648\u0645 \u062e\u0627\u0637\u0626 \u064a\u0639\u062a\u0631\u0636 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u062a\u0639\u0644\u0645 \u0646\u062a\u064a\u062c\u0629 \u0646\u0645\u0637 \u0627\u0644\u062a\u062f\u0631\u064a\u0633 \u0623\u0648 \u0637\u0628\u064a\u0639\u0629 \u0627\u0644\u0645\u0641\u0647\u0648\u0645.",u.C)
