B.alj=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u0645\u0631\u062c\u0639\u064a\u0629 \u0627\u0644\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0644\u0644\u0625\u0635\u0644\u0627\u062d \u0627\u0644\u062a\u0631\u0628\u0648\u064a \u0628\u0627\u0644\u0645\u063a\u0631\u0628 \u0644\u0644\u0645\u062f\u0649 \u0627\u0644\u0645\u062a\u0648\u0633\u0637 (2015-2030) \u062a\u064f\u0639\u0631\u0641 \u0628\u0640:",B.a6i,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0631\u0624\u064a\u0629 \u0627\u0644\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0644\u0644\u0625\u0635\u0644\u0627\u062d.",u.C)
B.a_u=s(["\u0627\u0644\u0645\u062c\u0644\u0633 \u0627\u0644\u062a\u0631\u0628\u0648\u064a.","\u0645\u062c\u0644\u0633 \u0627\u0644\u062a\u062f\u0628\u064a\u0631.","\u0645\u062c\u0627\u0644\u0633 \u0627\u0644\u0623\u0642\u0633\u0627\u0645.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.anV=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u0645\u062c\u0644\u0633 \u0627\u0644\u0630\u064a \u064a\u064f\u0639\u062a\u0628\u0631 \u0627\u0644\u062c\u0647\u0627\u0632 \u0627\u0644\u0623\u0647\u0645 \u0627\u0644\u0645\u0633\u0624\u0648\u0644 \u0639\u0646 \u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0634\u0624\u0648\u0646 \u0627\u0644\u0625\u062f\u0627\u0631\u064a\u0629 \u0648\u0627\u0644\u0645\u0627\u0644\u064a\u0629 \u0644\u0644\u0645\u0624\u0633\u0633\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629 \u0647\u0648:",B.a_u,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0645\u062c\u0644\u0633 \u0627\u0644\u062a\u062f\u0628\u064a\u0631.",u.C)
B.YR=s(["\u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0627\u0644\u0623\u0642\u062f\u0645 \u0641\u064a \u0627\u0644\u0645\u0624\u0633\u0633\u0629.","\u0645\u062f\u064a\u0631 \u0627\u0644\u0645\u0624\u0633\u0633\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629.","\u0631\u0626\u064a\u0633 \u062c\u0645\u0639\u064a\u0629 \u0622\u0628\u0627\u0621 \u0648\u0623\u0648\u0644\u064a\u0627\u0621 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630.","\u0627\u0644\u0645\u0641\u062a\u0634 \u0627\u0644\u062a\u0631\u0628\u0648\u064a \u0644\u0644\u0642\u0637\u0627\u0639."],t.s)
B.ajv=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u064a\u062a\u0631\u0623\u0633 \u0645\u062c\u0627\u0644\u0633 \u0627\u0644\u0645\u0624\u0633\u0633\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629 \u0628\u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a (\u0627\u0644\u062a\u062f\u0628\u064a\u0631\u060c \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u060c \u0627\u0644\u0623\u0642\u0633\u0627\u0645):",B.YR,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0645\u062f\u064a\u0631 \u0627\u0644\u0645\u0624\u0633\u0633\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629.",u.C)
B.a_e=s(["\u062a\u0648\u0638\u064a\u0641 \u0627\u0644\u0623\u0633\u0627\u062a\u0630\u0629 \u0648\u062a\u062d\u062f\u064a\u062f \u0623\u062c\u0648\u0631\u0647\u0645.","\u062a\u0646\u0632\u064a\u0644 \u0648\u0628\u0631\u0645\u062c\u0629 \u0645\u062e\u062a\u0644\u0641 \u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0648\u062d\u0633\u0627\u0628 \u0623\u0648\u0644\u0648\u064a\u0627\u062a \u062a\u062d\u0633\u064a\u0646 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a \u0628\u0627\u0644\u0645\u0624\u0633\u0633\u0629.","\u0625\u0644\u063a\u0627\u0621 \u0627\u0644\u0645\u0631\u0627\u0642\u0628\u0629 \u0627\u0644\u0645\u0633\u062a\u0645\u0631\u0629.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.apI=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a",'\u0645\u0634\u0631\u0648\u0639 "\u0627\u0644\u0645\u0624\u0633\u0633\u0629 \u0627\u0644\u0645\u062f\u0645\u062c" (PEI) \u064a\u064f\u0639\u062a\u0628\u0631 \u0627\u0644\u0625\u0637\u0627\u0631 \u0627\u0644\u0645\u0646\u0647\u062c\u064a \u0627\u0644\u0645\u0639\u062a\u0645\u062f \u0644\u0640:',B.a_e,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u0646\u0632\u064a\u0644 \u0648\u0628\u0631\u0645\u062c\u0629 \u0645\u062e\u062a\u0644\u0641 \u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0648\u062d\u0633\u0627\u0628 \u0623\u0648\u0644\u0648\u064a\u0627\u062a \u062a\u062d\u0633\u064a\u0646 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a \u0628\u0627\u0644\u0645\u0624\u0633\u0633\u0629.",u.C)
B.Zq=s(["\u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u0639\u0644\u0627\u062c\u064a.","\u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u0648\u0642\u0627\u0626\u064a.","\u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u062a\u0639\u0648\u064a\u0636\u064a.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.arg=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u0630\u064a \u064a\u064f\u0642\u062f\u0645 \u0642\u0628\u0644 \u0627\u0646\u0637\u0644\u0627\u0642 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a \u0644\u0648\u0642\u0627\u064a\u0629 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0645\u0646 \u0627\u0644\u0648\u0642\u0648\u0639 \u0641\u064a \u062a\u0639\u062b\u0631\u0627\u062a \u0645\u062a\u0648\u0642\u0639\u0629 \u064a\u064f\u0633\u0645\u0649:",B.Zq,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u0648\u0642\u0627\u0626\u064a.",u.C)
B.TJ=s(["\u0648\u062b\u064a\u0642\u0629 \u0625\u062f\u0627\u0631\u064a\u0629 \u0648\u0642\u0627\u0646\u0648\u0646\u064a\u0629 \u0625\u0644\u0632\u0627\u0645\u064a\u0629 \u064a\u062a\u062d\u0645\u0644 \u0627\u0644\u0645\u062f\u0631\u0633 \u0645\u0633\u0624\u0648\u0644\u064a\u0629 \u062a\u062d\u064a\u064a\u0646\u0647\u0627 \u0644\u0644\u0631\u062c\u0648\u0639 \u0625\u0644\u064a\u0647\u0627 \u0639\u0646\u062f \u0627\u0644\u062d\u0648\u0627\u062f\u062b \u0627\u0644\u0645\u062f\u0631\u0633\u064a\u0629.","\u0645\u062c\u0631\u062f \u0645\u0633\u0648\u062f\u0629 \u0634\u062e\u0635\u064a\u0629 \u0644\u0644\u0623\u0633\u062a\u0627\u0630 \u0644\u0627 \u0642\u064a\u0645\u0629 \u0644\u0647\u0627 \u0625\u062f\u0627\u0631\u064a\u0627\u064b.","\u0648\u062b\u064a\u0642\u0629 \u064a\u064f\u0645\u0633\u0643\u0647\u0627 \u0639\u0633\u0633 \u0627\u0644\u0645\u0624\u0633\u0633\u0629.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.apn=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a",'\u062a\u0639\u062a\u0628\u0631 \u0648\u062b\u064a\u0642\u0629 "\u0633\u062c\u0644 \u0627\u0644\u062d\u0636\u0648\u0631 \u0648\u0627\u0644\u063a\u064a\u0627\u0628" \u0628\u0627\u0644\u0641\u0635\u0644 \u0627\u0644\u062f\u0631\u0627\u0633\u064a:',B.TJ,0,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0648\u062b\u064a\u0642\u0629 \u0625\u062f\u0627\u0631\u064a\u0629 \u0648\u0642\u0627\u0646\u0648\u0646\u064a\u0629 \u0625\u0644\u0632\u0627\u0645\u064a\u0629 \u064a\u062a\u062d\u0645\u0644 \u0627\u0644\u0645\u062f\u0631\u0633 \u0645\u0633\u0624\u0648\u0644\u064a\u0629 \u062a\u062d\u064a\u064a\u0646\u0647\u0627 \u0644\u0644\u0631\u062c\u0648\u0639 \u0625\u0644\u064a\u0647\u0627 \u0639\u0646\u062f \u0627\u0644\u062d\u0648\u0627\u062f\u062b \u0627\u0644\u0645\u062f\u0631\u0633\u064a\u0629.",u.C)
B.a1H=s(["\u0627\u0644\u062a\u062e\u0635\u0635 \u0627\u0644\u0635\u0627\u0631\u0645.","\u0627\u0644\u062a\u062f\u0627\u062e\u0644 \u0648\u0627\u0644\u062a\u0642\u0627\u0637\u0639 \u0628\u064a\u0646 \u0627\u0644\u0645\u0648\u0627\u062f (Interdisciplinarit\xe9).","\u0627\u0644\u0641\u0635\u0644 \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.akf=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u0645\u0628\u062f\u0623 \u0627\u0644\u062a\u0631\u0628\u0648\u064a \u0627\u0644\u0630\u064a \u064a\u0642\u0636\u064a \u0628\u0627\u0644\u0631\u0628\u0637 \u0628\u064a\u0646 \u062a\u0639\u0644\u0645\u0627\u062a \u0627\u0644\u0645\u0648\u0627\u062f \u0627\u0644\u0645\u062e\u062a\u0644\u0641\u0629 \u0648\u0627\u0644\u0645 \u062a\u0642\u0627\u0637\u0639 \u0628\u064a\u0646\u0647\u0627 \u064a\u064f\u0639\u0631\u0641 \u0628\u0640:",B.a1H,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u062a\u062f\u0627\u062e\u0644 \u0648\u0627\u0644\u062a\u0642\u0627\u0637\u0639 \u0628\u064a\u0646 \u0627\u0644\u0645\u0648\u0627\u062f (Interdisciplinarit\xe9).",u.C)
B.a9U=s(["\u0627\u0644\u062a\u0631\u0643\u064a\u0632 \u0627\u0644\u062d\u0635\u0631\u064a \u0639\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0645\u0639\u0631\u0641\u064a \u0627\u0644\u0635\u0645 \u0641\u0642\u0637.","\u062a\u0646\u0645\u064a\u0629 \u0634\u062e\u0635\u064a\u0629 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0645\u0646 \u0645\u062e\u062a\u0644\u0641 \u0627\u0644\u062c\u0648\u0627\u0646\u0628 \u0627\u0644\u0641\u0643\u0631\u064a\u0629\u060c \u0627\u0644\u0648\u062c\u062f\u0627\u0646\u064a\u0629\u060c \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a\u0629\u060c \u0648\u0627\u0644\u0645\u0647\u0627\u0631\u064a\u0629 \u0639\u0628\u0631 \u0623\u0646\u0634\u0637\u0629 \u0645\u0648\u0627\u0632\u064a\u0629.","\u062a\u0646\u0638\u064a\u0645 \u0645\u0633\u0627\u0628\u0642\u0627\u062a \u0628\u064a\u0646 \u0627\u0644\u0645\u062f\u0631\u0633\u064a\u0646.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aoq=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u062a\u0633\u062a\u0647\u062f\u0641 \u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u0645\u062f\u0631\u0633\u064a\u0629 \u0628\u0627\u0644\u0645\u0624\u0633\u0633\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629:",B.a9U,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u0646\u0645\u064a\u0629 \u0634\u062e\u0635\u064a\u0629 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0645\u0646 \u0645\u062e\u062a\u0644\u0641 \u0627\u0644\u062c\u0648\u0627\u0646\u0628 \u0627\u0644\u0641\u0643\u0631\u064a\u0629\u060c \u0627\u0644\u0648\u062c\u062f\u0627\u0646\u064a\u0629\u060c \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a\u0629\u060c \u0648\u0627\u0644\u0645\u0647\u0627\u0631\u064a\u0629 \u0639\u0628\u0631 \u0623\u0646\u0634\u0637\u0629 \u0645\u0648\u0627\u0632\u064a\u0629.",u.C)
B.TD=s(["\u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u062f\u0631\u0627\u0633\u064a \u0627\u0644\u0648\u0627\u062d\u062f\u0629.","\u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u062a\u0648\u0632\u064a\u0639 \u0627\u0644\u062f\u0648\u0631\u064a \u0623\u0648 \u0627\u0644\u0645\u062c\u0627\u0644/\u0627\u0644\u0648\u062d\u062f\u0629 \u0627\u0644\u062f\u0631\u0627\u0633\u064a\u0629.","\u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u0645\u0633\u0627\u0631 \u0627\u0644\u0645\u0647\u0646\u064a \u0644\u0645\u062f\u0629 \u0639\u0634\u0631 \u0633\u0646\u0648\u0627\u062a.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.akA=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0645\u062f\u0649 \u0627\u0644\u0645\u062a\u0648\u0633\u0637 \u0641\u064a \u0639\u0645\u0644 \u0627\u0644\u0645\u062f\u0631\u0633 \u064a\u0634\u0645\u0644:",B.TD,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u062a\u0648\u0632\u064a\u0639 \u0627\u0644\u062f\u0648\u0631\u064a \u0623\u0648 \u0627\u0644\u0645\u062c\u0627\u0644/\u0627\u0644\u0648\u062d\u062f\u0629 \u0627\u0644\u062f\u0631\u0627\u0633\u064a\u0629.",u.C)
B.a3X=s(["\u0643\u062a\u0627\u0628\u0629 \u0645\u0644\u062e\u0635 \u0645\u0639\u0642\u062f \u0641\u064a \u0627\u0644\u0625\u0645\u0644\u0627\u0621.","\u0627\u0644\u0627\u0633\u062a\u0645\u0627\u0639 \u0627\u0644\u0641\u0639\u0627\u0644\u060c \u0627\u0644\u0641\u0647\u0645\u060c \u0648\u0627\u0644\u062a\u0639\u0628\u064a\u0631 \u0627\u0644\u0633\u0644\u064a\u0645 \u0648\u0627\u0644\u0645\u0634\u0627\u0641\u0647\u0629 \u0648\u0625\u0628\u062f\u0627\u0621 \u0627\u0644\u0631\u0623\u064a.","\u062d\u0641\u0638 \u0627\u0644\u0625\u0639\u0631\u0627\u0628 \u0648\u062a\u0637\u0628\u064a\u0642\u0647 \u0643\u062a\u0627\u0628\u064a\u0627\u064b.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.atd=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0645\u0646 \u0627\u0644\u0645\u0647\u0627\u0631\u0627\u062a \u0627\u0644\u0634\u0641\u0647\u064a\u0629 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u0629 \u0641\u064a \u0645\u0643\u0648\u0646 \u0627\u0644\u062a\u0648\u0627\u0635\u0644 \u0627\u0644\u0634\u0641\u0647\u064a \u0628\u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a:",B.a3X,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0627\u0633\u062a\u0645\u0627\u0639 \u0627\u0644\u0641\u0639\u0627\u0644\u060c \u0627\u0644\u0641\u0647\u0645\u060c \u0648\u0627\u0644\u062a\u0639\u0628\u064a\u0631 \u0627\u0644\u0633\u0644\u064a\u0645 \u0648\u0627\u0644\u0645\u0634\u0627\u0641\u0647\u0629 \u0648\u0625\u0628\u062f\u0627\u0621 \u0627\u0644\u0631\u0623\u064a.",u.C)
B.a5x=s(["\u0627\u0644\u0638\u0627\u0647\u0631\u0629 \u0627\u0644\u062a\u064a \u062a\u064f\u0645\u0631\u0631 \u0636\u0645\u0646\u064a\u0627\u064b \u0645\u0646 \u062e\u0644\u0627\u0644 \u0627\u0644\u0646\u0635\u0648\u0635 \u062f\u0648\u0646 \u062a\u0633\u0645\u064a\u0629 \u0627\u0644\u0645\u0641\u0647\u0648\u0645.","\u0627\u0644\u0638\u0627\u0647\u0631\u0629 \u0627\u0644\u062a\u064a \u062a\u062a\u0636\u0645\u0646 \u062a\u0633\u0645\u064a\u062a\u0647\u0627 \u0648\u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0642\u0648\u0627\u0639\u062f \u0627\u0644\u062e\u0627\u0635\u0629 \u0628\u0647\u0627 \u0648\u0627\u0633\u062a\u062e\u0631\u0627\u062c \u0634\u0648\u0627\u0647\u062f\u0647\u0627 \u0648\u0625\u0639\u0631\u0627\u0628\u0647\u0627.","\u0627\u0644\u0638\u0627\u0647\u0631\u0629 \u0627\u0644\u0634\u0641\u0647\u064a\u0629 \u063a\u064a\u0631 \u0627\u0644\u0645\u0643\u062a\u0648\u0628\u0629.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.asI=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a",'\u0627\u0644\u0645\u0642\u0635\u0648\u062f \u0628\u0627\u0644\u0638\u0627\u0647\u0631\u0629 \u0627\u0644\u0644\u063a\u0648\u064a\u0629 "\u0627\u0644\u0635\u0631\u064a\u062d\u0629" \u0647\u0648:',B.a5x,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0638\u0627\u0647\u0631\u0629 \u0627\u0644\u062a\u064a \u062a\u062a\u0636\u0645\u0646 \u062a\u0633\u0645\u064a\u062a\u0647\u0627 \u0648\u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0642\u0648\u0627\u0639\u062f \u0627\u0644\u062e\u0627\u0635\u0629 \u0628\u0647\u0627 \u0648\u0627\u0633\u062a\u062e\u0631\u0627\u062c \u0634\u0648\u0627\u0647\u062f\u0647\u0627 \u0648\u0625\u0639\u0631\u0627\u0628\u0647\u0627.",u.C)
B.XH=s(["\u062a\u0635\u062d\u064a\u062d \u0627\u0644\u0623\u062e\u0637\u0627\u0621 \u0648\u0639\u0631\u0636 \u0627\u0644\u0625\u0646\u062c\u0627\u0632\u0627\u062a.","\u0627\u0644\u0634\u0643\u0644 \u0648\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0646\u0635 \u0648\u0641\u0647\u0645\u0647 \u0648\u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0627\u0644\u062c\u0632\u0626\u064a \u0639\u0644\u0649 \u0627\u0644\u0638\u0648\u0627\u0647\u0631.","\u0643\u062a\u0627\u0628\u0629 \u0627\u0644\u0625\u0646\u062a\u0627\u062c \u0627\u0644\u0643\u062a\u0627\u0628\u064a \u0627\u0644\u0646\u0647\u0627\u0626\u064a.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.alT=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u062a\u064f\u062e\u0635\u0635 \u0627\u0644\u062d\u0635\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u0645\u0646 \u0645\u0643\u0648\u0646 \u0627\u0644\u062a\u0637\u0628\u064a\u0642\u0627\u062a \u0627\u0644\u0643\u062a\u0627\u0628\u064a\u0629 \u0641\u064a \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0633\u0627\u062f\u0633 \u0644\u0640:",B.XH,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0634\u0643\u0644 \u0648\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0646\u0635 \u0648\u0641\u0647\u0645\u0647 \u0648\u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0627\u0644\u062c\u0632\u0626\u064a \u0639\u0644\u0649 \u0627\u0644\u0638\u0648\u0627\u0647\u0631.",u.C)
B.a09=s(["\u0627\u0644\u0645\u0639\u064a\u0627\u0631 \u0627\u0644\u0639\u0627\u0645 \u0627\u0644\u0634\u0627\u0645\u0644.","\u0627\u0644\u0646\u062a\u064a\u062c\u0629 \u0627\u0644\u0625\u062c\u0631\u0627\u0626\u064a\u0629 \u0627\u0644\u0645\u0644\u0645\u0648\u0633\u0629 \u0648\u0627\u0644\u0643\u0645\u064a\u0629 \u0623\u0648 \u0627\u0644\u0643\u064a\u0641\u064a\u0629 \u0627\u0644\u062a\u064a \u062a\u062f\u0644 \u0639\u0644\u0649 \u062a\u062d\u0642\u0642 \u0627\u0644\u0645\u0639\u064a\u0627\u0631.","\u062f\u0631\u062c\u0629 \u0627\u0644\u0627\u0645\u062a\u062d\u0627\u0646 \u0627\u0644\u0639\u062f\u062f\u064a.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.arm=new A.c("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u0645\u0624\u0634\u0631 (Indicateur) \u0641\u064a \u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u0643\u0641\u0627\u064a\u0627\u062a \u0647\u0648:",B.a09,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0646\u062a\u064a\u062c\u0629 \u0627\u0644\u0625\u062c\u0631\u0627\u0626\u064a\u0629 \u0627\u0644\u0645\u0644\u0645\u0648\u0633\u0629 \u0648\u0627\u0644\u0643\u0645\u064a\u0629 \u0623\u0648 \u0627\u0644\u0643\u064a\u0641\u064a\u0629 \u0627\u0644\u062a\u064a \u062a\u062f\u0644 \u0639\u0644\u0649 \u062a\u062d\u0642\u0642 \u0627\u0644\u0645\u0639\u064a\u0627\u0631.",u.C)
