B.ST=s(["\u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a \u0648\u0627\u0644\u062a\u0641\u0627\u0648\u0636 \u0627\u0644\u0645\u0639\u0631\u0641\u064a \u0645\u0639 \u0627\u0644\u0623\u0642\u0631\u0627\u0646 \u0648\u0641\u064a \u0633\u064a\u0627\u0642\u0627\u062a \u062b\u0642\u0627\u0641\u064a\u0629.","\u0627\u0644\u062d\u0641\u0638 \u0648\u0627\u0644\u062a\u0643\u0631\u0627\u0631 \u0627\u0644\u0641\u0631\u062f\u064a \u0644\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a.","\u0627\u0644\u062a\u0623\u062b\u064a\u0631 \u0627\u0644\u0645\u0628\u0627\u0634\u0631 \u0648\u0627\u0644\u0622\u0644\u064a \u0644\u0644\u0645\u062b\u064a\u0631\u0627\u062a \u0627\u0644\u062e\u0627\u0631\u062c\u064a\u0629.","\u0627\u0644\u0646\u0636\u062c \u0627\u0644\u0628\u064a\u0648\u0644\u0648\u062c\u064a \u0627\u0644\u0645\u0628\u0627\u0634\u0631 \u0644\u0644\u062c\u0647\u0627\u0632 \u0627\u0644\u0639\u0635\u0628\u064a \u062f\u0648\u0646 \u0627\u0644\u062d\u0627\u062c\u0629 \u0644\u0644\u0645\u062d\u064a\u0637."],t.s)
B.anL=new A.c("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'16. "\u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0644\u0633\u0648\u0633\u064a\u0648-\u0628\u0646\u0627\u0626\u064a" \u064a\u0631\u0649 \u0623\u0646 \u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u064a\u062a\u0645 \u0628\u0634\u0643\u0644 \u0631\u0626\u064a\u0633\u064a \u0645\u0646 \u062e\u0644\u0627\u0644:',B.ST,0,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a \u0648\u0627\u0644\u062a\u0641\u0627\u0648\u0636 \u0627\u0644\u0645\u0639\u0631\u0641\u064a \u0645\u0639 \u0627\u0644\u0623\u0642\u0631\u0627\u0646 \u0648\u0641\u064a \u0633\u064a\u0627\u0642\u0627\u062a \u062b\u0642\u0627\u0641\u064a\u0629.",u.C)
B.SX=s(["\u0645\u0624\u0634\u0631 \u0639\u0644\u0649 \u0639\u062f\u0645 \u0628\u0630\u0644 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0644\u0623\u064a \u062c\u0647\u062f \u0648\u062c\u0628 \u0627\u0644\u0639\u0642\u0627\u0628 \u0639\u0644\u064a\u0647.","\u062e\u0644\u0644 \u064a\u062c\u0628 \u0625\u062e\u0641\u0627\u0624\u0647 \u0648\u062a\u0641\u0627\u062f\u064a\u0647 \u0628\u0623\u064a \u062b\u0645\u0646 \u0641\u064a \u0627\u0644\u0641\u0635\u0644.","\u0646\u0642\u0637\u0629 \u0627\u0646\u0637\u0644\u0627\u0642 \u0623\u0633\u0627\u0633\u064a\u0629 \u0648\u0645\u0624\u0634\u0631 \u0644\u062f\u0631\u0627\u0633\u0629 \u062a\u0645\u062b\u0644\u0627\u062a \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0648\u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0627\u0644\u0633\u0644\u064a\u0645\u0629.","\u062f\u0644\u064a\u0644 \u0642\u0627\u0637\u0639 \u0639\u0644\u0649 \u0639\u062f\u0645 \u0635\u0644\u0627\u062d\u064a\u0629 \u0627\u0644\u0645\u0646\u0647\u062c \u0627\u0644\u062f\u0631\u0627\u0633\u064a."],t.s)
B.ajO=new A.c("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'17. \u064a\u064f\u0639\u0631\u0641 "\u0627\u0644\u062e\u0637\u0623" \u0641\u064a \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0627\u0644\u062d\u062f\u064a\u062b\u0629 \u0628\u0623\u0646\u0647:',B.SX,2,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0646\u0642\u0637\u0629 \u0627\u0646\u0637\u0644\u0627\u0642 \u0623\u0633\u0627\u0633\u064a\u0629 \u0648\u0645\u0624\u0634\u0631 \u0644\u062f\u0631\u0627\u0633\u0629 \u062a\u0645\u062b\u0644\u0627\u062a \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0648\u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0627\u0644\u0633\u0644\u064a\u0645\u0629.",u.C)
B.a9E=s(["\u0627\u0644\u062a\u0641\u0643\u064a\u0631 \u0641\u064a \u0627\u0644\u0639\u0642\u0648\u0628\u0627\u062a \u0627\u0644\u0645\u0645\u0643\u0646\u0629 \u0644\u0644\u062a\u0644\u0627\u0645\u0630\u0629 \u0627\u0644\u0645\u0634\u0627\u063a\u0628\u064a\u0646.","\u0627\u0644\u0645\u0633\u0627\u0621\u0644\u0629 \u0627\u0644\u0630\u0627\u062a\u064a\u0629 \u0627\u0644\u0645\u0633\u062a\u0645\u0631\u0629 \u0644\u0644\u0645\u0645\u0627\u0631\u0633\u0627\u062a \u0627\u0644\u0641\u0635\u0644\u064a\u0629 \u0648\u062a\u062d\u0644\u064a\u0644\u0647\u0627 \u0644\u062a\u0637\u0648\u064a\u0631 \u0627\u0644\u0623\u062f\u0627\u0621 \u0648\u062a\u0639\u062f\u064a\u0644 \u0627\u0644\u0625\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a.","\u0627\u0644\u062a\u0641\u0643\u064a\u0631 \u0641\u064a \u0643\u062a\u0627\u0628\u0629 \u0627\u0644\u062a\u062e\u0637\u064a\u0637\u0627\u062a \u0627\u0644\u064a\u0648\u0645\u064a\u0629 \u0641\u0642\u0637.","\u0645\u0646\u0627\u0642\u0634\u0629 \u0627\u0644\u0642\u0636\u0627\u064a\u0627 \u0627\u0644\u0625\u062f\u0627\u0631\u064a\u0629 \u0641\u064a \u0645\u062c\u0627\u0644\u0633 \u0627\u0644\u0645\u0624\u0633\u0633\u0629."],t.s)
B.amG=new A.c("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'18. \u0645\u0645\u0627\u0631\u0633\u0629 "\u0627\u0644\u062a\u0641\u0643\u0631" (La pratique r\xe9flexive) \u0639\u0646\u062f \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u062a\u0639\u0646\u064a:',B.a9E,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0645\u0633\u0627\u0621\u0644\u0629 \u0627\u0644\u0630\u0627\u062a\u064a\u0629 \u0627\u0644\u0645\u0633\u062a\u0645\u0631\u0629 \u0644\u0644\u0645\u0645\u0627\u0631\u0633\u0627\u062a \u0627\u0644\u0641\u0635\u0644\u064a\u0629 \u0648\u062a\u062d\u0644\u064a\u0644\u0647\u0627 \u0644\u062a\u0637\u0648\u064a\u0631 \u0627\u0644\u0623\u062f\u0627\u0621 \u0648\u062a\u0639\u062f\u064a\u0644 \u0627\u0644\u0625\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a.",u.C)
B.Ur=s(["\u0625\u0639\u0641\u0627\u0621 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0648\u0636\u0639\u064a\u0629 \u0625\u0639\u0627\u0642\u0629 \u0645\u0646 \u062c\u0645\u064a\u0639 \u0627\u0644\u0645\u0648\u0627\u062f \u0627\u0644\u062f\u0631\u0627\u0633\u064a\u0629.","\u062a\u0639\u062f\u064a\u0644\u0627\u062a \u0648\u062a\u0643\u064a\u0641\u0627\u062a \u0641\u064a \u0627\u0644\u0637\u0631\u0642 \u0648\u0627\u0644\u0648\u0633\u0627\u0626\u0644 \u0648\u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0648\u0637\u0631\u0642 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0644\u062a\u0646\u0627\u0633\u0628 \u0630\u0648\u064a \u0627\u0644\u0627\u062d\u062a\u064a\u0627\u062c\u0627\u062a \u0627\u0644\u062e\u0627\u0635\u0629 \u062f\u0648\u0646 \u0625\u062e\u0644\u0627\u0644 \u0628\u0627\u0644\u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u0639\u0644\u0645\u064a\u0629.","\u0639\u0632\u0644 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0630\u0648\u064a \u0627\u0644\u0625\u0639\u0627\u0642\u0629 \u0641\u064a \u0645\u062f\u0627\u0631\u0633 \u062e\u0627\u0635\u0629 \u062f\u0627\u0626\u0645\u0627\u064b.","\u062e\u0641\u0636 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0627\u0645\u062a\u062d\u0627\u0646 \u0644\u062c\u0645\u064a\u0639 \u062a\u0644\u0627\u0645\u064a\u0630 \u0627\u0644\u0641\u0635\u0644."],t.s)
B.apL=new A.c("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'19. \u0641\u064a \u0633\u064a\u0627\u0642 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0627\u0644\u062f\u0627\u0645\u062c\u0629\u060c \u062a\u064f\u0639\u0631\u0641 "\u0627\u0644\u062a\u0643\u064a\u064a\u0641\u0627\u062a \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a\u0629" \u0628\u0623\u0646\u0647\u0627:',B.Ur,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u0639\u062f\u064a\u0644\u0627\u062a \u0648\u062a\u0643\u064a\u0641\u0627\u062a \u0641\u064a \u0627\u0644\u0637\u0631\u0642 \u0648\u0627\u0644\u0648\u0633\u0627\u0626\u0644 \u0648\u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0648\u0637\u0631\u0642 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0644\u062a\u0646\u0627\u0633\u0628 \u0630\u0648\u064a \u0627\u0644\u0627\u062d\u062a\u064a\u0627\u062c\u0627\u062a \u0627\u0644\u062e\u0627\u0635\u0629 \u062f\u0648\u0646 \u0625\u062e\u0644\u0627\u0644 \u0628\u0627\u0644\u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u0639\u0644\u0645\u064a\u0629.",u.C)
B.abb=s(["\u0627\u0644\u0633\u0644\u0648\u0643 \u0627\u0644\u062e\u0627\u0631\u062c\u064a \u0627\u0644\u0642\u0627\u0628\u0644 \u0644\u0644\u0645\u0644\u0627\u062d\u0638\u0629 \u0648\u0627\u0644\u0642\u064a\u0627\u0633.","\u0627\u0644\u0645\u0634\u0627\u0639\u0631\u060c \u0627\u0644\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0630\u0627\u062a\u064a\u0629\u060c \u0627\u0644\u062a\u0648\u062c\u064a\u0647 \u0627\u0644\u0630\u0627\u062a\u064a \u0644\u0644\u0645\u062a\u0639\u0644\u0645 \u0648\u0627\u0644\u0639\u0644\u0627\u0642\u0629 \u0627\u0644\u0625\u0646\u0633\u0627\u0646\u064a\u0629 \u0627\u0644\u0625\u064a\u062c\u0627\u0628\u064a\u0629.","\u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a \u0627\u0644\u062d\u0633\u0627\u0628\u064a\u0629 \u0648\u0627\u0644\u0645\u0646\u0637\u0642 \u0627\u0644\u0635\u0648\u0631\u064a \u0641\u0642\u0637.","\u0627\u0644\u0628\u0631\u0645\u062c\u0629 \u0627\u0644\u0644\u063a\u0648\u064a\u0629 \u0627\u0644\u0639\u0635\u0628\u064a\u0629 \u0648\u062a\u0637\u0628\u064a\u0642\u0627\u062a\u0647\u0627 \u0627\u0644\u0641\u0646\u064a\u0629."],t.s)
B.apJ=new A.c("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,"20. \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0627\u0644\u0641\u064a\u0646\u0648\u0645\u064a\u0646\u0648\u0644\u0648\u062c\u064a\u0629 \u0623\u0648 \u0627\u0644\u0625\u0646\u0633\u0627\u0646\u064a\u0629 (\u0645\u062b\u0644 \u0631\u0624\u064a\u0629 \u0643\u0627\u0631\u0644 \u0631\u0648\u062c\u0631\u0632) \u062a\u0631\u0643\u0632 \u0623\u0633\u0627\u0633\u0627\u064b \u0639\u0644\u0649:",B.abb,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0645\u0634\u0627\u0639\u0631\u060c \u0627\u0644\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0630\u0627\u062a\u064a\u0629\u060c \u0627\u0644\u062a\u0648\u062c\u064a\u0647 \u0627\u0644\u0630\u0627\u062a\u064a \u0644\u0644\u0645\u062a\u0639\u0644\u0645 \u0648\u0627\u0644\u0639\u0644\u0627\u0642\u0629 \u0627\u0644\u0625\u0646\u0633\u0627\u0646\u064a\u0629 \u0627\u0644\u0625\u064a\u062c\u0627\u0628\u064a\u0629.",u.C)
B.Yy=s(["\u0628\u062d\u062b \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0627\u0644\u0641\u0631\u062f\u064a \u0639\u0646 \u0627\u0644\u062d\u0644\u0648\u0644 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u062a\u0645\u062b\u0644\u062a\u0647.","\u0625\u0636\u0641\u0627\u0621 \u0627\u0644\u0635\u0628\u063a\u0629 \u0627\u0644\u0631\u0633\u0645\u064a\u0629 \u0648\u0627\u0644\u0645\u0648\u0636\u0648\u0639\u064a\u0629 \u0639\u0644\u0649 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a \u0648\u0628\u0646\u0627\u0621 \u0627\u0644\u062a\u0639\u0631\u064a\u0641 \u0648\u0627\u0644\u0642\u0627\u0639\u062f\u0629 \u0628\u0648\u0627\u0633\u0637\u0629 \u0627\u0644\u0645\u062f\u0631\u0633.","\u062a\u0628\u0627\u062f\u0644 \u0627\u0644\u0631\u0645\u0648\u0632 \u0648\u0627\u0644\u0635\u064a\u0627\u063a\u0627\u062a \u0628\u064a\u0646 \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u062f\u0627\u062e\u0644 \u0627\u0644\u0645\u062c\u0645\u0648\u0639\u0627\u062a.","\u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u062d\u062c\u062c \u0648\u0627\u0644\u0628\u0631\u0627\u0647\u064a\u0646 \u0644\u0644\u062a\u0631\u062c\u064a\u062d \u0628\u064a\u0646 \u0627\u0644\u0635\u064a\u0627\u063a\u0627\u062a."],t.s)
B.aq8=new A.c("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'21. \u0648\u0641\u0642 \u0646\u0638\u0631\u064a\u0629 \u0627\u0644\u0648\u0636\u0639\u064a\u0627\u062a \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a\u0629 \u0644\u0640 "\u063a\u064a \u0628\u0631\u0648\u0633\u0648" (Guy Brousseau)\u060c \u0645\u0631\u062d\u0644\u0629 "\u0627\u0644\u0645\u0623\u0633\u0633\u0629" ( Institutionnalisation ) \u062a\u0639\u0646\u064a:',B.Yy,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0625\u0636\u0641\u0627\u0621 \u0627\u0644\u0635\u0628\u063a\u0629 \u0627\u0644\u0631\u0633\u0645\u064a\u0629 \u0648\u0627\u0644\u0645\u0648\u0636\u0648\u0639\u064a\u0629 \u0639\u0644\u0649 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a \u0648\u0628\u0646\u0627\u0621 \u0627\u0644\u062a\u0639\u0631\u064a\u0641 \u0648\u0627\u0644\u0642\u0627\u0639\u062f\u0629 \u0628\u0648\u0627\u0633\u0637\u0629 \u0627\u0644\u0645\u062f\u0631\u0633.",u.C)
B.a4g=s(["\u0627\u0644\u0628\u062f\u0621 \u0645\u0628\u0627\u0634\u0631\u0629 \u0628\u0627\u0644\u0631\u0645\u0648\u0632 \u0648\u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u062b\u0645 \u0627\u0644\u0627\u0646\u062a\u0642\u0627\u0644 \u0644\u0644\u0631\u0633\u0648\u0645 \u0627\u0644\u0628\u064a\u0627\u0646\u064a\u0629.","\u0627\u0644\u0627\u0646\u0637\u0644\u0627\u0642 \u0645\u0646 \u0627\u0644\u0645\u0646\u0627\u0648\u0644\u0629 \u0628\u0627\u0644\u064a\u062f \u0644\u0644\u0648\u0633\u0627\u0626\u0644 \u0648\u0627\u0644\u0623\u0634\u064a\u0627\u0621 \u0627\u0644\u0645\u0627\u062f\u064a\u0629\u060c \u062b\u0645 \u0634\u0628\u0647 \u0627\u0644\u0645\u062d\u0633\u0648\u0633 (\u0627\u0644\u0635\u0648\u0631 \u0648\u0627\u0644\u0631\u0633\u0648\u0645)\u060c \u0648\u0635\u0648\u0644\u0627\u064b \u0625\u0644\u0649 \u0627\u0644\u0645\u062c\u0631\u062f (\u0627\u0644\u0631\u0645\u0648\u0632).","\u0627\u0644\u0627\u0642\u062a\u0635\u0627\u0631 \u0639\u0644\u0649 \u0627\u0644\u0645\u0633\u0627\u0626\u0644 \u0627\u0644\u0644\u0641\u0638\u064a\u0629 \u0627\u0644\u0645\u0643\u062a\u0648\u0628\u0629 \u0628\u0627\u0644\u0646\u0635.","\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u062d\u0627\u0633\u0628\u0629 \u0627\u0644\u0622\u0644\u064a\u0629 \u0641\u064a \u062c\u0645\u064a\u0639 \u0627\u0644\u062d\u0635\u0635."],t.s)
B.alU=new A.c("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'22. \u0641\u064a \u0645\u0627\u062f\u0629 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a \u0628\u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a\u0629\u060c \u0627\u0644\u0645\u0628\u062f\u0623 \u0627\u0644\u0645\u0646\u0647\u062c\u064a \u0627\u0644\u0645\u0646\u0627\u062f\u064a \u0628\u0640 "\u0627\u0644\u0627\u0646\u0637\u0644\u0627\u0642 \u0645\u0646 \u0627\u0644\u0645\u062d\u0633\u0648\u0633 \u0625\u0644\u0649 \u0627\u0644\u0645\u062c\u0631\u062f" \u064a\u0642\u062a\u0636\u064a:',B.a4g,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0627\u0646\u0637\u0644\u0627\u0642 \u0645\u0646 \u0627\u0644\u0645\u0646\u0627\u0648\u0644\u0629 \u0628\u0627\u0644\u064a\u062f \u0644\u0644\u0648\u0633\u0627\u0626\u0644 \u0648\u0627\u0644\u0623\u0634\u064a\u0627\u0621 \u0627\u0644\u0645\u0627\u062f\u064a\u0629\u060c \u062b\u0645 \u0634\u0628\u0647 \u0627\u0644\u0645\u062d\u0633\u0648\u0633 (\u0627\u0644\u0635\u0648\u0631 \u0648\u0627\u0644\u0631\u0633\u0648\u0645)\u060c \u0648\u0635\u0648\u0644\u0627\u064b \u0625\u0644\u0649 \u0627\u0644\u0645\u062c\u0631\u062f (\u0627\u0644\u0631\u0645\u0648\u0632).",u.C)
