B.as9=new A.c("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'35. \u064a\u064f\u0639\u0631\u0641 "\u0627\u0644\u063a\u0631\u0627\u0641\u064a\u0645" (Grapheme) \u0628\u0623\u0646\u0647:',B.Tv,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u062a\u0645\u062b\u064a\u0644 \u0627\u0644\u062e\u0637\u0627\u0626\u064a/\u0627\u0644\u0643\u062a\u0627\u0628\u064a \u0644\u0644\u0641\u0648\u0646\u064a\u0645 (\u0627\u0644\u062d\u0631\u0641 \u0627\u0644\u0645\u0643\u062a\u0648\u0628).",u.C)
B.aac=s(["\u0627\u0644\u062a\u062f\u0631\u064a\u0633 \u0647\u0648 \u0646\u0634\u0627\u0637 \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u060c \u0648\u0627\u0644\u062a\u0639\u0644\u0645 \u0647\u0648 \u0646\u0634\u0627\u0637 \u0627\u0644\u0645\u062f\u0631\u0633.","\u0627\u0644\u062a\u062f\u0631\u064a\u0633 \u0641\u0639\u0644 \u0623\u0641\u0639\u0627\u0644 \u0648\u0645\u0645\u0627\u0631\u0633\u0627\u062a \u0642\u0635\u064a\u0629 \u064a\u0642\u0648\u0645 \u0628\u0647\u0627 \u0627\u0644\u0645\u0639\u0644\u0645 \u0644\u062a\u0633\u0647\u064a\u0644 \u0627\u0644\u062a\u0639\u0644\u0645\u060c \u0648\u0627\u0644\u062a\u0639\u0644\u0645 \u0647\u0648 \u0627\u0644\u062a\u063a\u064a\u0631 \u0627\u0644\u0634\u0628\u0647 \u0627\u0644\u062f\u0627\u0626\u0645 \u0641\u064a \u0633\u0644\u0648\u0643 \u0627\u0644\u0645\u0639\u0627\u0631\u0641 \u0644\u062f\u0649 \u0627\u0644\u0645\u062a\u0639\u0644\u0645.","\u0644\u0627 \u064a\u0648\u062c\u062f \u0623\u064a \u0641\u0631\u0642 \u0628\u064a\u0646\u0647\u0645\u0627 \u0648\u0647\u0645\u0627 \u0645\u0635\u0637\u0644\u062d\u0627\u0646 \u0644\u0634\u064a\u0621 \u0648\u0627\u062d\u062f.","\u0627\u0644\u062a\u062f\u0631\u064a\u0633 \u064a\u062a\u0639\u0644\u0642 \u0628\u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0645\u0627\u0644\u064a \u0641\u0642\u0637."],t.s)
B.ap4=new A.c("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'36. \u064a\u0643\u0645\u0646 \u0627\u0644\u0641\u0631\u0642 \u0627\u0644\u0631\u0626\u064a\u0633\u064a \u0628\u064a\u0646 "\u0627\u0644\u062a\u062f\u0631\u064a\u0633" \u0648 "\u0627\u0644\u062a\u0639\u0644\u0651\u0645" \u0641\u064a \u0623\u0646:',B.aac,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u062a\u062f\u0631\u064a\u0633 \u0641\u0639\u0644 \u0623\u0641\u0639\u0627\u0644 \u0648\u0645\u0645\u0627\u0631\u0633\u0627\u062a \u0642\u0635\u064a\u0629 \u064a\u0642\u0648\u0645 \u0628\u0647\u0627 \u0627\u0644\u0645\u0639\u0644\u0645 \u0644\u062a\u0633\u0647\u064a\u0644 \u0627\u0644\u062a\u0639\u0644\u0645\u060c \u0648\u0627\u0644\u062a\u0639\u0644\u0645 \u0647\u0648 \u0627\u0644\u062a\u063a\u064a\u0631 \u0627\u0644\u0634\u0628\u0647 \u0627\u0644\u062f\u0627\u0626\u0645 \u0641\u064a \u0633\u0644\u0648\u0643 \u0627\u0644\u0645\u0639\u0627\u0631\u0641 \u0644\u062f\u0649 \u0627\u0644\u0645\u062a\u0639\u0644\u0645.",u.C)
B.WC=s(["\u062a\u0644\u062e\u064a\u0635 \u0627\u0644\u0646\u0635 \u0648\u0635\u064a\u0627\u063a\u0629 \u0627\u0644\u0641\u0643\u0631\u0629 \u0627\u0644\u0639\u0627\u0645\u0629.","\u062a\u0635\u0641\u062d \u0627\u0644\u0639\u0646\u0648\u0627\u0646\u060c \u0627\u0644\u0635\u0648\u0631\u060c \u0627\u0644\u062a\u0646\u0628\u0624 \u0628\u0645\u0648\u0636\u0648\u0639 \u0627\u0644\u0646\u0635\u060c \u0648\u0627\u0633\u062a\u062f\u0639\u0627\u0621 \u0627\u0644\u0645\u0639\u0627\u0631\u0641 \u0627\u0644\u0642\u0628\u0644\u064a\u0629.","\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0639\u0646 \u0623\u0633\u0626\u0644\u0629 \u0627\u0644\u0641\u0647\u0645 \u0627\u0644\u062f\u0642\u064a\u0642\u0629 \u0648\u0627\u0644\u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u0639\u0645\u064a\u0642.","\u0627\u0633\u062a\u062e\u0631\u0627\u062c \u0627\u0644\u0642\u0648\u0627\u0639\u062f \u0627\u0644\u0646\u062d\u0648\u064a\u0629 \u0645\u0646 \u0627\u0644\u0646\u0635."],t.s)
B.ap5=new A.c("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'37. \u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0639\u0627\u0626\u0644\u0629 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 (\u0645\u062b\u0644: \u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0645\u0627 \u0642\u0628\u0644 \u0627\u0644\u0642\u0631\u0627\u0621\u0629\u060c \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0642\u0631\u0627\u0621\u0629\u060c \u0628\u0639\u062f \u0627\u0644\u0642\u0631\u0627\u0621\u0629) \u062a\u0634\u0645\u0644 \u0641\u064a \u0645\u0631\u062d\u0644\u0629 "\u0645\u0627 \u0642\u0628\u0644 \u0627\u0644\u0642\u0631\u0627\u0621\u0629":',B.WC,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u0635\u0641\u062d \u0627\u0644\u0639\u0646\u0648\u0627\u0646\u060c \u0627\u0644\u0635\u0648\u0631\u060c \u0627\u0644\u062a\u0646\u0628\u0624 \u0628\u0645\u0648\u0636\u0648\u0639 \u0627\u0644\u0646\u0635\u060c \u0648\u0627\u0633\u062a\u062f\u0639\u0627\u0621 \u0627\u0644\u0645\u0639\u0627\u0631\u0641 \u0627\u0644\u0642\u0628\u0644\u064a\u0629.",u.C)
B.abz=s(["\u064a\u062a\u0623\u062e\u0631 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0639\u0646 \u0648\u0642\u062a \u0627\u0644\u062d\u0635\u0629.","\u064a\u0633\u062a\u0628\u062f\u0644 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0645\u0648\u0636\u0648\u0639 \u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0644\u0623\u0635\u0644\u064a \u0628\u0627\u0644\u062a\u0631\u0643\u064a\u0632 \u0627\u0644\u0645\u0641\u0631\u0637 \u0639\u0644\u0649 \u0623\u062f\u0627\u0629 \u0623\u0648 \u0648\u0633\u064a\u0644\u0629 \u0645\u0633\u0627\u0639\u062f\u0629 \u062a\u062d\u0648\u0644 \u0627\u0644\u0647\u062f\u0641 \u0627\u0644\u062b\u0627\u0646\u0648\u064a \u0625\u0644\u0649 \u0645\u0648\u0636\u0648\u0639 \u0623\u0633\u0627\u0633\u064a.","\u064a\u062e\u0631\u062c \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0625\u0644\u0649 \u0633\u0627\u062d\u0629 \u0627\u0644\u0627\u0633\u062a\u0631\u0627\u062d\u0629.","\u064a\u0646\u0633\u0649 \u0627\u0644\u062a\u0644\u0645\u064a\u0630 \u0623\u062f\u0648\u0627\u062a\u0647 \u0627\u0644\u0645\u062f\u0631\u0633\u064a."],t.s)
B.akL=new A.c("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'38. "\u0627\u0644\u0627\u0646\u0632\u0644\u0627\u0642 \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a" (Glissement didactique) \u0647\u0648 \u0627\u0646\u062d\u0631\u0627\u0641 \u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a \u064a\u062d\u062f\u062b \u0639\u0646\u062f\u0645\u0627:',B.abz,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u064a\u0633\u062a\u0628\u062f\u0644 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0645\u0648\u0636\u0648\u0639 \u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0644\u0623\u0635\u0644\u064a \u0628\u0627\u0644\u062a\u0631\u0643\u064a\u0632 \u0627\u0644\u0645\u0641\u0631\u0637 \u0639\u0644\u0649 \u0623\u062f\u0627\u0629 \u0623\u0648 \u0648\u0633\u064a\u0644\u0629 \u0645\u0633\u0627\u0639\u062f\u0629 \u062a\u062d\u0648\u0644 \u0627\u0644\u0647\u062f\u0641 \u0627\u0644\u062b\u0627\u0646\u0648\u064a \u0625\u0644\u0649 \u0645\u0648\u0636\u0648\u0639 \u0623\u0633\u0627\u0633\u064a.",u.C)
B.a3w=s(["\u0623\u062f\u0648\u0627\u062a \u0646\u0627\u062f\u0631\u0629 \u0644\u0627 \u062a\u0639\u0628\u0631 \u0639\u0646 \u0627\u0644\u062a\u0646\u0627\u0633\u0628.","\u0646\u0645\u0627\u0630\u062c \u0648\u062a\u0645\u062b\u064a\u0644\u0627\u062a \u0631\u064a\u0627\u0636\u064a\u0629 \u0631\u0626\u064a\u0633\u064a\u0629 \u0644\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0648\u062c\u0648\u062f \u0639\u0644\u0627\u0642\u0629 \u062a\u0646\u0627\u0633\u0628\u064a\u0629.","\u062f\u0631\u0633 \u062e\u0627\u0635 \u0628\u0627\u0644\u0647\u0646\u062f\u0633\u0629 \u0627\u0644\u0641\u0636\u0627\u0626\u064a\u0629 \u0641\u0642\u0637.","\u0623\u062e\u0637\u0627\u0621 \u0634\u0627\u0626\u0639\u0629 \u064a\u062c\u0628 \u062a\u062c\u0646\u0628\u0647\u0627."],t.s)
B.arQ=new A.c("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,"39. \u0641\u064a \u062a\u062f\u0631\u064a\u0633 \u0627\u0644\u062a\u0646\u0627\u0633\u0628\u064a\u0629 \u0628\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a\u060c \u062a\u064f\u0639\u062a\u0628\u0631 \u0627\u0644\u062c\u062f\u0648\u0644 \u0648\u0627\u0644\u062a\u0645\u062b\u064a\u0644 \u0627\u0644\u0628\u064a\u0627\u0646\u064a \u0628\u0627\u0644\u062e\u0637 \u0627\u0644\u0645\u0633\u062a\u0642\u064a\u0645 \u0627\u0644\u0645\u0631 \u0628\u0627\u0644\u0645\u0631\u0643\u0628 (\u0627\u0644\u0645\u0628\u062f\u0623):",B.a3w,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0646\u0645\u0627\u0630\u062c \u0648\u062a\u0645\u062b\u064a\u0644\u0627\u062a \u0631\u064a\u0627\u0636\u064a\u0629 \u0631\u0626\u064a\u0633\u064a\u0629 \u0644\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0648\u062c\u0648\u062f \u0639\u0644\u0627\u0642\u0629 \u062a\u0646\u0627\u0633\u0628\u064a\u0629.",u.C)
B.a5_=s(["\u0642\u064a\u0627\u0645 \u0627\u0644\u0645\u062f\u0631\u0633 \u0628\u0625\u0639\u0637\u0627\u0621 \u0627\u0644\u062d\u0644 \u0623\u0648 \u062a\u0648\u062c\u064a\u0647 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0628\u0625\u0634\u0627\u0631\u0627\u062a \u0645\u0643\u0634\u0648\u0641\u0629 \u062a\u062d\u0631\u0645\u0647 \u0645\u0646 \u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0639\u0627\u0626\u0642 \u0627\u0644\u0645\u0639\u0631\u0641\u064a.","\u063a\u064a\u0627\u0628 \u0627\u0644\u0648\u0633\u0627\u0626\u0644 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629.","\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0623\u062c\u0646\u0628\u064a\u0629 \u062f\u0627\u062e\u0644 \u0627\u0644\u0641\u0635\u0644.","\u0635\u0631\u0627\u0645\u0629 \u0627\u0644\u0627\u0645\u062a\u062d\u0627\u0646\u0627\u062a \u0627\u0644\u0648\u0637\u0646\u064a\u0629."],t.s)
B.alQ=new A.c("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'40. \u064a\u0647\u062f\u0641 "\u0645\u0641\u0647\u0648\u0645 \u0623\u062b\u0631 \u0646\u0648\u0628\u064a\u0644" (Effet Topaze) \u0641\u064a \u0627\u0644\u0623\u062f\u0628\u064a\u0627\u062a \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a\u0629 \u0625\u0644\u0649 \u0627\u0644\u062a\u0646\u0628\u064a\u0647 \u0645\u0646:',B.a5_,0,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0642\u064a\u0627\u0645 \u0627\u0644\u0645\u062f\u0631\u0633 \u0628\u0625\u0639\u0637\u0627\u0621 \u0627\u0644\u062d\u0644 \u0623\u0648 \u062a\u0648\u062c\u064a\u0647 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0628\u0625\u0634\u0627\u0631\u0627\u062a \u0645\u0643\u0634\u0648\u0641\u0629 \u062a\u062d\u0631\u0645\u0647 \u0645\u0646 \u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0639\u0627\u0626\u0642 \u0627\u0644\u0645\u0639\u0631\u0641\u064a.",u.C)
