B.amx=new A.c("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,"49. \u0627\u0644\u0631\u0627\u0641\u0639\u0629 \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629 \u0644\u0644\u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u0625\u0637\u0627\u0631 51.17 \u0644\u0625\u0631\u0633\u0627\u0621 \u0645\u062f\u0631\u0633\u0629 \u0627\u0644\u0627\u0646\u0635\u0627\u0641 \u0648\u062a\u0643\u0627\u0641\u0624 \u0627\u0644\u0641\u0631\u0635 \u062a\u0631\u0643\u0632 \u0639\u0644\u0649:",B.VA,0,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u0639\u0645\u064a\u0645 \u062a\u0639\u0644\u064a\u0645 \u0623\u0648\u0644\u064a \u0630\u064a \u062c\u0648\u062f\u0629 \u0648\u062a\u062c\u0647\u064a\u0632 \u0627\u0644\u0645\u0624\u0633\u0633\u0627\u062a \u0648\u062a\u062d\u062f\u064a\u062f \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0627\u0644\u062f\u0627\u0645\u062c\u0629.",u.C)
B.a9N=s(["\u0627\u062e\u062a\u0628\u0627\u0631\u0627\u062a PISA \u0627\u0644\u062f\u0648\u0644\u064a\u0629.","\u0631\u0648\u0627\u0626\u0632 \u0627\u0644\u062a\u0645\u0648\u0642\u0639 (Diagnostic testing) \u0644\u062a\u062d\u062f\u064a\u062f \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u062a\u0644\u0645\u064a\u0630 \u0627\u0644\u062d\u0642\u064a\u0642\u064a \u0628\u0639\u064a\u062f\u0627\u064b \u0639\u0646 \u0645\u0633\u062a\u0648\u0627\u0647 \u0627\u0644\u062f\u0631\u0627\u0633\u064a \u0627\u0644\u0635\u0648\u0631\u064a.","\u0627\u0645\u062a\u062d\u0627\u0646\u0627\u062a \u0627\u0644\u0628\u0643\u0627\u0644\u0648\u0631\u064a\u0627.","\u0631\u0648\u0627\u0626\u0632 \u0642\u064a\u0627\u0633 \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0646\u0641\u0633\u064a IQ."],t.s)
B.asz=new A.c("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'50. \u0627\u0644\u062a\u0642\u064a\u064a\u0645 \u0627\u0644\u0645\u0624\u0633\u0633\u064a \u0627\u0644\u0623\u0648\u0644 \u0644\u0628\u0631\u0646\u0627\u0645\u062c "\u0645\u0624\u0633\u0633\u0627\u062a \u0627\u0644\u0631\u064a\u0627\u062f\u0629" \u0641\u064a \u0645\u0627\u062f\u0629 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a \u0648\u0627\u0644\u0644\u063a\u0627\u062a \u0623\u0638\u0647\u0631 \u0627\u0639\u062a\u0645\u0627\u062f \u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631\u0627\u062a \u0627\u0644\u0627\u0633\u062a\u0626\u0646\u0627\u0633\u064a\u0629 \u0627\u0644\u0645\u0633\u0645\u0627\u0629:',B.a9N,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0631\u0648\u0627\u0626\u0632 \u0627\u0644\u062a\u0645\u0648\u0642\u0639 (Diagnostic testing) \u0644\u062a\u062d\u062f\u064a\u062f \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u062a\u0644\u0645\u064a\u0630 \u0627\u0644\u062d\u0642\u064a\u0642\u064a \u0628\u0639\u064a\u062f\u0627\u064b \u0639\u0646 \u0645\u0633\u062a\u0648\u0627\u0647 \u0627\u0644\u062f\u0631\u0627\u0633\u064a \u0627\u0644\u0635\u0648\u0631\u064a.",u.C)
B.a6n=s(["\u0645\u062f\u0631\u0633\u0629 \u0627\u0644\u0646\u062c\u0627\u062d \u0648\u062a\u0648\u0641\u064a\u0631 \u0627\u0644\u0645\u0646\u062d.","\u0627\u0644\u0623\u0646\u062f\u064a\u0629 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0629 \u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a\u0629.","\u0627\u0644\u0639\u0644\u0627\u0645\u0629 \u0627\u0644\u062a\u062c\u0627\u0631\u064a\u0629 \u0644\u0644\u0645\u0624\u0633\u0633\u0627\u062a \u0627\u0644\u0627\u0633\u062a\u062b\u0645\u0627\u0631\u064a\u0629.","\u0645\u0624\u0633\u0633\u0627\u062a \u0627\u0644\u0631\u064a\u0627\u062f\u0629 (\xc9coles pionni\xe8res) \u0627\u0644\u0645\u062c\u0647\u0632\u0629 \u0628\u0627\u0644\u062a\u0643\u0646\u0648\u0644\u0648\u062c\u064a\u0627 \u0648\u0627\u0644\u0648\u0633\u0627\u0626\u0644 \u0627\u0644\u062d\u062f\u064a\u062b\u0629 \u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u0645\u0645\u0646\u0647\u062c."],t.s)
