B.a4T=s(["\u062a\u062f\u0631\u064a\u0633 \u0623\u0633\u0628\u0648\u0639 \u0628\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0648\u0623\u0633\u0628\u0648\u0639 \u0628\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0641\u0631\u0646\u0633\u064a\u0629.","\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u062e\u064a\u0627\u0631 \u0627\u0644\u0644\u063a\u0648\u064a \u0627\u0644\u0645\u0632\u062f\u0648\u062c \u0644\u062a\u062f\u0631\u064a\u0633 \u0628\u0639\u0636 \u0627\u0644\u0645\u0648\u0627\u062f \u0623\u0648 \u0628\u0639\u0636 \u0627\u0644\u0645\u0636\u0627\u0645\u064a\u0646 \u0627\u0644\u0645\u062c\u0627\u0644\u0627\u062a (\u0645\u062b\u0644 \u0627\u0644\u0639\u0644\u0645\u064a\u0629 \u0648\u0627\u0644\u062a\u0642\u0646\u064a\u0629) \u0628\u0644\u063a\u0627\u062a \u0623\u062c\u0646\u0628\u064a\u0629.","\u062a\u0631\u062c\u0645\u0629 \u0643\u0644 \u0643\u0644\u0645\u0629 \u064a\u0644\u0642\u064a\u0647\u0627 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0641\u0648\u0631\u064a\u0627\u064b \u0644\u0644\u063a\u0629 \u062b\u0627\u0646\u064a\u0629.","\u062a\u062f\u0631\u064a\u0633 \u0627\u0644\u0644\u063a\u0627\u062a \u0641\u064a \u0627\u0644\u0641\u062a\u0631\u0629 \u0627\u0644\u0645\u0633\u0627\u0626\u064a\u0629 \u0641\u0642\u0637."],t.s)
B.al6=new A.c("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'53. \u0622\u0644\u064a\u0629 "\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0627\u0644\u0644\u063a\u0648\u064a" (Alternance linguistique) \u062a\u0646\u0635 \u0639\u0644\u0649:',B.a4T,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u062e\u064a\u0627\u0631 \u0627\u0644\u0644\u063a\u0648\u064a \u0627\u0644\u0645\u0632\u062f\u0648\u062c \u0644\u062a\u062f\u0631\u064a\u0633 \u0628\u0639\u0636 \u0627\u0644\u0645\u0648\u0627\u062f \u0623\u0648 \u0628\u0639\u0636 \u0627\u0644\u0645\u0636\u0627\u0645\u064a\u0646 \u0627\u0644\u0645\u062c\u0627\u0644\u0627\u062a (\u0645\u062b\u0644 \u0627\u0644\u0639\u0644\u0645\u064a\u0629 \u0648\u0627\u0644\u062a\u0642\u0646\u064a\u0629) \u0628\u0644\u063a\u0627\u062a \u0623\u062c\u0646\u0628\u064a\u0629.",u.C)
B.a97=s(["\u0639\u062f\u062f \u0627\u0644\u0645\u062f\u0631\u0633\u064a\u0646 \u0641\u064a \u0643\u0644 \u0645\u0624\u0633\u0633\u0629.","\u0627\u0644\u0647\u062f\u0631 \u0627\u0644\u0645\u062f\u0631\u0633\u064a \u0648\u0627\u0644\u0627\u0646\u0642\u0637\u0627\u0639 \u0639\u0646 \u0627\u0644\u062f\u0631\u0627\u0633\u0629 \u0628\u0646\u0633\u0628\u0629 \u0627\u0644\u062b\u0644\u062b.","\u0627\u0644\u063a\u0644\u0627\u0641 \u0627\u0644\u0632\u0645\u0646\u064a \u0644\u0644\u0645\u0648\u0627\u062f \u0627\u0644\u0639\u0644\u0645\u064a\u0629.","\u0639\u062f\u062f \u0627\u0644\u0645\u0641\u062a\u0634\u064a\u0646 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u064a\u0646."],t.s)
B.aqI=new A.c("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,"54. \u062a\u0647\u062f\u0641 \u0628\u0631\u0627\u0645\u062c \u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u0635\u0631\u064a\u062d \u0627\u0644\u0645\u0639\u062a\u0645\u062f\u0629 \u0641\u064a \u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u0645\u0648\u0627\u0632\u064a\u0629 \u0648\u0627\u0644\u0631\u064a\u0627\u0636\u0629 \u0628\u0627\u0644\u062e\u0627\u0631\u0637\u0629 \u0627\u0644\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0625\u0644\u0649 \u062a\u0642\u0644\u064a\u0635 \u0645\u0639\u062f\u0644:",B.a97,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0647\u062f\u0631 \u0627\u0644\u0645\u062f\u0631\u0633\u064a \u0648\u0627\u0644\u0627\u0646\u0642\u0637\u0627\u0639 \u0639\u0646 \u0627\u0644\u062f\u0631\u0627\u0633\u0629 \u0628\u0646\u0633\u0628\u0629 \u0627\u0644\u062b\u0644\u062b.",u.C)
B.aaD=s(["\u0627\u0644\u0645\u062e\u0637\u0637 \u0627\u0644\u0627\u0633\u062a\u0639\u062c\u0627\u0644\u064a 2.","\u0628\u0631\u0627\u0645\u062c \u0627\u0644\u0625\u0637\u0627\u0631 \u0627\u0644\u0625\u062c\u0631\u0627\u0626\u064a (\u0644\u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0645\u0634\u0627\u0631\u064a\u0639 \u0648\u0627\u0644\u0645\u0628\u0627\u062f\u0631\u0627\u062a \u0648\u0627\u0644\u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u0643\u064e\u0645\u064a\u0629 \u0627\u0644\u0645\u062d\u062f\u062f\u0629 \u0641\u064a \u0627\u0644\u0632\u0645\u0646).","\u0627\u0644\u0645\u0646\u0647\u0627\u062c \u0627\u0644\u0645\u0646\u0642\u062d \u0627\u0644\u062c\u062f\u064a\u062f \u0644\u0639\u0627\u0645 2030.","\u0646\u0638\u0627\u0645 \u0628\u0634\u0627\u0626\u0631 \u0627\u0644\u0645\u0648\u062d\u062f."],t.s)
B.ajm=new A.c("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,"55. \u064a\u0645\u062a\u062f \u0627\u0644\u0625\u0637\u0627\u0631 \u0627\u0644\u0625\u062c\u0631\u0627\u0626\u064a \u0644\u062a\u0646\u0632\u064a\u0644 \u062e\u0627\u0631\u0637\u0629 \u0627\u0644\u0637\u0631\u064a\u0642 2022-2026 \u0639\u0644\u0649 \u0623\u0633\u0627\u0633 \u0628\u0631\u0646\u0627\u0645\u062c\u064a \u0645\u0641\u0635\u0644 \u064a\u064f\u0639\u0631\u0641 \u0628\u0640:",B.aaD,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0628\u0631\u0627\u0645\u062c \u0627\u0644\u0625\u0637\u0627\u0631 \u0627\u0644\u0625\u062c\u0631\u0627\u0626\u064a (\u0644\u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0645\u0634\u0627\u0631\u064a\u0639 \u0648\u0627\u0644\u0645\u0628\u0627\u062f\u0631\u0627\u062a \u0648\u0627\u0644\u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u0643\u064e\u0645\u064a\u0629 \u0627\u0644\u0645\u062d\u062f\u062f\u0629 \u0641\u064a \u0627\u0644\u0632\u0645\u0646).",u.C)
B.a_F=s(["\u062e\u0637\u0623 \u062e\u0641\u064a\u0641\u0627\u064b \u064a\u062a\u0637\u0644\u0628 \u0627\u0644\u062a\u0646\u0628\u064a\u0647 \u0627\u0644\u0634\u0641\u0647\u064a \u0641\u0642\u0637.","\u0625\u062e\u0644\u0627\u0644\u0627\u064b \u0628\u0627\u0644\u0648\u0627\u062c\u0628 \u0627\u0644\u0645\u0647\u0646\u064a \u064a\u062a\u0631\u062a\u0628 \u0639\u0646\u0647 \u0627\u0644\u0627\u0642\u062a\u0637\u0627\u0639 \u0645\u0646 \u0627\u0644\u0623\u062c\u0631 \u0648\u062a\u0641\u0639\u064a\u0644 \u0645\u0633\u0637\u0631\u0629 \u062a\u0631\u0643 \u0627\u0644\u0648\u0638\u064a\u0641\u0629 \u0625\u0646 \u062a\u062c\u0627\u0648\u0632 \u0627\u0644\u0645\u062f\u062f \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064a\u0629.","\u0623\u0645\u0631\u0627\u064b \u0645\u0633\u0645\u0648\u062d\u0627\u064b \u0628\u0647 \u0637\u0627\u0644\u0645\u0627 \u064a\u062a\u0645 \u062a\u0639\u0648\u064a\u0636\u0647 \u0644\u0627\u062d\u0642\u0627\u064b.","\u0625\u062c\u0627\u0632\u0629 \u0627\u0633\u062a\u062b\u0646\u0627\u0626\u064a\u0629 \u062a\u0644\u0642\u0627\u0626\u064a\u0629."],t.s)
B.anF=new A.c("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'56. \u062d\u0633\u0628 \u0627\u0644\u0646\u0638\u0627\u0645 \u0627\u0644\u0623\u0633\u0627\u0633\u064a \u0627\u0644\u062e\u0627\u0635 \u0628\u0645\u0648\u0638\u0641\u064a \u0627\u0644\u0648\u0632\u0627\u0631\u0629 \u0627\u0644\u0645\u0643\u0644\u0641\u0629 \u0628\u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0627\u0644\u0648\u0637\u0646\u064a\u0629\u060c \u064a\u064f\u0639\u062a\u0628\u0631 \u062e\u0637\u0623 "\u062a\u063a\u064a\u0628 \u0627\u0644\u0645\u0639\u0644\u0645 \u063a\u064a\u0631 \u0627\u0644\u0645\u0634\u0631\u0648\u0639 \u0639\u0646 \u0627\u0644\u0639\u0645\u0644":',B.a_F,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0625\u062e\u0644\u0627\u0644\u0627\u064b \u0628\u0627\u0644\u0648\u0627\u062c\u0628 \u0627\u0644\u0645\u0647\u0646\u064a \u064a\u062a\u0631\u062a\u0628 \u0639\u0646\u0647 \u0627\u0644\u0627\u0642\u062a\u0637\u0627\u0639 \u0645\u0646 \u0627\u0644\u0623\u062c\u0631 \u0648\u062a\u0641\u0639\u064a\u0644 \u0645\u0633\u0637\u0631\u0629 \u062a\u0631\u0643 \u0627\u0644\u0648\u0638\u064a\u0641\u0629 \u0625\u0646 \u062a\u062c\u0627\u0648\u0632 \u0627\u0644\u0645\u062f\u062f \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064a\u0629.",u.C)
B.aal=s(["\u0627\u0644\u0645\u062c\u0644\u0633 \u0627\u0644\u062a\u0631\u0628\u0648\u064a.","\u0645\u062c\u0644\u0633 \u0627\u0644\u062a\u062f\u0628\u064a\u0631.","\u0645\u062c\u0627\u0644\u0633 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629.","\u0645\u062c\u0644\u0633 \u0627\u0644\u0627\u0646\u0636\u0628\u0627\u0637."],t.s)
B.apM=new A.c("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,"57. \u0627\u0644\u0645\u062c\u0644\u0633 \u0627\u0644\u0630\u064a \u064a\u0639\u062a\u0628\u0631 \u0627\u0644\u0647\u064a\u0623\u0629 \u0627\u0644\u0645\u0639\u0646\u064a\u0629 \u0628\u0627\u0644\u062a\u062f\u0628\u064a\u0631 \u0627\u0644\u0625\u062f\u0627\u0631\u064a \u0648\u0627\u0644\u0645\u0627\u0644\u064a \u0648\u0627\u0644\u0645\u0633\u062a\u0642\u0628\u0644\u064a \u0644\u0644\u0645\u0624\u0633\u0633\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629 \u0648\u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629 \u0639\u0644\u0649 \u0628\u0631\u0646\u0627\u0645\u062c \u0639\u0645\u0644\u0647\u0627 \u0627\u0644\u0633\u0646\u0648\u064a \u0647\u0648:",B.aal,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0645\u062c\u0644\u0633 \u0627\u0644\u062a\u062f\u0628\u064a\u0631.",u.C)
B.aaq=s(["\u0627\u0644\u0645\u062f\u064a\u0631\u060c \u0648\u0645\u0645\u062b\u0644 \u0639\u0646 \u0643\u0644 \u0645\u0633\u062a\u0648\u0649 \u062f\u0631\u0627\u0633\u064a \u0645\u0646 \u0623\u0637\u0631 \u0627\u0644\u062a\u062f\u0631\u064a\u0633\u060c \u0648\u0631\u0626\u064a\u0633 \u062c\u0645\u0639\u064a\u0629 \u0623\u0645\u0647\u0627\u062a \u0648\u0622\u0628\u0627\u0621 \u0648\u0623\u0648\u0644\u064a\u0627\u0621 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630.","\u0627\u0644\u0645\u062f\u064a\u0631 \u0648\u0627\u0644\u0643\u0627\u062a\u0628 \u0627\u0644\u0639\u0627\u0645 \u0641\u0642\u0637.","\u0627\u0644\u062d\u0627\u0631\u0633 \u0627\u0644\u0639\u0627\u0645 \u0648\u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0641\u0642\u0637.","\u0645\u0645\u062b\u0644 \u0627\u0644\u0645\u062f\u064a\u0631\u064a\u0629 \u0627\u0644\u0625\u0642\u0644\u064a\u0645\u064a\u0629 \u0648\u0627\u0644\u0633\u0644\u0637\u0629 \u0627\u0644\u0645\u062d\u0644\u064a\u0629."],t.s)
B.ajf=new A.c("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'58. \u064a\u062a\u0643\u0648\u0646 "\u0627\u0644\u0645\u062c\u0644\u0633 \u0627\u0644\u062a\u0631\u0628\u0648\u064a" \u0644\u0644\u0645\u0624\u0633\u0633\u0629 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a\u0629 \u0645\u0646:',B.aaq,0,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0645\u062f\u064a\u0631\u060c \u0648\u0645\u0645\u062b\u0644 \u0639\u0646 \u0643\u0644 \u0645\u0633\u062a\u0648\u0649 \u062f\u0631\u0627\u0633\u064a \u0645\u0646 \u0623\u0637\u0631 \u0627\u0644\u062a\u062f\u0631\u064a\u0633\u060c \u0648\u0631\u0626\u064a\u0633 \u062c\u0645\u0639\u064a\u0629 \u0623\u0645\u0647\u0627\u062a \u0648\u0622\u0628\u0627\u0621 \u0648\u0623\u0648\u0644\u064a\u0627\u0621 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630.",u.C)
B.a2j=s(["\u0627\u0644\u0639\u0632\u0644 \u0645\u0646 \u0627\u0644\u0648\u0638\u064a\u0641\u0629 \u062f\u0648\u0646 \u062a\u0641\u0648\u064a\u062a \u0627\u0644\u062d\u0642 \u0641\u064a \u0627\u0644\u0645\u0639\u0627\u0634.","\u0627\u0644\u0625\u0646\u0630\u0627\u0631 \u0648\u0627\u0644\u062a\u0648\u0628\u064a\u062e.","\u0627\u0644\u0627\u0646\u062d\u062f\u0627\u0631 \u0641\u064a \u0627\u0644\u0631\u062a\u0628\u0629.","\u0627\u0644\u062d\u0631\u0645\u0627\u0646 \u0645\u0646 \u0627\u0644\u0623\u062c\u0631 \u0644\u0645\u062f\u0629 \u0633\u0646\u0629."],t.s)
