B.aou=new A.c("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639","\u0641\u064a \u0623\u0633\u0628\u0648\u0639 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645 \u0648\u0627\u0644\u062a\u0648\u0644\u064a\u0641 (\u0627\u0644\u0623\u0633\u0628\u0648\u0639 5 \u0645\u0646 \u0627\u0644\u0648\u062d\u062f\u0629)\u060c \u062a\u062e\u0635\u0635 \u0627\u0644\u062d\u0635\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u0644\u0640:",B.a2i,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u0634\u062e\u064a\u0635 \u0627\u0644\u0645\u0643\u062a\u0633\u0628\u0627\u062a \u0648\u0631\u0635\u062f \u0627\u0644\u062a\u0639\u062b\u0631\u0627\u062a \u0648\u062a\u0642\u064a\u064a\u0645 \u0645\u0627 \u062a\u062d\u0642\u0642 \u0645\u0646 \u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u0648\u062d\u062f\u0629.",u.C)
B.aaP=s(["\u0627\u0644\u062d\u0635\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u0641\u0642\u0637 \u0645\u0646 \u0627\u0644\u0623\u0633\u0628\u0648\u0639 \u0627\u0644\u062e\u0627\u0645\u0633.","\u0627\u0644\u062d\u0635\u0635 \u0627\u0644\u0623\u0648\u0644\u0649 \u0648\u0627\u0644\u062b\u0627\u0646\u064a\u0629 \u0648\u0627\u0644\u062b\u0627\u0644\u062b\u0629 \u062f\u0648\u0646 \u0627\u0644\u062d\u0627\u062c\u0629 \u0644\u062a\u0642\u0648\u064a\u0645.","\u0627\u0644\u062d\u0635\u062a\u064a\u0646 3 \u06485 \u0644\u062a\u062c\u0627\u0648\u0632 \u0627\u0644\u062a\u0639\u062b\u0631\u0627\u062a \u0627\u0644\u0646\u0648\u0639\u064a\u0629 \u0628\u0639\u062f \u062a\u0641\u064a\u064a\u0626 \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.ajX=new A.c("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639","\u062a\u0644\u062c\u0623 \u0627\u0644\u0623\u0633\u062a\u0627\u0630\u0629 \u0625\u0644\u0649 \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0645\u0631\u0643\u0632\u0629 (Soutien cibl\xe9) \u0641\u064a \u062a\u062f\u0628\u064a\u0631 \u0623\u0633\u0628\u0648\u0639 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062a\u0648\u0644\u064a\u0641 \u062e\u0644\u0627\u0644:",B.aaP,2,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u062d\u0635\u062a\u064a\u0646 3 \u06485 \u0644\u062a\u062c\u0627\u0648\u0632 \u0627\u0644\u062a\u0639\u062b\u0631\u0627\u062a \u0627\u0644\u0646\u0648\u0639\u064a\u0629 \u0628\u0639\u062f \u062a\u0641\u064a\u064a\u0626 \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646.",u.C)
B.Yn=s(["\u0635\u0646\u0639 \u0645\u062c\u0633\u0645\u0627\u062a \u0628\u0644\u0627\u0633\u062a\u064a\u0643\u064a\u0629 \u0648\u0643\u0631\u062a\u0648\u0646\u064a\u0629 \u0644\u0644\u0647\u0646\u062f\u0633\u0629 \u0627\u0644\u0641\u0636\u0627\u0626\u064a\u0629.","\u062a\u062d\u0648\u064a\u0644 \u0645\u0633\u0623\u0644\u0629 \u0623\u0648 \u0648\u0636\u0639\u064a\u0629 \u0648\u0627\u0642\u0639\u064a\u0629 \u0625\u0644\u0649 \u0646\u0645\u0648\u0630\u062c \u0623\u0648 \u0635\u064a\u0627\u063a\u0629 \u0631\u064a\u0627\u0636\u064a\u0629 \u0648\u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0628\u0627\u0644\u0631\u0645\u0648\u0632.","\u062d\u0641\u0638 \u0635\u064a\u0627\u063a\u0627\u062a \u0627\u0644\u0642\u0648\u0627\u0646\u064a\u0646 \u0627\u0644\u062d\u0633\u0627\u0628\u064a\u0629 \u0648\u0627\u0633\u062a\u0638\u0647\u0627\u0631\u0647\u0627 \u0634\u0641\u0647\u064a\u0627\u064b.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.ajp=new A.c("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'\u062a\u064f\u0639\u0631\u0641 "\u0627\u0644\u0645\u0648\u062f\u064a\u0644\u0629" \u0623\u0648 \u0627\u0644\u0646\u0645\u0630\u062c\u0629 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a\u064a\u0629 (Mod\xe9lisation) \u0628\u0623\u0646\u0647\u0627:',B.Yn,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u062d\u0648\u064a\u0644 \u0645\u0633\u0623\u0644\u0629 \u0623\u0648 \u0648\u0636\u0639\u064a\u0629 \u0648\u0627\u0642\u0639\u064a\u0629 \u0625\u0644\u0649 \u0646\u0645\u0648\u0630\u062c \u0623\u0648 \u0635\u064a\u0627\u063a\u0629 \u0631\u064a\u0627\u0636\u064a\u0629 \u0648\u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0628\u0627\u0644\u0631\u0645\u0648\u0632.",u.C)
B.a7Y=s(["\u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u0645\u0641\u0647\u0648\u0645 \u0643\u0627\u0645\u0644\u0627\u064b \u0648\u0628\u0634\u0643\u0644 \u0645\u0641\u0635\u0644 \u0641\u064a \u0645\u0633\u062a\u0648\u0649 \u062f\u0631\u0627\u0633\u064a \u0648\u0627\u062d\u062f \u062b\u0645 \u0625\u063a\u0644\u0627\u0642\u0647.","\u0625\u0639\u0637\u0627\u0621 \u0627\u0644\u0645\u0641\u0627\u0647\u064a\u0645 \u0627\u0644\u0635\u0639\u0628\u0629 \u0641\u064a \u0627\u0644\u0633\u0646\u0648\u0627\u062a \u0627\u0644\u0623\u0648\u0644\u0649 \u0648\u062a\u0628\u0633\u064a\u0637\u0647\u0627 \u0641\u064a \u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a \u0627\u0644\u0639\u0644\u064a\u0627.","\u0627\u0644\u0639\u0648\u062f\u0629 \u0644\u0646\u0641\u0633 \u0627\u0644\u0645\u0641\u0647\u0648\u0645 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a\u064a \u0639\u0628\u0631 \u0645\u0633\u062a\u0648\u064a\u0627\u062a \u0645\u062a\u062a\u0627\u0628\u0639\u0629 \u0645\u0639 \u0627\u0644\u062a\u0648\u0633\u0639 \u0648\u0627\u0644\u0639\u0645\u0642 \u0648\u0627\u0644\u062a\u062c\u0631\u064a\u062f \u0627\u0644\u062a\u062f\u0631\u064a\u062c\u064a.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.asD=new A.c("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639","\u0627\u0644\u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u062d\u0644\u0632\u0648\u0646\u064a (Approche spiralaire) \u0644\u0644\u0645\u0641\u0627\u0647\u064a\u0645 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a\u064a\u0629 \u064a\u0642\u062a\u0636\u064a:",B.a7Y,2,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0639\u0648\u062f\u0629 \u0644\u0646\u0641\u0633 \u0627\u0644\u0645\u0641\u0647\u0648\u0645 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a\u064a \u0639\u0628\u0631 \u0645\u0633\u062a\u0648\u064a\u0627\u062a \u0645\u062a\u062a\u0627\u0628\u0639\u0629 \u0645\u0639 \u0627\u0644\u062a\u0648\u0633\u0639 \u0648\u0627\u0644\u0639\u0645\u0642 \u0648\u0627\u0644\u062a\u062c\u0631\u064a\u062f \u0627\u0644\u062a\u062f\u0631\u064a\u062c\u064a.",u.C)
B.a41=s(["\u0625\u0644\u063a\u0627\u0621 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u0627\u0644\u0631\u0645\u0648\u0632 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a\u064a\u0629 \u0627\u0644\u0645\u0648\u062d\u062f\u0629.","\u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a \u0628\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0641\u0631\u0646\u0633\u064a\u0629 \u0648\u062a\u0648\u0638\u064a\u0641 \u0645\u0635\u0637\u0644\u062d\u0627\u062a\u0647\u0627 \u0627\u0644\u0639\u0644\u0645\u064a\u0629 \u0628\u0627\u0644\u062a\u0648\u0627\u0632\u064a \u0645\u0639 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0648\u0637\u0646\u064a\u0629 \u0644\u062a\u0647\u064a\u0626\u062a\u0647\u0645 \u0644\u0644\u0645\u0633\u062a\u0642\u0628\u0644.","\u062a\u0631\u062c\u0645\u0629 \u0627\u0644\u062d\u0635\u0635 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0643\u0644\u0645\u0629 \u0628\u0643\u0644\u0645\u0629 \u0634\u0641\u0647\u064a\u0627\u064b.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.akj=new A.c("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639","\u0627\u0644\u062a\u0646\u0633\u064a\u0642 \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a \u0648\u0627\u0644\u062a\u062f\u0631\u064a\u0633 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0627\u0644\u0644\u063a\u0648\u064a \u0641\u064a \u0645\u0627\u062f\u0629 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a \u064a\u0647\u062f\u0641 \u0625\u0644\u0649:",B.a41,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a \u0628\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0641\u0631\u0646\u0633\u064a\u0629 \u0648\u062a\u0648\u0638\u064a\u0641 \u0645\u0635\u0637\u0644\u062d\u0627\u062a\u0647\u0627 \u0627\u0644\u0639\u0644\u0645\u064a\u0629 \u0628\u0627\u0644\u062a\u0648\u0627\u0632\u064a \u0645\u0639 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0648\u0637\u0646\u064a\u0629 \u0644\u062a\u0647\u064a\u0626\u062a\u0647\u0645 \u0644\u0644\u0645\u0633\u062a\u0642\u0628\u0644.",u.C)
B.ac1=s(["\u0645\u0646\u062d \u0646\u0642\u0627\u0637 \u0625\u0634\u0647\u0627\u062f\u064a\u0629 \u062a\u064f\u0633\u062c\u0644 \u0641\u064a \u0645\u0633\u0627\u0631 \u0644\u0644\u062a\u0644\u0627\u0645\u064a\u0630.","\u0631\u0635\u062f \u0627\u0644\u062c\u0627\u0647\u0632\u064a\u0629 \u0648\u0627\u0644\u062d\u062f\u0648\u062f \u0627\u0644\u0642\u0628\u0644\u064a\u0629 \u0644\u062a\u0634\u062e\u064a\u0635 \u0627\u0644\u062a\u0639\u062b\u0631\u0627\u062a \u0648\u0628\u0646\u0627\u0621 \u062e\u0637\u0629 \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0645\u0628\u0643\u0631\u0629.","\u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u0648\u0631\u0633\u0645 \u0633\u0644\u0645 \u0644\u0644\u062a\u0641\u0648\u0642 \u0648\u0627\u0644\u0631\u0633\u0648\u0628 \u062f\u0627\u062e\u0644 \u0627\u0644\u0645\u062f\u0631\u0633\u0629.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aiS=new A.c("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639","\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0634\u062e\u064a\u0635\u064a \u0644\u0644\u0645\u0633\u062a\u0644\u0632\u0645\u0627\u062a \u0641\u064a \u0628\u062f\u0627\u064a\u0629 \u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u062f\u0631\u0627\u0633\u064a\u0629 \u064a\u0647\u062f\u0641 \u0623\u0633\u0627\u0633\u0627\u064b \u0625\u0644\u0649:",B.ac1,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0631\u0635\u062f \u0627\u0644\u062c\u0627\u0647\u0632\u064a\u0629 \u0648\u0627\u0644\u062d\u062f\u0648\u062f \u0627\u0644\u0642\u0628\u0644\u064a\u0629 \u0644\u062a\u0634\u062e\u064a\u0635 \u0627\u0644\u062a\u0639\u062b\u0631\u0627\u062a \u0648\u0628\u0646\u0627\u0621 \u062e\u0637\u0629 \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0645\u0628\u0643\u0631\u0629.",u.C)
B.a6G=s(["\u0648\u0636\u0639\u064a\u0629 \u0645\u0639\u0642\u062f\u0629 \u062c\u062f\u0627\u064b \u062a\u062a\u0637\u0644\u0628 \u0645\u0639\u0627\u0631\u0641 \u0644\u0645 \u064a\u062f\u0631\u0633\u0647\u0627 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0645\u0637\u0644\u0642\u0627\u064b.","\u062a\u0637\u0628\u064a\u0642 \u0645\u0628\u0627\u0634\u0631 \u0648\u062a\u0643\u0631\u0627\u0631\u064a \u0644\u0642\u0627\u0639\u062f\u0629 \u0631\u064a\u0627\u0636\u064a\u0629 \u062a\u0645 \u0634\u0631\u062d\u0647\u0627 \u0644\u0644\u062a\u0648.","\u0648\u0636\u0639\u064a\u0629 \u062a\u062d\u0645\u0644 \u0645\u0639\u0646\u0649 \u0648\u062a\u0636\u0639 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0623\u0645\u0627\u0645 \u0639\u0627\u0626\u0642 \u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a \u064a\u062a\u0637\u0644\u0628 \u0627\u0633\u062a\u062f\u0639\u0627\u0621 \u0648\u062a\u0648\u0644\u064a\u0641 \u0645\u0639\u0627\u0631\u0641\u0647 \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0644\u062a\u062c\u0627\u0648\u0632\u0647.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aoB=new A.c("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'\u062a\u064f\u0639\u0631\u0641 "\u0627\u0644\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0645\u0633\u0623\u0644\u0629" (Situation-probl\xe8me) \u0627\u0644\u062c\u064a\u062f\u0629 \u0641\u064a \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a \u0628\u0640:',B.a6G,2,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0648\u0636\u0639\u064a\u0629 \u062a\u062d\u0645\u0644 \u0645\u0639\u0646\u0649 \u0648\u062a\u0636\u0639 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0623\u0645\u0627\u0645 \u0639\u0627\u0626\u0642 \u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a \u064a\u062a\u0637\u0644\u0628 \u0627\u0633\u062a\u062f\u0639\u0627\u0621 \u0648\u062a\u0648\u0644\u064a\u0641 \u0645\u0639\u0627\u0631\u0641\u0647 \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0644\u062a\u062c\u0627\u0648\u0632\u0647.",u.C)
B.Sw=s(["\u0627\u0644\u062a\u062d\u0648\u064a\u0644 \u0627\u0644\u0645\u0628\u0627\u0634\u0631 \u0641\u064a \u062c\u062f\u0648\u0644 \u0627\u0644\u0645\u0633\u0627\u062d\u0627\u062a.","\u0645\u0642\u0627\u0631\u0646\u0629 \u0648\u0645\u0644\u0627 any \u0627\u0644\u0645\u0633\u0627\u062d\u0627\u062a \u0628\u0648\u0627\u0633\u0637\u0629 \u0648\u062d\u062f\u0627\u062a \u0627\u0639\u062a\u0628\u0627\u0637\u064a\u0629 \u0648\u062a\u0631\u0628\u064a\u0639\u0627\u062a (\u0627\u0644\u062a\u0628\u0644\u064a\u0637).","\u062d\u0633\u0627\u0628 \u062d\u062c\u0645 \u0627\u0644\u0645\u062c\u0633\u0645\u0627\u062a \u0627\u0644\u0642\u0627\u0626\u0645\u0629.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.arP=new A.c("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639","\u0641\u064a \u062f\u0631\u0633 \u0642\u064a\u0627\u0633 \u0627\u0644\u0645\u0633\u0627\u062d\u0627\u062a \u0644\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639\u060c \u0627\u0644\u0645\u0641\u0647\u0648\u0645 \u0627\u0644\u0630\u064a \u064a\u064f\u0628\u0646\u0649 \u0642\u0628\u0644 \u0627\u0644\u062a\u0642\u0646\u064a\u0629 \u0627\u0644\u0627\u0639\u062a\u064a\u0627\u062f\u064a\u0629 \u0644\u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u0627\u0644\u0642\u0627\u0646\u0648\u0646 ( S = L  times l ) \u0647\u0648:",B.Sw,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0645\u0642\u0627\u0631\u0646\u0629 \u0648\u0645\u0644\u0627 any \u0627\u0644\u0645\u0633\u0627\u062d\u0627\u062a \u0628\u0648\u0627\u0633\u0637\u0629 \u0648\u062d\u062f\u0627\u062a \u0627\u0639\u062a\u0628\u0627\u0637\u064a\u0629 \u0648\u062a\u0631\u0628\u064a\u0639\u0627\u062a (\u0627\u0644\u062a\u0628\u0644\u064a\u0637).",u.C)
B.a01=s(["\u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u0627\u0644\u062d\u0627\u0633\u0628\u0629 \u0627\u0644\u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a\u0629 \u062d\u0635\u0631\u0627\u064b.","\u0625\u062a\u0642\u0627\u0646 \u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u062a\u0641\u0643\u064a\u0643 \u0648\u062a\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u0639\u062f\u0627\u062f \u0648\u062a\u0648\u0638\u064a\u0641 \u062e\u0627\u0635\u064a\u0627\u062a \u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a (\u0627\u0644\u062a\u0648\u0632\u064a\u0639\u064a\u0629 \u0648\u0627\u0644\u062a\u0628\u0627\u062f\u0644\u064a\u0629).","\u0643\u062a\u0627\u0628\u0629 \u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a \u0639\u0645\u0648\u062f\u064a\u0627\u064b \u0639\u0644\u0649 \u062f\u0641\u062a\u0631 \u0627\u0644\u062a\u0633\u0648\u064a\u062f \u0641\u0642\u0637.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.ajx=new A.c("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639","\u0627\u0644\u062d\u0633\u0627\u0628 \u0627\u0644\u0633\u0631\u064a\u0639 (Calcul rapide) \u0643\u062c\u0632\u0621 \u0645\u0646 \u0627\u0644\u062d\u0633\u0627\u0628 \u0627\u0644\u0630\u0647\u0646\u064a \u064a\u0633\u062a\u0646\u062f \u0625\u0644\u0649:",B.a01,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0625\u062a\u0642\u0627\u0646 \u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u062a\u0641\u0643\u064a\u0643 \u0648\u062a\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u0639\u062f\u0627\u062f \u0648\u062a\u0648\u0638\u064a\u0641 \u062e\u0627\u0635\u064a\u0627\u062a \u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a (\u0627\u0644\u062a\u0648\u0632\u064a\u0639\u064a\u0629 \u0648\u0627\u0644\u062a\u0628\u0627\u062f\u0644\u064a\u0629).",u.C)
B.aas=s(["\u0646\u0634\u0627\u0637 \u0627\u0644\u0645\u062f\u0631\u0633 \u0648\u0645\u0627 \u0633\u064a\u0634\u0631\u062d\u0647 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u062d\u0635\u0629.",'\u0648\u0635\u0641 \u0623\u0641\u0639\u0627\u0644 \u063a\u064a\u0631 \u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u0645\u0644\u0627\u062d\u0638\u0629 \u0645\u062b\u0644 "\u0623\u0646 \u064a\u0641\u0647\u0645 \u0627\u0644\u062a\u0644\u0645\u064a\u0630".',"\u0633\u0644\u0648\u0643 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0627\u0644\u0642\u0627\u0628\u0644 \u0644\u0644\u0645\u0644\u0627\u062d\u0638\u0629 \u0648\u0627\u0644\u0642\u064a\u0627\u0633 \u0641\u064a \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u062a\u0639\u0644\u0645 (\u0623\u0646 \u064a\u0643\u0648\u0646 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0642\u0627\u062f\u0631\u0627\u064b \u0639\u0644\u0649...).","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.asb=new A.c("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639","\u0627\u0644\u0647\u062f\u0641 \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a \u0627\u0644\u0625\u062c\u0631\u0627\u0626\u064a \u0627\u0644\u0645\u0635\u0627\u063a \u0628\u0634\u0643\u0644 \u0635\u062d\u064a\u062d \u064a\u062c\u0628 \u0623\u0646 \u064a\u0631\u0643\u0632 \u0639\u0644\u0649:",B.aas,2,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0633\u0644\u0648\u0643 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0627\u0644\u0642\u0627\u0628\u0644 \u0644\u0644\u0645\u0644\u0627\u062d\u0638\u0629 \u0648\u0627\u0644\u0642\u064a\u0627\u0633 \u0641\u064a \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u062a\u0639\u0644\u0645 (\u0623\u0646 \u064a\u0643\u0648\u0646 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0642\u0627\u062f\u0631\u0627\u064b \u0639\u0644\u0649...).",u.C)
B.YB=s(["\u0627\u0644\u0634\u0631\u064a\u0637 \u0627\u0644\u0639\u062f\u062f\u064a \u0648\u0627\u0644\u062c\u062f\u0648\u0644 \u0648\u0627\u0644\u0645\u0643\u0639\u0628\u0627\u062a \u0648\u0627\u0644\u0635\u0641\u0627\u0626\u062d \u0648\u0627\u0644\u0642\u0637\u0639 \u0627\u0644\u0645\u0642\u0633\u0645\u0629 \u0625\u0644\u0649 \u0623\u0639\u0634\u0627\u0631 \u0648\u0623\u062c\u0632\u0627\u0621 \u0627\u0644\u0645\u0626\u0629.","\u0623\u0634\u0631\u0637\u0629 \u0627\u0644\u0641\u064a\u062f\u064a\u0648 \u0627\u0644\u0648\u062b\u0627\u0626\u0642\u064a\u0629 \u063a\u064a\u0631 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u064a\u0629.","\u0627\u0644\u0645\u0646\u0642\u0644\u0629 \u0648\u0627\u0644\u0645\u0632\u0648\u0627\u0629.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.asx=new A.c("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639","\u0627\u0644\u0648\u0633\u064a\u0644\u0629 \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a\u0629 \u0627\u0644\u0623\u0643\u062b\u0631 \u0645\u0644\u0627\u0621\u0645\u0629 \u0644\u0628\u0646\u0627\u0621 \u0645\u0641\u0647\u0648\u0645 \u0627\u0644\u0623\u0639\u062f\u0627\u062f \u0627\u0644\u0639\u0634\u0631\u064a\u0629 \u0641\u064a \u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0631\u0627\u0628\u0639\u0629 \u0647\u064a:",B.YB,0,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0634\u0631\u064a\u0637 \u0627\u0644\u0639\u062f\u062f\u064a \u0648\u0627\u0644\u062c\u062f\u0648\u0644 \u0648\u0627\u0644\u0645\u0643\u0639\u0628\u0627\u062a \u0648\u0627\u0644\u0635\u0641\u0627\u0626\u062d \u0648\u0627\u0644\u0642\u0637\u0639 \u0627\u0644\u0645\u0642\u0633\u0645\u0629 \u0625\u0644\u0649 \u0623\u0639\u0634\u0627\u0631 \u0648\u0623\u062c\u0632\u0627\u0621 \u0627\u0644\u0645\u0626\u0629.",u.C)
B.a15=s(["\u0642\u0648\u0627\u0639\u062f \u0627\u0644\u0645\u0626\u0629 \u0648\u0627\u0644\u0646\u0633\u0628\u0629 \u0627\u0644\u0645\u0626\u0648\u064a\u0629 \u0627\u0644\u0645\u0639\u0642\u062f\u0629 \u0623\u0648\u0644\u0627\u064b.","\u062c\u062f\u0627\u0648\u0644 \u0627\u0644\u062a\u0646\u0627\u0633\u0628\u060c \u0627\u0644\u0645\u062e\u0637\u0637\u0627\u062a \u0627\u0644\u062e\u0637\u064a\u0629\u060c \u0648\u0645\u0639\u0627\u0645\u0644 \u0627\u0644\u062a\u0646\u0627\u0633\u0628 \u0627\u0644\u0645\u0631\u0628\u0648\u0637 \u0628\u0627\u0644\u0639\u0644\u0627\u0642\u0627\u062a \u0627\u0644\u0639\u062f\u062f\u064a\u0629.","\u062d\u0633\u0627\u0628 \u0645\u0633\u0627\u062d\u0629 \u0627\u0644\u062f\u0627\u0626\u0631\u0629 \u0648\u062d\u062c\u0645 \u0627\u0644\u0643\u0631\u0629.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.ari=new A.c("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'\u0645\u0641\u0647\u0648\u0645 "\u0627\u0644\u062a\u0646\u0627\u0633\u0628\u064a\u0629" \u064a\u064f\u0628\u0646\u0649 \u0641\u064a \u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a\u0629 \u0639\u0628\u0631 \u0627\u0644\u0627\u0639\u062a\u0645\u0627\u062f \u0627\u0644\u0645\u0628\u0627\u0634\u0631 \u0639\u0644\u0649:',B.a15,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062c\u062f\u0627\u0648\u0644 \u0627\u0644\u062a\u0646\u0627\u0633\u0628\u060c \u0627\u0644\u0645\u062e\u0637\u0637\u0627\u062a \u0627\u0644\u062e\u0637\u064a\u0629\u060c \u0648\u0645\u0639\u0627\u0645\u0644 \u0627\u0644\u062a\u0646\u0627\u0633\u0628 \u0627\u0644\u0645\u0631\u0628\u0648\u0637 \u0628\u0627\u0644\u0639\u0644\u0627\u0642\u0627\u062a \u0627\u0644\u0639\u062f\u062f\u064a\u0629.",u.C)
B.a9I=s(["\u0627\u0644\u0627\u0633\u062a\u062f\u0644\u0627\u0644 \u0628\u0627\u0644\u062e\u0644\u0641 \u0627\u0644\u0635\u0648\u0631\u064a \u0627\u0644\u0645\u062a\u0642\u062f\u0645.","\u0627\u0644\u0627\u0633\u062a\u062f\u0644\u0627\u0644 \u0627\u0644\u0627\u0633\u062a\u0642\u0631\u0627\u0626\u064a (\u0627\u0644\u0627\u0646\u062a\u0642\u0627\u0644 \u0645\u0646 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u062e\u0627\u0635\u0629 \u0648\u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0627\u062a \u0627\u0644\u0645\u0627\u062f\u064a\u0629 \u0625\u0644\u0649 \u0627\u0644\u062a\u0639\u0645\u064a\u0645).","\u0627\u0644\u0628\u0631\u0647\u0627\u0646 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a\u064a \u0627\u0644\u0646\u0638\u0631\u064a \u0627\u0644\u0645\u062c\u0631\u062f.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.at1=new A.c("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639","\u0627\u0644\u0627\u0633\u062a\u062f\u0644\u0627\u0644 \u0627\u0644\u0631\u064a\u0627\u0636\u064a \u0627\u0644\u0645\u0639\u062a\u0645\u062f \u063a\u0627\u0644\u0628\u0627\u064b \u0641\u064a \u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a \u0644\u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u0641\u0627\u0647\u064a\u0645 \u0647\u0648:",B.a9I,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0627\u0633\u062a\u062f\u0644\u0627\u0644 \u0627\u0644\u0627\u0633\u062a\u0642\u0631\u0627\u0626\u064a (\u0627\u0644\u0627\u0646\u062a\u0642\u0627\u0644 \u0645\u0646 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u062e\u0627\u0635\u0629 \u0648\u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0627\u062a \u0627\u0644\u0645\u0627\u062f\u064a\u0629 \u0625\u0644\u0649 \u0627\u0644\u062a\u0639\u0645\u064a\u0645).",u.C)
B.a64=s(["\u064a\u062d\u062a\u0648\u064a \u0639\u0644\u0649 \u0625\u062c\u0627\u0628\u0629 \u0648\u0627\u062d\u062f\u0629 \u0648\u0645\u0633\u0627\u0631 \u062d\u062a\u0645\u064a \u0645\u062d\u062f\u062f \u0645\u0633\u0628\u0642\u0627\u064b.","\u064a\u062a\u064a\u062d \u0644\u0644\u0645\u062a\u0639\u0644\u0645 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0625\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0648\u0637\u0631\u0642 \u062d\u0644 \u0645\u062a\u0639\u062f\u062f\u0629 \u0648\u0645\u062a\u0646\u0648\u0639\u0629 \u0644\u0644\u0648\u0635\u0648\u0644 \u0644\u0644\u0646\u0647\u0627\u064a\u0629.","\u0644\u0627 \u064a\u062a\u0637\u0644\u0628 \u0623\u064a \u062a\u0641\u0643\u064a\u0631 \u0623\u0648 \u0623\u062f\u0627\u0629 \u0631\u064a\u0627\u0636\u064a\u0627\u062a\u064a\u0629.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.ail=new A.c("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639","\u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0645\u0641\u062a\u0648\u062d (Activit\xe9 ouverte) \u0641\u064a \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a \u0647\u0648 \u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0630\u064a:",B.a64,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u064a\u062a\u064a\u062d \u0644\u0644\u0645\u062a\u0639\u0644\u0645 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0625\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0648\u0637\u0631\u0642 \u062d\u0644 \u0645\u062a\u0639\u062f\u062f\u0629 \u0648\u0645\u062a\u0646\u0648\u0639\u0629 \u0644\u0644\u0648\u0635\u0648\u0644 \u0644\u0644\u0646\u0647\u0627\u064a\u0629.",u.C)
B.a7e=s(["\u062a\u0648\u0642\u064a\u0639 \u0627\u0644\u062a\u0632\u0627\u0645 \u0645\u0639 \u0648\u0644\u064a \u0627\u0644\u0623\u0645\u0631 \u0628\u0627\u0644\u0645\u062d\u0643\u0645\u0629.","\u062a\u062d\u062f\u064a\u062f \u0648\u062a\u0648\u0636\u064a\u062d \u0627\u0644\u0642\u0648\u0627\u0639\u062f \u0627\u0644\u0623\u062f\u0648\u0627\u0631 \u0648\u0627\u0644\u062a\u0639\u0644\u064a\u0645\u0627\u062a \u0648\u0627\u0644\u0645\u0647\u0627\u0645 \u0627\u0644\u0632\u0645\u0627\u0646\u064a\u0629 \u0648\u0627\u0644\u0645\u0643\u0627\u0646\u064a\u0629 \u0628\u064a\u0646 \u0627\u0644\u0645\u062f\u0631\u0633 \u0648\u0627\u0644\u0645\u062a\u0639\u0644\u0645.","\u0625\u062c\u0628\u0627\u0631 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0639\u0644\u0649 \u0643\u062a\u0627\u0628\u0629 \u0627\u0644\u0645\u0644\u062e\u0635 \u0628\u0635\u0631\u0627\u0645\u0629 \u062f\u0648\u0646 \u0645\u0646\u0627\u0642\u0634\u0629.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.ald=new A.c("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'\u0645\u0641\u0647\u0648\u0645 "\u0639\u0642\u062f \u0627\u0644\u062a\u0639\u0644\u0645" \u0623\u0648 "\u0627\u0644\u062a\u0639\u0627\u0642\u062f \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a" \u064a\u064f\u0641\u0639\u0644 \u0641\u064a \u0627\u0644\u0641\u0635\u0644 \u0645\u0646 \u062e\u0644\u0627\u0644:',B.a7e,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u062d\u062f\u064a\u062f \u0648\u062a\u0648\u0636\u064a\u062d \u0627\u0644\u0642\u0648\u0627\u0639\u062f \u0627\u0644\u0623\u062f\u0648\u0627\u0631 \u0648\u0627\u0644\u062a\u0639\u0644\u064a\u0645\u0627\u062a \u0648\u0627\u0644\u0645\u0647\u0627\u0645 \u0627\u0644\u0632\u0645\u0627\u0646\u064a\u0629 \u0648\u0627\u0644\u0645\u0643\u0627\u0646\u064a\u0629 \u0628\u064a\u0646 \u0627\u0644\u0645\u062f\u0631\u0633 \u0648\u0627\u0644\u0645\u062a\u0639\u0644\u0645.",u.C)
B.Uw=s(["\u0645\u0631\u062d\u0644\u0629 \u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u0641\u0647\u0648\u0645 \u0627\u0644\u0635\u0639\u0628\u0629 \u0641\u0642\u0637.","\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062d\u0633\u0627\u0628 \u0627\u0644\u0630\u0647\u0646\u064a \u0648\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0643\u0648\u064a\u0646\u064a \u0627\u0644\u0633\u0631\u064a\u0639 \u0644\u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0623\u062e\u0637\u0627\u0621 \u0627\u0644\u0634\u0627\u0626\u0639\u0629 \u0641\u0648\u0631\u064a\u0627\u064b.","\u062a\u0648\u062b\u064a\u0642 \u0627\u0644\u0645\u0644\u062e\u0635\u0627\u062a \u0627\u0644\u0646\u0647\u0627\u0626\u064a\u0629 \u0644\u062a\u0628\u0642\u0649 \u062f\u0627\u0626\u0645\u0627\u064b.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.amV=new A.c("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639","\u062a\u064f\u0639\u062a\u0628\u0631 \u0627\u0644\u0623\u0644\u0648\u0627\u062d (Ardoises) \u0623\u062f\u0627\u0629 \u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a\u0629 \u0631\u0626\u064a\u0633\u064a\u0629 \u062a\u0633\u062a\u0639\u0645\u0644 \u0628\u0643\u062b\u0631\u0629 \u0641\u064a:",B.Uw,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062d\u0633\u0627\u0628 \u0627\u0644\u0630\u0647\u0646\u064a \u0648\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0643\u0648\u064a\u0646\u064a \u0627\u0644\u0633\u0631\u064a\u0639 \u0644\u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0623\u062e\u0637\u0627\u0621 \u0627\u0644\u0634\u0627\u0626\u0639\u0629 \u0641\u0648\u0631\u064a\u0627\u064b.",u.C)
B.a4t=s(["\u0639\u0632\u0644 \u0627\u0644\u0645\u0639\u0627\u0631\u0641 \u0648\u0627\u0644\u0645\u0641\u0627\u0647\u064a\u0645 \u0648\u062c\u0639\u0644 \u0643\u0644 \u062f\u0631\u0633 \u0645\u0633\u062a\u0642\u0644 \u0628\u0630\u0627\u062a\u0647.","\u0631\u0628\u0637 \u0627\u0644\u0645\u0643\u062a\u0633\u0628\u0627\u062a \u0648\u062a\u062c\u0645\u064a\u0639 \u0627\u0644\u0639\u0644\u0627\u0642\u0627\u062a \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a\u064a\u0629 \u0627\u0644\u0645\u062e\u062a\u0644\u0641\u0629 \u0648\u062a\u0637\u0628\u064a\u0642\u0647\u0627 \u0641\u064a \u0648\u0636\u0639\u064a\u0627\u062a \u0634\u0627\u0645\u0644\u0629 \u0648\u0645\u0631\u0643\u0628\u0629.","\u0643\u062a\u0627\u0628\u0629 \u0627\u0644\u0641\u0631\u0648\u0636 \u0627\u0644\u0645\u0646\u0632\u0644\u064a\u0629 \u0648\u062a\u0635\u062d\u064a\u062d\u0647\u0627 \u0641\u0631\u062f\u064a\u0627\u064b.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aky=new A.c("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639","\u0623\u0633\u0628\u0648\u0639 \u0627\u0644\u062a\u0648\u0644\u064a\u0641 \u0641\u064a \u0645\u0627\u062f\u0629 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a \u064a\u0647\u062f\u0641 \u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a\u0627\u064b \u0625\u0644\u0649:",B.a4t,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0631\u0628\u0637 \u0627\u0644\u0645\u0643\u062a\u0633\u0628\u0627\u062a \u0648\u062a\u062c\u0645\u064a\u0639 \u0627\u0644\u0639\u0644\u0627\u0642\u0627\u062a \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a\u064a\u0629 \u0627\u0644\u0645\u062e\u062a\u0644\u0641\u0629 \u0648\u062a\u0637\u0628\u064a\u0642\u0647\u0627 \u0641\u064a \u0648\u0636\u0639\u064a\u0627\u062a \u0634\u0627\u0645\u0644\u0629 \u0648\u0645\u0631\u0643\u0628\u0629.",u.C)
B.a3D=s(["\u0645\u0624\u0634\u0631\u0627\u064b \u0633\u0644\u0628\u064a\u064b\u0627 \u064a\u0633\u062a\u0648\u062c\u0628 \u0645\u0639\u0627\u0642\u0628\u0629 \u0627\u0644\u062a\u0644\u0645\u064a\u0630.","\u0638\u0627\u0647\u0631\u0629 \u0637\u0628\u064a\u0639\u064a\u0629 \u0648\u0639\u0627\u0642\u0627\u064b \u0645\u0639\u0627\u0641\u064a\u0627\u064b \u064a\u0634\u0643\u0644 \u0646\u0642\u0637\u0629 \u0627\u0646\u0637\u0644\u0627\u0642 \u0644\u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0648\u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u062a\u0641\u0643\u064a\u0631.","\u062f\u0644\u064a\u0644\u0627\u064b \u0642\u0627\u0637\u0639\u0627\u064b \u0639\u0644\u0649 \u0639\u062f\u0645 \u0642\u062f\u0631\u0629 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0639\u0644\u0649 \u0627\u0644\u062a\u0639\u0644\u0645 \u0645\u0633\u062a\u0642\u0628\u0644\u0627\u064b.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.ain=new A.c("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'\u0627\u0644\u0645\u0628\u062f\u0623 \u0627\u0644\u0645\u0648\u062c\u0647 \u0644\u062a\u062f\u0631\u064a\u0633 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a \u0627\u0644\u0645\u0633\u0645\u0649 "\u0627\u0633\u062a\u062b\u0645\u0627\u0631 \u0627\u0644\u0623\u062e\u0637\u0627\u0621" \u064a\u0646\u0638\u0631 \u0625\u0644\u0649 \u0627\u0644\u062e\u0637\u0623 \u0628\u0643\u0648\u0646\u0647:',B.a3D,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0638\u0627\u0647\u0631\u0629 \u0637\u0628\u064a\u0639\u064a\u0629 \u0648\u0639\u0627\u0642\u0627\u064b \u0645\u0639\u0627\u0641\u064a\u0627\u064b \u064a\u0634\u0643\u0644 \u0646\u0642\u0637\u0629 \u0627\u0646\u0637\u0644\u0627\u0642 \u0644\u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0648\u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u062a\u0641\u0643\u064a\u0631.",u.C)
B.a4X=s(["\u0627\u0644\u0642\u0633\u0645\u0629 \u0642\u0628\u0644 \u0627\u0644\u062c\u0645\u0639 \u0648\u0627\u0644\u0637\u0631\u062d.","\u0627\u0644\u062c\u0645\u0639 \u0648\u0627\u0644\u0637\u0631\u062d \u0628\u0627\u0644\u062a\u0648\u0627\u0632\u064a\u060c \u062b\u0645 \u0627\u0644\u0636\u0631\u0628 \u0643\u0645\u0641\u0647\u0648\u0645 \u0644\u0644\u062c\u0645\u0639 \u0627\u0644\u0645\u062a\u0643\u0631\u0631\u060c \u0641\u0627\u0644\u0642\u0633\u0645\u0629 \u0643\u062a\u0648\u0632\u064a\u0639 \u0648\u062a\u0643\u0631\u0627\u0631 \u0644\u0644\u0637\u0631\u062d.","\u0627\u0644\u0636\u0631\u0628 \u0648\u0627\u0644\u0642\u0633\u0645\u0629 \u0642\u0628\u0644 \u0625\u062f\u0631\u0627\u0643 \u0645\u0641\u0647\u0648\u0645 \u0627\u0644\u0639\u062f\u062f.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.anv=new A.c("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639","\u0627\u0644\u062a\u062f\u0631\u062c \u0641\u064a \u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a \u0627\u0644\u0623\u0631\u0628\u0639 \u0639\u0644\u0649 \u0627\u0644\u0623\u0639\u062f\u0627\u062f \u0627\u0644\u0635\u062d\u064a\u062d\u0629 \u064a\u0642\u062a\u0636\u064a \u062a\u0642\u062f\u064a\u0645:",B.a4X,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u062c\u0645\u0639 \u0648\u0627\u0644\u0637\u0631\u062d \u0628\u0627\u0644\u062a\u0648\u0627\u0632\u064a\u060c \u062b\u0645 \u0627\u0644\u0636\u0631\u0628 \u0643\u0645\u0641\u0647\u0648\u0645 \u0644\u0644\u062c\u0645\u0639 \u0627\u0644\u0645\u062a\u0643\u0631\u0631\u060c \u0641\u0627\u0644\u0642\u0633\u0645\u0629 \u0643\u062a\u0648\u0632\u064a\u0639 \u0648\u062a\u0643\u0631\u0627\u0631 \u0644\u0644\u0637\u0631\u062d.",u.C)
B.a3x=s(["\u0627\u0633\u062a\u062e\u0631\u0627\u062c \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0648\u062d\u0633\u0627\u0628 \u0627\u0644\u0627\u0646\u062d\u0631\u0627\u0641 \u0627\u0644\u0645\u0639\u064a\u0627\u0631\u064a \u0648\u0627\u0644\u0625\u062d\u0635\u0627\u0621 \u0627\u0644\u0645\u062a\u0642\u062f\u0645.","\u0642\u0631\u0627\u0621\u0629 \u0648\u062a\u0623\u0648\u064a\u0644 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0648\u062a\u0646\u0638\u064a\u0645\u0647\u0627 \u0641\u064a \u062c\u062f\u0627\u0648\u0644 \u0648\u0645\u062e\u0637\u0637\u0627\u062a \u0628\u0627\u0644\u0623\u0639\u0645\u062f\u0629 \u0648\u0627\u0644\u0639\u0635\u064a.","\u0643\u062a\u0627\u0628\u0629 \u0628\u0631\u0645\u062c\u064a\u0627\u062a \u0625\u062d\u0635\u0627\u0626\u064a\u0629 \u0628\u0644\u063a\u0627\u062a \u0627\u0644\u0628\u0631\u0645\u062c\u0629.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aqr=new A.c("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'\u0641\u064a \u0643\u0641\u0627\u064a\u0629 "\u062a\u0646\u0638\u064a\u0645 \u0648\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a" \u0628\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0631\u0627\u0628\u0639\u0629\u060c \u064a\u064f\u0637\u0627\u0644\u0628 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0628\u0640:',B.a3x,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0642\u0631\u0627\u0621\u0629 \u0648\u062a\u0623\u0648\u064a\u0644 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0648\u062a\u0646\u0638\u064a\u0645\u0647\u0627 \u0641\u064a \u062c\u062f\u0627\u0648\u0644 \u0648\u0645\u062e\u0637\u0637\u0627\u062a \u0628\u0627\u0644\u0623\u0639\u0645\u062f\u0629 \u0648\u0627\u0644\u0639\u0635\u064a.",u.C)
B.Wc=s(["\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0641\u0639\u0644 ( Situation  d'action ).","\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629 ( Situation  de  validation ).","\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0645\u0623\u0633\u0633\u0629 ( Situation  d'institutionnalisation ).","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.anX=new A.c("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'26. \u0648\u0641\u0642 \u0646\u0638\u0631\u064a\u0629 \u0627\u0644\u0648\u0636\u0639\u064a\u0627\u062a \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a\u0629 \u0644\u0640 "\u063a\u064a \u0628\u0631\u0648\u0633\u0648"\u060c \u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u062a\u064a \u064a\u0648\u0627\u062c\u0647 \u0641\u064a\u0647\u0627 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0627\u0644\u0648\u0636\u0639\u064a\u0629 \u0628\u0645\u0641\u0631\u062f\u0647 \u0648\u064a\u0635\u0648\u063a \u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0636\u0645\u0646\u064a\u0629 \u0647\u064a:',B.Wc,0,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0641\u0639\u0644 ( Situation  d'action ).",u.C)
B.aax=s(["\u0635\u064a\u0627\u063a\u0629 \u0627\u0644\u062a\u0642\u0631\u064a\u0631 \u0627\u0644\u0625\u062f\u0627\u0631\u064a \u0627\u0644\u064a\u0648\u0645\u064a.","\u0627\u0644\u0634\u0631\u062d \u0648\u0627\u0644\u062a\u0639\u0628\u064a\u0631 \u0627\u0644\u0635\u0631\u064a\u062d \u0639\u0646 \u062e\u0637\u0629 \u0627\u0644\u062d\u0644 \u0627\u0644\u062a\u064a \u062a\u0648\u0635\u0644 \u0625\u0644\u064a\u0647\u0627 \u0644\u0632\u0645\u0644\u0627\u0626\u0647 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0631\u0645\u0648\u0632 \u0648\u0644\u063a\u0629 \u0631\u064a\u0627\u0636\u064a\u0627\u062a\u064a\u0629.","\u0627\u0644\u0627\u0633\u062a\u0645\u0627\u0639 \u0627\u0644\u0634\u0627\u0645\u0644 \u0644\u0634\u0631\u062d \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0648\u0645\u0633\u0637\u0631\u0629 \u0627\u0644\u062d\u0644 \u0639\u0644\u0649 \u0627\u0644\u0633\u0628\u0648\u0631\u0629.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.asC=new A.c("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'27. \u0645\u0631\u062d\u0644\u0629 "\u0627\u0644\u0635\u064a\u0627\u063a\u0629" ( Situation  de  formulation ) \u0641\u064a \u0646\u0638\u0631\u064a\u0629 \u0627\u0644\u0648\u0636\u0639\u064a\u0627\u062a \u062a\u062a\u0637\u0644\u0628 \u0645\u0646 \u0627\u0644\u0645\u062a\u0639\u0644\u0645:',B.aax,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0634\u0631\u062d \u0648\u0627\u0644\u062a\u0639\u0628\u064a\u0631 \u0627\u0644\u0635\u0631\u064a\u062d \u0639\u0646 \u062e\u0637\u0629 \u0627\u0644\u062d\u0644 \u0627\u0644\u062a\u064a \u062a\u0648\u0635\u0644 \u0625\u0644\u064a\u0647\u0627 \u0644\u0632\u0645\u0644\u0627\u0626\u0647 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0631\u0645\u0648\u0632 \u0648\u0644\u063a\u0629 \u0631\u064a\u0627\u0636\u064a\u0627\u062a\u064a\u0629.",u.C)
B.W3=s(["\u062d\u0641\u0638 \u0627\u0644\u062a\u0639\u0627\u0631\u064a\u0641 \u0627\u0644\u0631\u0633\u0645\u064a\u0629 \u0627\u0644\u0645\u0643\u062a\u0648\u0628\u0629 \u0641\u064a \u0627\u0644\u0643\u062a\u0627\u0628 \u0627\u0644\u0645\u062f\u0631\u0633.","\u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u0628\u0631\u0627\u0647\u064a\u0646 \u0648\u0627\u0644\u062d\u062c\u062c \u0627\u0644\u0645\u0646\u0637\u0642\u064a\u0629 \u0644\u0625\u062b\u0628\u0627\u062a \u0635\u062d\u0629 \u0646\u062a\u0627\u0626\u062c\u0647 \u0623\u0648 \u0625\u0642\u0646\u0627\u0639 \u0623\u0642\u0631\u0627\u0646\u0647 \u0628\u062c\u062f\u0648\u0649 \u0637\u0631\u064a\u0642\u062a\u0647.","\u0646\u0642\u0644 \u0627\u0644\u062d\u0644\u0648\u0644 \u0627\u0644\u0645\u0643\u062a\u0648\u0628\u0629 \u0645\u0646 \u062f\u0641\u062a\u0631 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0645\u0628\u0627\u0634\u0631\u0629.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.asg=new A.c("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'28. \u0641\u064a \u0648\u0636\u0639\u064a\u0629 "\u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629" ( Situation  de  validation )\u060c \u064a\u0643\u0648\u0646 \u0627\u0644\u062f\u0648\u0631 \u0627\u0644\u0623\u0633\u0627\u0633\u064a \u0644\u0644\u0645\u062a\u0639\u0644\u0645 \u0647\u0648:',B.W3,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u0628\u0631\u0627\u0647\u064a\u0646 \u0648\u0627\u0644\u062d\u062c\u062c \u0627\u0644\u0645\u0646\u0637\u0642\u064a\u0629 \u0644\u0625\u062b\u0628\u0627\u062a \u0635\u062d\u0629 \u0646\u062a\u0627\u0626\u062c\u0647 \u0623\u0648 \u0625\u0642\u0646\u0627\u0639 \u0623\u0642\u0631\u0627\u0646\u0647 \u0628\u062c\u062f\u0648\u0649 \u0637\u0631\u064a\u0642\u062a\u0647.",u.C)
B.aaQ=s(["\u062a\u0631\u0643 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u064a\u0642\u0631\u0631\u0648\u0646 \u0627\u0644\u062a\u0639\u0627\u0631\u064a\u0641 \u0627\u0644\u0631\u0633\u0645\u064a\u0629 \u062f\u0648\u0646 \u062a\u062f\u062e\u0644 \u0627\u0644\u0623\u0633\u062a\u0627\u0630.","\u062a\u062f\u062e\u0644 \u0627\u0644\u0645\u062f\u0631\u0633 \u0644\u0625\u0636\u0641\u0627\u0621 \u0627\u0644\u0635\u0628\u063a\u0629 \u0627\u0644\u0631\u0633\u0645\u064a\u0629 \u0648\u0627\u0644\u0645\u0648\u0636\u0648\u0639\u064a\u0629 \u0639\u0644\u0649 \u0627\u0644\u0645\u0641\u0647\u0648\u0645 \u0627\u0644\u062c\u062f\u064a\u062f \u0648\u0636\u0628\u0637 \u0627\u0644\u0645\u0635\u0637\u0644\u062d\u0627\u062a \u0648\u0627\u0644\u0631\u0645\u0648\u0632.","\u062a\u0648\u0632\u064a\u0639 \u0627\u0644\u0631\u0648\u0627\u0626\u0632 \u0648\u0627\u0644\u0623\u0644\u0648\u0627\u062d \u0644\u0625\u062c\u0631\u0627\u0621 \u0627\u0644\u062d\u0633\u0627\u0628 \u0627\u0644\u0630\u0647\u0646\u064a.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.apS=new A.c("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'29. \u0645\u0631\u062d\u0644\u0629 "\u0627\u0644\u0645\u0623\u0633\u0633\u0629" ( Situation  d\'institutionnalisation ) \u062a\u062a\u062c\u0644\u0649 \u0628\u0627\u0644\u0623\u0633\u0627\u0633 \u0641\u064a:',B.aaQ,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u062f\u062e\u0644 \u0627\u0644\u0645\u062f\u0631\u0633 \u0644\u0625\u0636\u0641\u0627\u0621 \u0627\u0644\u0635\u0628\u063a\u0629 \u0627\u0644\u0631\u0633\u0645\u064a\u0629 \u0648\u0627\u0644\u0645\u0648\u0636\u0648\u0639\u064a\u0629 \u0639\u0644\u0649 \u0627\u0644\u0645\u0641\u0647\u0648\u0645 \u0627\u0644\u062c\u062f\u064a\u062f \u0648\u0636\u0628\u0637 \u0627\u0644\u0645\u0635\u0637\u0644\u062d\u0627\u062a \u0648\u0627\u0644\u0631\u0645\u0648\u0632.",u.C)
B.WN=s(["\u062a\u0648\u0641\u064a\u0631 \u0628\u064a\u0626\u0629 \u062a\u0639\u0644\u064a\u0645\u064a\u0629 \u0647\u0627\u062f\u0626\u0629 \u0648\u0645\u062b\u0627\u0644\u064a\u0629 \u0644\u0644\u062a\u0644\u0627\u0645\u064a\u0630.","\u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0644\u0645\u0624\u0634\u0631\u0627\u062a \u0645\u0643\u0634\u0648\u0641\u0629 \u0623\u0648 \u0625\u0639\u0637\u0627\u0621 \u0627\u0644\u062c\u0648\u0627\u0628 \u0628\u0637\u0631\u064a\u0642\u0629 \u063a\u064a\u0631 \u0645\u0628\u0627\u0634\u0631\u0629 \u062a\u062d\u0631\u0645 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0645\u0646 \u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0639\u0627\u0626\u0642.","\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0623\u0644\u0639\u0627\u0628 \u0648\u0627\u0644\u0645\u0633\u0631\u062d \u0641\u064a \u0634\u0631\u062d \u062f\u0631\u0648\u0633 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.asA=new A.c("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'30. \u064a\u064f\u0642\u0635\u062f \u0628\u0645\u0641\u0647\u0648\u0645 "\u0623\u062b\u0631 \u0646\u0648\u0628\u064a\u0644" (Effet Topaze) \u0641\u064a \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643:',B.WN,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0644\u0645\u0624\u0634\u0631\u0627\u062a \u0645\u0643\u0634\u0648\u0641\u0629 \u0623\u0648 \u0625\u0639\u0637\u0627\u0621 \u0627\u0644\u062c\u0648\u0627\u0628 \u0628\u0637\u0631\u064a\u0642\u0629 \u063a\u064a\u0631 \u0645\u0628\u0627\u0634\u0631\u0629 \u062a\u062d\u0631\u0645 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0645\u0646 \u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0639\u0627\u0626\u0642.",u.C)
