B.anJ=new A.c("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'62. \u064a\u062a\u0643\u0648\u0646 "\u0645\u062c\u0644\u0633 \u0627\u0644\u062a\u062f\u0628\u064a\u0631" \u0628\u0627\u0644\u0645\u0624\u0633\u0633\u0629 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a\u0629 \u0628\u0631\u0626\u0627\u0633\u0629 \u0645\u062f\u064a\u0631 \u0627\u0644\u0645\u0624\u0633\u0633\u0629 \u0648\u0639\u0636\u0648\u064a\u0629 \u0645\u0645\u062b\u0644\u064a\u0646 \u0639\u0646:',B.aci,0,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0647\u064a\u0623\u0629 \u0627\u0644\u062a\u062f\u0631\u064a\u0633\u060c \u0627\u0644\u0623\u0637\u0631 \u0627\u0644\u0625\u062f\u0627\u0631\u064a\u0629\u060c \u0645\u0645\u062b\u0644 \u0627\u0644\u062c\u0645\u0627\u0639\u0629 \u0627\u0644\u062a\u0631\u0627\u0628\u064a\u0629\u060c \u0648\u0631\u0626\u064a\u0633 \u062c\u0645\u0639\u064a\u0629 \u0623\u0645\u0647\u0627\u062a \u0648\u0622\u0628\u0627\u0621 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630.",u.C)
B.a_x=s(["\u0623\u062b\u0646\u0627\u0621 \u0632\u0645\u0646 \u0648\u0645\u0643\u0627\u0646 \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0641\u0639\u0644\u064a\u0629 \u0644\u0644\u0648\u0638\u064a\u0641\u0629 \u0623\u0648 \u0641\u064a \u0627\u0644\u0645\u0633\u0627\u0631 \u0627\u0644\u0637\u0628\u064a\u0639\u064a \u0644\u0644\u0625\u064a\u0627\u0628 \u0648\u0627\u0644\u0630\u0647\u0627\u0628.","\u062e\u0644\u0627\u0644 \u0627\u0644\u0639\u0637\u0644 \u0627\u0644\u0635\u064a\u0641\u064a\u0629 \u0648\u0627\u0644\u0633\u0641\u0631 \u0627\u0644\u0634\u062e\u0635\u064a \u062e\u0627\u0631\u062c \u0627\u0644\u0645\u063a\u0631\u0628.","\u0623\u064a\u0627\u0645 \u0639\u0637\u0644 \u0627\u0644\u0623\u0639\u064a\u0627\u062f \u0627\u0644\u0648\u0637\u0646\u064a\u0629 \u0641\u064a \u0627\u0644\u0633\u0643\u0646 \u0627\u0644\u0634\u062e\u0635\u064a.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.akH=new A.c("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'63. "\u062d\u0648\u0627\u062f\u062b \u0627\u0644\u0634\u063a\u0644 \u0648\u0627\u0644\u062e\u062f\u0645\u0629" \u0627\u0644\u062a\u064a \u064a\u062a\u0639\u0631\u0636 \u0644\u0647\u0627 \u0627\u0644\u0645\u0648\u0638\u0641 \u0623\u0648 \u0627\u0644\u062a\u0644\u0645\u064a\u0630 \u062a\u062d\u062a \u0625\u0634\u0631\u0627\u0641 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u062a\u0646\u0638\u0645 \u0648\u062a\u063a\u0637\u064a\u0647\u0627 \u0627\u0644\u062f\u0648\u0644\u0629 \u0628\u0634\u0631\u0637 \u0623\u0646 \u062a\u0642\u0639:',B.a_x,0,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0623\u062b\u0646\u0627\u0621 \u0632\u0645\u0646 \u0648\u0645\u0643\u0627\u0646 \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0641\u0639\u0644\u064a\u0629 \u0644\u0644\u0648\u0638\u064a\u0641\u0629 \u0623\u0648 \u0641\u064a \u0627\u0644\u0645\u0633\u0627\u0631 \u0627\u0644\u0637\u0628\u064a\u0639\u064a \u0644\u0644\u0625\u064a\u0627\u0628 \u0648\u0627\u0644\u0630\u0647\u0627\u0628.",u.C)
