B.a8x=s(["\u0627\u0644\u0623\u0628\u062c\u062f\u064a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0641\u064a \u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u0633\u0644\u0627\u0643.","\u0627\u0644\u0623\u0628\u062c\u062f\u064a\u0629 \u0627\u0644\u0644\u0627\u062a\u064a\u0646\u064a\u0629 \u0627\u0644\u0645\u0639\u064a\u0627\u0631\u064a\u0629.","\u062d\u0631\u0641 \u062a\u064a\u0641\u064a\u0646\u0627\u063a \u0627\u0644\u0645\u0648\u062d\u062f \u0645\u0646 \u0637\u0631\u0641 \u0627\u0644\u0645\u0639\u0647\u062f \u0627\u0644\u0645\u0644\u0643\u064a \u0644\u0644\u062b\u0642\u0627\u0641\u0629 \u0627\u0644\u0623\u0645\u0627\u0632\u064a\u063a\u064a\u0629.","\u0627\u0644\u0643\u062a\u0627\u0628\u0629 \u0627\u0644\u0647\u064a\u0631\u0648\u063a\u0644\u064a\u0641\u064a\u0629 \u0627\u0644\u062a\u0627\u0631\u064a\u062e\u064a\u0629.","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.atg=new A.c("\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0623\u0645\u0627\u0632\u064a\u063a\u064a\u0629",null,"\u064a\u064f\u0639\u062a\u0645\u062f \u0641\u064a \u062a\u062f\u0631\u064a\u0633 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0623\u0645\u0627\u0632\u064a\u063a\u064a\u0629 \u0628\u0627\u0644\u0645\u062f\u0631\u0633\u0629 \u0627\u0644\u0645\u063a\u0631\u0628\u064a\u0629 \u0643\u062a\u0627\u0628\u0629\u064b \u0639\u0644\u0649:",B.a8x,2,"\u0627\u0639\u062a\u0645\u062f \u0627\u0644\u0645\u063a\u0631\u0628 \u062d\u0631\u0641 \u062a\u064a\u0641\u064a\u0646\u0627\u063a \u0627\u0644\u0630\u064a \u0648\u062d\u062f\u062a\u0647 IRCAM \u0628\u0648\u0635\u0641\u0647 \u0627\u0644\u062e\u0637 \u0627\u0644\u0631\u0633\u0645\u064a \u0644\u0643\u062a\u0627\u0628\u0629 \u0627\u0644\u0623\u0645\u0627\u0632\u064a\u063a\u064a\u0629 \u0648\u062a\u062f\u0631\u064a\u0633\u0647\u0627 \u0641\u064a \u0627\u0644\u0645\u062f\u0631\u0633\u0629.","\u0627\u0644\u0645\u0639\u0647\u062f \u0627\u0644\u0645\u0644\u0643\u064a \u0644\u0644\u062b\u0642\u0627\u0641\u0629 \u0627\u0644\u0623\u0645\u0627\u0632\u064a\u063a\u064a\u0629 (IRCAM)")
B.a5D=s(["\u0627\u0644\u0645\u0639\u0647\u062f \u0627\u0644\u0645\u0644\u0643\u064a \u0644\u0644\u062b\u0642\u0627\u0641\u0629 \u0627\u0644\u0623\u0645\u0627\u0632\u064a\u063a\u064a\u0629.",u.F,"\u0627\u0644\u0645\u0631\u0643\u0632 \u0627\u0644\u0648\u0637\u0646\u064a \u0644\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u0627\u0645\u062a\u062d\u0627\u0646\u0627\u062a.","\u0627\u0644\u0623\u0643\u0627\u062f\u064a\u0645\u064a\u0629 \u0627\u0644\u062c\u0647\u0648\u064a\u0629 \u0644\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u062a\u0643\u0648\u064a\u0646.","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.asf=new A.c("\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0623\u0645\u0627\u0632\u064a\u063a\u064a\u0629",null,"\u0627\u0644\u0645\u0624\u0633\u0633\u0629 \u0627\u0644\u0645\u0643\u0644\u0641\u0629 \u0628\u0627\u0644\u0645\u062d\u0627\u0641\u0638\u0629 \u0639\u0644\u0649 \u0627\u0644\u0644\u063a\u0629 \u0648\u0627\u0644\u062b\u0642\u0627\u0641\u0629 \u0627\u0644\u0623\u0645\u0627\u0632\u064a\u063a\u064a\u0629 \u0648\u062a\u0648\u062d\u064a\u062f \u0645\u0639\u0627\u064a\u064a\u0631 \u062a\u062f\u0631\u064a\u0633\u0647\u0627\u060c \u0648\u0627\u0644\u0645\u062d\u062f\u062b\u0629 \u0633\u0646\u0629 2001\u060c \u0647\u064a:",B.a5D,0,"\u0623\u064f\u062d\u062f\u062b \u0627\u0644\u0645\u0639\u0647\u062f \u0627\u0644\u0645\u0644\u0643\u064a \u0644\u0644\u062b\u0642\u0627\u0641\u0629 \u0627\u0644\u0623\u0645\u0627\u0632\u064a\u063a\u064a\u0629 (IRCAM) \u0633\u0646\u0629 2001 \u0644\u064a\u0642\u0648\u0645 \u0628\u062a\u0623\u0647\u064a\u0644 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0623\u0645\u0627\u0632\u064a\u063a\u064a\u0629 \u0648\u062a\u0648\u062d\u064a\u062f \u0643\u062a\u0627\u0628\u062a\u0647\u0627 \u0648\u0627\u0644\u0645\u0633\u0627\u0647\u0645\u0629 \u0641\u064a \u0627\u0644\u0628\u062d\u062b \u0627\u0644\u0645\u062a\u0639\u0644\u0642 \u0628\u0647\u0627 \u0648\u0628\u062a\u062f\u0631\u064a\u0633\u0647\u0627.","\u0627\u0644\u0645\u0639\u0647\u062f \u0627\u0644\u0645\u0644\u0643\u064a \u0644\u0644\u062b\u0642\u0627\u0641\u0629 \u0627\u0644\u0623\u0645\u0627\u0632\u064a\u063a\u064a\u0629 (IRCAM)")
B.VW=s(["26 \u062d\u0631\u0641\u0627.","29 \u062d\u0631\u0641\u0627.","33 \u062d\u0631\u0641\u0627.","38 \u062d\u0631\u0641\u0627.","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.ano=new A.c("\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0623\u0645\u0627\u0632\u064a\u063a\u064a\u0629",null,"\u064a\u062a\u0643\u0648\u0646 \u062d\u0631\u0641 \u062a\u064a\u0641\u064a\u0646\u0627\u063a \u0627\u0644\u0645\u0639\u062a\u0645\u062f \u0631\u0633\u0645\u064a\u0627 \u0641\u064a \u062a\u062f\u0631\u064a\u0633 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0623\u0645\u0627\u0632\u064a\u063a\u064a\u0629 \u0645\u0646 \u0639\u062f\u062f \u0645\u0646 \u0627\u0644\u062d\u0631\u0648\u0641 \u0642\u062f\u0631\u0647:",B.VW,2,"\u064a\u062a\u0643\u0648\u0646 \u062a\u064a\u0641\u064a\u0646\u0627\u063a-IRCAM \u0645\u0646 33 \u062d\u0631\u0641\u0627 \u0645\u0639\u062a\u0645\u062f\u0627 \u0641\u064a \u0627\u0644\u0643\u062a\u0627\u0628\u0629 \u0648\u0627\u0644\u062a\u062f\u0631\u064a\u0633\u060c \u0625\u0636\u0627\u0641\u0629 \u0625\u0644\u0649 \u0631\u0645\u0648\u0632 \u0644\u0636\u0628\u0637 \u0627\u0644\u0623\u0635\u0648\u0627\u062a.","\u0627\u0644\u0645\u0639\u0647\u062f \u0627\u0644\u0645\u0644\u0643\u064a \u0644\u0644\u062b\u0642\u0627\u0641\u0629 \u0627\u0644\u0623\u0645\u0627\u0632\u064a\u063a\u064a\u0629 (IRCAM)")
B.Ts=s(["\u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0627\u0644\u0646\u0638\u0631\u064a\u0629 \u0628\u0642\u0648\u0627\u0639\u062f \u0627\u0644\u0644\u063a\u0629.","\u0627\u0644\u0642\u062f\u0631\u0629 \u0639\u0644\u0649 \u062d\u0641\u0638 \u0627\u0644\u0646\u0635\u0648\u0635 \u0648\u0627\u0633\u062a\u0638\u0647\u0627\u0631\u0647\u0627.","\u0627\u0644\u062d\u0641\u0638 \u0627\u0644\u0622\u0644\u064a \u0644\u0644\u0645\u0639\u062c\u0645 \u062f\u0648\u0646 \u0627\u0633\u062a\u0639\u0645\u0627\u0644.","\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0643\u0641\u0627\u064a\u0629 \u0627\u0644\u062a\u0648\u0627\u0635\u0644\u064a\u0629 \u0644\u062f\u0649 \u0627\u0644\u0645\u062a\u0639\u0644\u0645.","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.anl=new A.c("\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0623\u0645\u0627\u0632\u064a\u063a\u064a\u0629",null,"\u062a\u0633\u062a\u0647\u062f\u0641 \u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0629 \u0627\u0644\u062a\u0648\u0627\u0635\u0644\u064a\u0629 \u0641\u064a \u062a\u062f\u0631\u064a\u0633 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0623\u0645\u0627\u0632\u064a\u063a\u064a\u0629 \u0628\u0627\u0644\u062f\u0631\u062c\u0629 \u0627\u0644\u0623\u0648\u0644\u0649:",B.Ts,3,"\u062a\u0631\u0643\u0632 \u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0629 \u0627\u0644\u062a\u0648\u0627\u0635\u0644\u064a\u0629 \u0639\u0644\u0649 \u062a\u0645\u0643\u064a\u0646 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0645\u0646 \u062a\u0648\u0638\u064a\u0641 \u0627\u0644\u0644\u063a\u0629 \u0641\u064a \u0645\u0648\u0627\u0642\u0641 \u062a\u0648\u0627\u0635\u0644\u064a\u0629 \u062f\u0627\u0644\u0629\u060c \u0641\u0627\u0644\u0644\u063a\u0629 \u0648\u0633\u064a\u0644\u0629 \u0644\u0644\u062a\u0648\u0627\u0635\u0644 \u0648\u0644\u064a\u0633\u062a \u0645\u062c\u0631\u062f \u0645\u0648\u0636\u0648\u0639\u0627 \u0644\u0644\u062d\u0641\u0638.",u.i)
B.Zl=s(["\u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0635\u0627\u0645\u062a\u0629\u060c \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u062c\u0647\u0631\u064a\u0629\u060c \u0627\u0644\u0625\u0645\u0644\u0627\u0621.","\u0627\u0644\u062a\u0647\u064a\u0626\u0629\u060c \u0627\u0644\u0641\u0647\u0645\u060c \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0641\u0642\u0637.","\u0642\u0628\u0644 \u0627\u0644\u0642\u0631\u0627\u0621\u0629\u060c \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0642\u0631\u0627\u0621\u0629\u060c \u0628\u0639\u062f \u0627\u0644\u0642\u0631\u0627\u0621\u0629.","\u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0629\u060c \u0627\u0644\u0627\u0633\u062a\u0638\u0647\u0627\u0631\u060c \u0627\u0644\u062a\u0637\u0628\u064a\u0642.","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.an0=new A.c("\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0623\u0645\u0627\u0632\u064a\u063a\u064a\u0629",null,"\u062a\u064f\u0646\u0638\u0645 \u0623\u0646\u0634\u0637\u0629 \u062f\u0631\u0633 \u0627\u0644\u0646\u0635 \u0641\u064a \u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0629 \u0627\u0644\u062d\u062f\u064a\u062b\u0629 \u0644\u062a\u062f\u0631\u064a\u0633 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0623\u0645\u0627\u0632\u064a\u063a\u064a\u0629 \u0648\u0641\u0642 \u0627\u0644\u0645\u0631\u0627\u062d\u0644 \u0627\u0644\u0622\u062a\u064a\u0629:",B.Zl,2,"\u064a\u0639\u062a\u0645\u062f \u062a\u062f\u0631\u064a\u0633 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0648\u0641\u0642 \u0627\u0644\u0646\u0645\u0648\u0630\u062c \u0627\u0644\u062d\u062f\u064a\u062b \u0645\u0631\u0627\u062d\u0644 \u062b\u0644\u0627\u062b \u0645\u062a\u062a\u0627\u0628\u0639\u0629: \u0645\u0627 \u0642\u0628\u0644 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0644\u062a\u0647\u064a\u0626\u0629 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0648\u0628\u0646\u0627\u0621 \u0627\u0644\u062a\u0648\u0642\u0639\u0627\u062a\u060c \u0648\u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0644\u0644\u0641\u0647\u0645 \u0648\u0627\u0644\u062a\u0634\u062e\u064a\u0635\u060c \u0648\u0645\u0627 \u0628\u0639\u062f \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0644\u062a\u062b\u0628\u064a\u062a \u0627\u0644\u0645\u0643\u062a\u0633\u0628\u0627\u062a \u0648\u062a\u0648\u0638\u064a\u0641\u0647\u0627.",u.i)
B.a6u=s(["\u062d\u0641\u0638 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0644\u0644\u0646\u0635\u0648\u0635 \u0627\u0644\u0623\u0645\u0627\u0632\u064a\u063a\u064a\u0629 \u063a\u064a\u0628\u0627.","\u062a\u0645\u0643\u064a\u0646 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0645\u0646 \u062a\u0648\u0638\u064a\u0641 \u0627\u0644\u0645\u0643\u062a\u0633\u0628\u0627\u062a \u0627\u0644\u0644\u063a\u0648\u064a\u0629 \u0641\u064a \u0648\u0636\u0639\u064a\u0627\u062a \u062f\u0627\u0644\u0629.","\u062a\u0642\u064a\u064a\u0645 \u062f\u0631\u062c\u0629 \u0627\u0644\u0627\u0633\u062a\u0638\u0647\u0627\u0631 \u0623\u0633\u0628\u0648\u0639\u064a\u0627.","\u062a\u0642\u0644\u064a\u0635 \u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u0634\u0641\u0648\u064a\u0629 \u062f\u0627\u062e\u0644 \u0627\u0644\u0642\u0633\u0645.","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.alb=new A.c("\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0623\u0645\u0627\u0632\u064a\u063a\u064a\u0629",null,"\u0645\u0627 \u0627\u0644\u063a\u0627\u064a\u0629 \u0627\u0644\u0645\u0631\u0643\u0632\u064a\u0629 \u0645\u0646 \u0627\u0639\u062a\u0645\u0627\u062f \u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0629 \u0628\u0627\u0644\u0643\u0641\u0627\u064a\u0627\u062a \u0641\u064a \u062a\u062f\u0631\u064a\u0633 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0623\u0645\u0627\u0632\u064a\u063a\u064a\u0629\u061f",B.a6u,1,"\u062a\u0642\u0648\u0645 \u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0629 \u0628\u0627\u0644\u0643\u0641\u0627\u064a\u0627\u062a \u0639\u0644\u0649 \u062a\u0639\u0628\u0626\u0629 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0644\u0645\u0643\u062a\u0633\u0628\u0627\u062a\u0647 (\u0645\u0639\u0631\u0641\u0629\u060c \u0645\u0647\u0627\u0631\u0627\u062a\u060c \u0645\u0648\u0627\u0642\u0641) \u062f\u0627\u062e\u0644 \u0648\u0636\u0639\u064a\u0627\u062a \u062f\u0627\u0644\u0629 \u0642\u0631\u064a\u0628\u0629 \u0645\u0646 \u0648\u0627\u0642\u0639\u0647\u060c \u0648\u0644\u064a\u0633 \u0639\u0644\u0649 \u0627\u0644\u062d\u0641\u0638 \u0648\u0627\u0644\u062a\u0631\u062f\u064a\u062f.",u.i)
B.W4=s(["\u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u0625\u0637\u0627\u0631 51.17 \u0627\u0644\u0645\u062a\u0639\u0644\u0642 \u0628\u0645\u0646\u0638\u0648\u0645\u0629 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u062a\u0643\u0648\u064a\u0646 \u0648\u0627\u0644\u0628\u062d\u062b \u0627\u0644\u0639\u0644\u0645\u064a.","\u0627\u0644\u0645\u064a\u062b\u0627\u0642 \u0627\u0644\u0648\u0637\u0646\u064a \u0644\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u062a\u0643\u0648\u064a\u0646 \u0644\u0633\u0646\u0629 1960.","\u0627\u0644\u0638\u0647\u064a\u0631 \u0627\u0644\u0634\u0631\u064a\u0641 \u0627\u0644\u0645\u0646\u0638\u0645 \u0644\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0623\u0635\u064a\u0644.","\u0627\u0644\u0645\u0631\u0633\u0648\u0645 \u0627\u0644\u0645\u062d\u062f\u062b \u0644\u0644\u0645\u062f\u0631\u0633\u0629 \u0627\u0644\u062c\u0645\u0627\u0639\u0627\u062a\u064a\u0629.","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aoQ=new A.c("\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0623\u0645\u0627\u0632\u064a\u063a\u064a\u0629",null,"\u062f\u0639\u0645 \u062a\u0639\u0632\u064a\u0632 \u062a\u062f\u0631\u064a\u0633 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0623\u0645\u0627\u0632\u064a\u063a\u064a\u0629 \u062f\u0627\u062e\u0644 \u0627\u0644\u0645\u0646\u0638\u0648\u0645\u0629 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0629 \u0627\u0644\u0645\u063a\u0631\u0628\u064a\u0629 \u0648\u0631\u062f\u062a \u0645\u0642\u062a\u0636\u064a\u0627\u062a\u0647 \u0636\u0645\u0646:",B.W4,0,"\u0623\u0643\u062f \u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u0625\u0637\u0627\u0631 51.17 (2019) \u0639\u0644\u0649 \u0627\u0644\u0627\u0646\u0641\u062a\u0627\u062d \u0639\u0644\u0649 \u0627\u0644\u0644\u063a\u0627\u062a \u0627\u0644\u0648\u0637\u0646\u064a\u0629 \u0628\u0645\u0627 \u0641\u064a\u0647\u0627 \u0627\u0644\u0623\u0645\u0627\u0632\u064a\u063a\u064a\u0629 \u0648\u062a\u062c\u0648\u064a\u062f \u062a\u0639\u0644\u064a\u0645\u0647\u0627\u060c \u0636\u0645\u0646 \u0645\u0628\u0627\u062f\u0626 \u0627\u0644\u0639\u062f\u0627\u0644\u0629 \u0648\u0627\u0644\u062c\u0648\u062f\u0629 \u0648\u0627\u0644\u0627\u0631\u062a\u0642\u0627\u0621 \u0627\u0644\u0645\u0646\u0634\u0648\u062f \u0628\u0627\u0644\u0645\u0646\u0638\u0648\u0645\u0629 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0629.","\u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u0625\u0637\u0627\u0631 51.17 \u0627\u0644\u0645\u062a\u0639\u0644\u0642 \u0628\u0645\u0646\u0638\u0648\u0645\u0629 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u062a\u0643\u0648\u064a\u0646 (2019)")
B.a2e=s(["\u0625\u0634\u063a\u0627\u0644 \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u062f\u0631\u0633.","\u062a\u0642\u064a\u064a\u0645 \u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0627\u0644\u0646\u0638\u0631\u064a\u0629 \u0628\u0642\u0648\u0627\u0639\u062f \u0627\u0644\u0644\u063a\u0629.","\u0627\u0644\u0627\u0633\u062a\u0639\u062f\u0627\u062f \u0644\u0644\u0625\u0645\u0644\u0627\u0621 \u0641\u0642\u0637.","\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0642\u062f\u0631\u0629 \u0639\u0644\u0649 \u0627\u0644\u062a\u0648\u0627\u0635\u0644 \u0627\u0644\u0634\u0641\u0647\u064a \u0641\u064a \u0645\u0648\u0627\u0642\u0641 \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u064a\u0648\u0645\u064a\u0629.","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aiw=new A.c("\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0623\u0645\u0627\u0632\u064a\u063a\u064a\u0629",null,"\u0645\u0627 \u0627\u0644\u063a\u0627\u064a\u0629 \u0645\u0646 \u062a\u062e\u0635\u064a\u0635 \u062d\u064a\u0632 \u0645\u0647\u0645 \u0644\u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u0634\u0641\u0648\u064a\u0629 \u0641\u064a \u062a\u062f\u0631\u064a\u0633 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0623\u0645\u0627\u0632\u064a\u063a\u064a\u0629 \u0628\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a \u0627\u0644\u0623\u0648\u0644\u0649 \u0645\u0646 \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a\u061f",B.a2e,3,"\u062a\u0639\u0637\u064a \u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0629 \u0627\u0644\u0623\u0641\u0642\u064a\u0629 \u0627\u0644\u062d\u062f\u064a\u062b\u0629 \u0627\u0644\u0623\u0648\u0644\u0648\u064a\u0629 \u0644\u0644\u0643\u0641\u0627\u064a\u0629 \u0627\u0644\u0634\u0641\u0647\u064a\u0629 \u0641\u064a \u0628\u062f\u0627\u064a\u0629 \u062a\u0639\u0644\u0645 \u0627\u0644\u0644\u063a\u0629\u060c \u0644\u0623\u0646 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u064a\u0643\u062a\u0633\u0628 \u0623\u0648\u0644\u0627 \u0627\u0644\u0642\u062f\u0631\u0629 \u0639\u0644\u0649 \u0627\u0644\u062a\u0648\u0627\u0635\u0644 \u0634\u0641\u0647\u064a\u0627 \u0642\u0628\u0644 \u0627\u0644\u0648\u0644\u0648\u062c \u0625\u0644\u0649 \u0627\u0644\u0645\u0643\u062a\u0648\u0628.",u.i)
