B.ak1=new A.c("\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645",null,"\u062a\u0634\u0643\u0644 \u0627\u0644\u062e\u0637\u0648\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u0641\u064a \u0645\u0633\u0627\u0631 \u0627\u0633\u062a\u062b\u0645\u0627\u0631 \u0627\u0644\u0623\u062e\u0637\u0627\u0621 \u0623\u0633\u0627\u0633\u0627 \u0644\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0645\u0631\u0643\u0632\u0629\u060c \u0648\u062a\u062a\u0645\u062b\u0644 \u0641\u064a:",B.a1e,2,"\u064a\u0628\u062f\u0623 \u0645\u0633\u0627\u0631 \u0627\u0633\u062a\u062b\u0645\u0627\u0631 \u0627\u0644\u0623\u062e\u0637\u0627\u0621 \u0628\u0627\u0644\u062d\u0635\u0631 \u0627\u0644\u0645\u0646\u0647\u062c\u064a \u0644\u0644\u0623\u062e\u0637\u0627\u0621\u060c \u062b\u0645 \u064a\u0623\u062a\u064a \u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u0623\u062e\u0637\u0627\u0621 (\u0645\u0635\u0627\u062f\u0631 \u0648\u0623\u0633\u0628\u0627\u0628 \u0648\u0623\u0646\u0648\u0627\u0639 \u0648\u0643\u064a\u0641\u064a\u0629 \u0627\u0644\u0639\u0644\u0627\u062c) \u0641\u0628\u0646\u0627\u0621 \u062e\u0637\u0629 \u0644\u0644\u062f\u0639\u0645.","\u062a\u0642\u064a\u064a\u0645 \u0634\u0627\u0645\u0644 \u0641\u064a \u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a (\u0641\u0635\u064a\u062d)")
