B.an3=new A.c("\u0627\u0644\u0646\u0645\u0648 \u0648\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0627\u0643\u062a\u0633\u0627\u0628 \u0627\u0644\u0641\u0647\u0645",null,"\u0644\u062a\u062f\u0631\u064a\u0633 \u0646\u0635 \u0634\u0639\u0631\u064a \u0639\u0644\u0649 \u0636\u0648\u0621 \u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0629 \u0627\u0644\u062c\u0634\u0637\u0627\u0644\u062a\u064a\u0629 \u064a\u0628\u062f\u0623 \u0627\u0644\u0645\u0639\u0644\u0645 \u0628\u0640:",B.a4a,1,"\u0627\u0644\u062c\u0634\u0637\u0627\u0644\u062a\u064a\u0629 \u062a\u0631\u0649 \u0623\u0646 \u0627\u0644\u062a\u0639\u0644\u0645 \u0625\u062f\u0631\u0627\u0643 \u0644\u0644\u0645\u0639\u0646\u0649 \u0645\u0646 \u0627\u0644\u0643\u0644 \u0625\u0644\u0649 \u0627\u0644\u062c\u0632\u0621: \u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0646\u0635 \u0643\u0627\u0645\u0644\u0627\u064b \u062b\u0645 \u0627\u0644\u0645\u0636\u0645\u0648\u0646 \u0627\u0644\u0639\u0627\u0645 \u062b\u0645 \u0627\u0644\u062a\u0641\u0635\u064a\u0644 \u0641\u064a \u0627\u0644\u0648\u062d\u062f\u0627\u062a \u0627\u0644\u0635\u063a\u0631\u0649.","\u0646\u0638\u0631\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645")
B.abG=s(["\u062f\u0627\u062e\u0644\u064a\u0629 \u062a\u0646\u0628\u062b\u0642 \u0645\u0646 \u0625\u062f\u0631\u0627\u0643 \u0628\u0646\u064a\u0629 \u0627\u0644\u0645\u0648\u0642\u0641","\u062e\u0627\u0631\u062c\u064a\u0629 \u062a\u0642\u0648\u0645 \u0639\u0644\u0649 \u0627\u0644\u0645\u062b\u064a\u0631 \u0648\u0627\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0629","\u0645\u0631\u062a\u0628\u0637\u0629 \u0628\u0627\u0644\u062a\u0639\u0632\u064a\u0632 \u0648\u0627\u0644\u0639\u0642\u0627\u0628","\u0645\u0627\u062f\u064a\u0629 \u0641\u064a \u0645\u0639\u0638\u0645\u0647\u0627","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aqc=new A.c("\u0627\u0644\u0646\u0645\u0648 \u0648\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0627\u0643\u062a\u0633\u0627\u0628 \u0627\u0644\u0641\u0647\u0645",null,"\u062a\u062e\u062a\u0644\u0641 \u0627\u0644\u062d\u0648\u0627\u0641\u0632 \u0639\u0646\u062f \u0627\u0644\u062c\u0634\u0637\u0627\u0644\u062a\u064a\u0629 \u0639\u0646 \u0627\u0644\u0633\u0644\u0648\u0643\u064a\u0629 \u0628\u0623\u0646\u0647\u0627:",B.abG,0,"\u0627\u0644\u062d\u0648\u0627\u0641\u0632 \u0641\u064a \u0627\u0644\u0645\u062f\u0631\u0633\u0629 \u0627\u0644\u062c\u0634\u0637\u0627\u0644\u062a\u064a\u0629 \u062f\u0627\u062e\u0644\u064a\u0629 (\u0625\u062f\u0631\u0627\u0643 \u0627\u0644\u0645\u0639\u0646\u0649 \u0648\u0627\u0644\u0627\u0633\u062a\u0628\u0635\u0627\u0631)\u060c \u0628\u064a\u0646\u0645\u0627 \u0627\u0644\u0633\u0644\u0648\u0643\u064a\u0629 \u062a\u0639\u062a\u0645\u062f \u062d\u0648\u0627\u0641\u0632 \u062e\u0627\u0631\u062c\u064a\u0629 (\u0645\u062b\u064a\u0631/\u062a\u0639\u0632\u064a\u0632/\u0639\u0642\u0627\u0628).","\u0646\u0638\u0631\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645")
B.T6=s(["\u0645\u0646 0 \u0625\u0644\u0649 \u0633\u0646\u062a\u064a\u0646","\u0645\u0646 \u0633\u0646\u062a\u064a\u0646 \u0625\u0644\u0649 7 \u0633\u0646\u0648\u0627\u062a","\u0645\u0646 7 \u0625\u0644\u0649 12 \u0633\u0646\u0629 \u062a\u0642\u0631\u064a\u0628\u0627\u064b","\u0645\u0646 12 \u0633\u0646\u0629 \u0641\u0645\u0627 \u0641\u0648\u0642","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.as7=new A.c("\u0627\u0644\u0646\u0645\u0648 \u0648\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0627\u0643\u062a\u0633\u0627\u0628 \u0627\u0644\u0641\u0647\u0645",null,"\u062a\u0642\u0639 \u0645\u0631\u062d\u0644\u0629 \xab\u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a \u0627\u0644\u0645\u0644\u0645\u0648\u0633\u0629\xbb \u0639\u0646\u062f \u0628\u064a\u0627\u062c\u064a\u0647 \u0641\u064a \u0641\u062a\u0631\u0629:",B.T6,2,"\u0645\u0631\u0627\u062d\u0644 \u0628\u064a\u0627\u062c\u064a\u0647: \u0627\u0644\u062d\u0633\u064a\u0629 \u0627\u0644\u062d\u0631\u0643\u064a\u0629 (0-2)\u060c \u0645\u0627 \u0642\u0628\u0644 \u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a (2-7)\u060c \u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a \u0627\u0644\u0645\u0644\u0645\u0648\u0633\u0629 (7-11/12)\u060c \u0648\u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a \u0627\u0644\u0645\u062c\u0631\u062f\u0629 (12+).","\u0646\u0638\u0631\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0627\u0644\u0645\u0633\u062a\u062c\u062f\u0627\u062a")
B.abg=s(["\u0639\u0645\u0644\u064a\u0629 \u0641\u0631\u062f\u064a\u0629 \u0642\u0627\u0626\u0645\u0629 \u0639\u0644\u0649 \u0627\u0644\u0646\u0636\u062c \u0627\u0644\u0628\u064a\u0648\u0644\u0648\u062c\u064a \u0648\u062d\u062f\u0647","\u0646\u062a\u064a\u062c\u0629 \u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629 \u0648\u0627\u0644\u062e\u0637\u0623 \u0648\u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0629","\u0645\u0633\u062a\u0642\u0644\u0629 \u0639\u0646 \u0627\u0644\u0648\u0633\u0637 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a \u0648\u0627\u0644\u062b\u0642\u0627\u0641\u064a","\u0639\u0645\u0644\u064a\u0629 \u0627\u062c\u062a\u0645\u0627\u0639\u064a\u0629 \u0641\u064a \u0627\u0644\u0645\u0642\u0627\u0645 \u0627\u0644\u0623\u0648\u0644 \u062a\u062a\u062d\u0642\u0642 \u0639\u0628\u0631 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0645\u0639 \u0627\u0644\u0623\u0643\u062b\u0631 \u062e\u0628\u0631\u0629","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aoI=new A.c("\u0627\u0644\u0646\u0645\u0648 \u0648\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0627\u0643\u062a\u0633\u0627\u0628 \u0627\u0644\u0641\u0647\u0645",null,"\u064a\u0631\u0649 \u0641\u064a\u063a\u0648\u062a\u0633\u0643\u064a \u0623\u0646 \u0627\u0644\u062a\u0639\u0644\u0645 \u0639\u0646\u062f \u0627\u0644\u0637\u0641\u0644:",B.abg,3,"\u0641\u064a\u063a\u0648\u062a\u0633\u0643\u064a (\u0627\u0644\u0633\u0648\u0633\u064a\u0648\u0628\u0646\u0627\u0626\u064a\u0629): \u0627\u0644\u062a\u0639\u0644\u0645 \u0639\u0645\u0644\u064a\u0629 \u0627\u062c\u062a\u0645\u0627\u0639\u064a\u0629 \u0623\u0648\u0644\u0627\u064b\u060c \u064a\u0628\u0646\u064a \u0627\u0644\u0637\u0641\u0644 \u0645\u0639\u0631\u0641\u062a\u0647 \u0639\u0628\u0631 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0645\u0639 \u0627\u0644\u0645\u062d\u064a\u0637 \u0648\u0627\u0644\u0623\u0634\u062e\u0627\u0635 \u0627\u0644\u0623\u0643\u062b\u0631 \u062e\u0628\u0631\u0629.","\u0646\u0638\u0631\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0645\u0646 \u0625\u0639\u062f\u0627\u062f \u062a\u0648\u0641\u064a\u0642 \u0644\u062e\u0635\u0627\u0635")
B.abv=s(["\u0627\u0644\u0648\u0633\u0627\u0626\u0644 \u0648\u0627\u0644\u0622\u0644\u0627\u062a \u0627\u0644\u0635\u0646\u0627\u0639\u064a\u0629 \u0641\u0642\u0637","\u0627\u0644\u0644\u063a\u0629 \u0648\u0627\u0644\u0631\u0645\u0648\u0632 \u0648\u0627\u0644\u0623\u0646\u0645\u0627\u0637 \u0627\u0644\u062b\u0642\u0627\u0641\u064a\u0629","\u0627\u0644\u0623\u0644\u0639\u0627\u0628 \u0648\u0627\u0644\u062a\u0631\u0641\u064a\u0647 \u0641\u064a \u0627\u0644\u0642\u0633\u0645","\u0627\u0644\u0643\u062a\u0628 \u0627\u0644\u0645\u062f\u0631\u0633\u064a\u0629 \u0648\u0627\u0644\u062f\u0641\u0627\u062a\u0631","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aqT=new A.c("\u0627\u0644\u0646\u0645\u0648 \u0648\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0627\u0643\u062a\u0633\u0627\u0628 \u0627\u0644\u0641\u0647\u0645",null,"\u064a\u0642\u0635\u062f \u0641\u064a\u063a\u0648\u062a\u0633\u0643\u064a \u0628\u0640\xab\u0627\u0644\u0623\u062f\u0648\u0627\u062a \u0627\u0644\u062b\u0642\u0627\u0641\u064a\u0629\xbb \u0627\u0644\u062a\u064a \u062a\u0633\u0627\u0639\u062f \u0639\u0644\u0649 \u062a\u0637\u0648\u0631 \u0627\u0644\u0641\u0631\u062f:",B.abv,1,"\u0627\u0644\u0623\u062f\u0648\u0627\u062a \u0627\u0644\u062b\u0642\u0627\u0641\u064a\u0629 \u0639\u0646\u062f \u0641\u064a\u063a\u0648\u062a\u0633\u0643\u064a \u0645\u062b\u0644 \u0627\u0644\u0644\u063a\u0629 \u0648\u0627\u0644\u0631\u0645\u0648\u0632 \u0647\u064a \u0648\u0633\u0627\u0626\u0637 \u062a\u0646\u0642\u0644 \u0628\u0647\u0627 \u0627\u0644\u0645\u0639\u0627\u0631\u0641 \u0648\u0627\u0644\u0645\u0647\u0627\u0631\u0627\u062a \u0639\u0628\u0631 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a.","\u0646\u0638\u0631\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0645\u0646 \u0625\u0639\u062f\u0627\u062f \u062a\u0648\u0641\u064a\u0642 \u0644\u062e\u0635\u0627\u0635")
B.a9h=s(["\u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a \u0645\u0639 \u0627\u0644\u0623\u0642\u0631\u0627\u0646 \u0623\u0648 \u0627\u0644\u0645\u0639\u0644\u0645\u064a\u0646","\u0627\u0644\u062f\u0631\u0627\u0633\u0629 \u0627\u0644\u0641\u0631\u062f\u064a\u0629 \u0627\u0644\u0635\u0627\u0645\u062a\u0629","\u0627\u0644\u062a\u0643\u0631\u0627\u0631 \u0627\u0644\u0645\u064a\u0643\u0627\u0646\u064a\u0643\u064a \u0644\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a","\u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0629 \u0627\u0644\u0633\u0644\u0628\u064a\u0629 \u0641\u0642\u0637","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.ate=new A.c("\u0627\u0644\u0646\u0645\u0648 \u0648\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0627\u0643\u062a\u0633\u0627\u0628 \u0627\u0644\u0641\u0647\u0645",null,"\u064a\u062a\u062d\u0642\u0642 \u0627\u0644\u062a\u0639\u0644\u0645 \u0628\u0634\u0643\u0644 \u0623\u0645\u062b\u0644 \u0641\u064a \u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u0646\u0645\u0648 \u0627\u0644\u0642\u0631\u064a\u0628 \u0639\u0628\u0631:",B.a9h,0,"\u0641\u064a\u063a\u0648\u062a\u0633\u0643\u064a \u064a\u0624\u0643\u062f \u0623\u0646 \u0627\u0644\u062a\u0639\u0644\u0645 \u064a\u062d\u062f\u062b \u0628\u0634\u0643\u0644 \u0623\u0645\u062b\u0644 \u062f\u0627\u062e\u0644 \u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u0646\u0645\u0648 \u0627\u0644\u0642\u0631\u064a\u0628 \u0645\u0646 \u062e\u0644\u0627\u0644 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a (\u0627\u0644\u0648\u0633\u0627\u0637\u0629 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a\u0629).","\u0646\u0638\u0631\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0645\u0646 \u0625\u0639\u062f\u0627\u062f \u062a\u0648\u0641\u064a\u0642 \u0644\u062e\u0635\u0627\u0635")
B.Z1=s(["\u0644\u0627\u0643\u062a\u0634\u0627\u0641 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0628\u0623\u0646\u0641\u0633\u0647\u0645 \u0645\u0646 \u062e\u0644\u0627\u0644 \u0627\u0644\u0627\u0633\u062a\u0642\u0635\u0627\u0621","\u0644\u062a\u0644\u0642\u064a \u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u062c\u0627\u0647\u0632\u0629 \u062f\u0648\u0646 \u0645\u0634\u0627\u0631\u0643\u0629","\u0644\u062d\u0641\u0638 \u0627\u0644\u0646\u0635\u0648\u0635 \u0648\u0627\u0644\u0645\u0635\u0637\u0644\u062d\u0627\u062a","\u0644\u0644\u062a\u0642\u064a\u064a\u062f \u0628\u0646\u0645\u0648\u0630\u062c \u0648\u0627\u062d\u062f \u0641\u064a \u0627\u0644\u062a\u0639\u0628\u064a\u0631","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aln=new A.c("\u0627\u0644\u0646\u0645\u0648 \u0648\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0627\u0643\u062a\u0633\u0627\u0628 \u0627\u0644\u0641\u0647\u0645",null,"\u064a\u062f\u0627\u0641\u0639 \u0628\u0631\u0648\u0646\u0631 \u0639\u0646 \u0641\u0643\u0631\u0629 \u0623\u0646 \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u064a\u062c\u0628 \u0623\u0646 \u062a\u064f\u0645\u0646\u062d \u0644\u0647\u0645 \u0627\u0644\u0641\u0631\u0635\u0629:",B.Z1,0,"\u0628\u0631\u0648\u0646\u0631 \u0645\u062f\u0627\u0641\u0639 \u0639\u0646 \u0627\u0644\u062a\u0639\u0644\u0645 \u0628\u0627\u0644\u0627\u0643\u062a\u0634\u0627\u0641: \u0625\u062a\u0627\u062d\u0629 \u0627\u0644\u0641\u0631\u0635\u0629 \u0644\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u0644\u0627\u0643\u062a\u0634\u0627\u0641 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0628\u0623\u0646\u0641\u0633\u0647\u0645 \u0639\u0628\u0631 \u0627\u0644\u0627\u0633\u062a\u0642\u0635\u0627\u0621 \u0648\u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0645\u0639 \u0627\u0644\u0628\u064a\u0626\u0629\u060c \u0628\u0645\u0627 \u064a\u062a\u0642\u0627\u0637\u0639 \u0645\u0639 \u0627\u0644\u0633\u0648\u0633\u064a\u0648\u0628\u0646\u0627\u0626\u064a\u0629.","\u0646\u0638\u0631\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0645\u0646 \u0625\u0639\u062f\u0627\u062f \u062a\u0648\u0641\u064a\u0642 \u0644\u062e\u0635\u0627\u0635")
B.a4J=s(["\u0645\u0646 \u0645\u062d\u062a\u0648\u0649 \u0627\u0644\u0645\u0627\u062f\u0629 \u0627\u0644\u0645\u0631\u0627\u062f \u062a\u062f\u0631\u064a\u0633\u0647\u0627","\u0645\u0646 \u0627\u0644\u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u0645\u0633\u0637\u0631\u0629 \u0641\u064a \u0627\u0644\u0645\u0642\u0631\u0631","\u0645\u0646 \u0648\u0627\u0642\u0639 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0644\u062a\u0645\u0643\u064a\u0646\u0647 \u0645\u0646 \u0627\u0644\u062a\u0643\u064a\u0641 \u0645\u0639\u0647 \u0648\u0641\u0647\u0645\u0647","\u0645\u0646 \u0627\u0644\u0627\u0645\u062a\u062d\u0627\u0646\u0627\u062a \u0648\u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631\u0627\u062a \u0627\u0644\u0648\u0637\u0646\u064a\u0629","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.asv=new A.c("\u0627\u0644\u0646\u0645\u0648 \u0648\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0627\u0643\u062a\u0633\u0627\u0628 \u0627\u0644\u0641\u0647\u0645",null,"\u062a\u062a\u0645\u064a\u0632 \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627\u062a \u0627\u0644\u0645\u062a\u0645\u062d\u0648\u0631\u0629 \u062d\u0648\u0644 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0628\u0623\u0646\u0647\u0627 \u062a\u0646\u0637\u0644\u0642:",B.a4J,2,"\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627\u062a \u0627\u0644\u0645\u062a\u0645\u062d\u0648\u0631\u0629 \u062d\u0648\u0644 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u062a\u0645\u0646\u062d \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a \u0645\u0639\u0646\u0649 \u0644\u0623\u0646\u0647\u0627 \u062a\u0646\u0637\u0644\u0642 \u0645\u0646 \u0627\u0644\u0648\u0627\u0642\u0639 \u0645\u0646 \u0623\u062c\u0644 \u0627\u0644\u062a\u0643\u064a\u0641 \u0645\u0639\u0647 \u0648\u0641\u0647\u0645\u0647\u060c \u0648\u062a\u0646\u0645\u064a \u0627\u0644\u0627\u0633\u062a\u0642\u0644\u0627\u0644\u064a\u0629.","\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627\u062a \u0627\u0644\u0648\u0638\u064a\u0641\u064a\u0629")
