B.aiL=new A.c("\u0635\u0639\u0648\u0628\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0639\u0648\u0627\u0626\u0642\u0647",null,"\u062a\u0639\u062a\u0645\u062f \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0627\u0644\u0641\u0627\u0631\u0642\u064a\u0629 \u0643\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u062a\u0639\u062b\u0631\u0627\u062a \u0639\u0644\u0649:",B.Uc,1,"\u0641\u064a\u0644\u064a\u0628 \u0645\u064a\u0631\u064a\u0648: \u0627\u0644\u0641\u0627\u0631\u0642\u064a\u0629 \u062a\u0639\u0646\u064a \u0625\u062f\u0631\u0627\u062c \u0645\u0633\u0627\u0631\u0627\u062a \u0645\u062a\u0643\u064a\u0641\u0629 \u0645\u0639 \u062d\u0627\u062c\u0627\u062a \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u0648\u0645\u0648\u0627\u0635\u0641\u0627\u062a\u0647\u0645\u060c \u0644\u062a\u0645\u0643\u064a\u0646\u0647\u0645 \u062c\u0645\u064a\u0639\u0627\u064b \u0645\u0646 \u0627\u0645\u062a\u0644\u0627\u0643 \u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0646\u0641\u0633\u0647\u0627 \u0639\u0628\u0631 \u0645\u0633\u0627\u0631\u0627\u062a \u0645\u062a\u0646\u0648\u0639\u0629.","\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0627\u0644\u0641\u0627\u0631\u0642\u064a\u0629 \u0648\u062a\u0637\u0628\u064a\u0642\u0627\u062a\u0647\u0627 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0629")
B.YO=s(["\u0627\u0644\u0623\u0634\u062e\u0627\u0635 \u0641\u064a \u0648\u0636\u0639\u064a\u0629 \u0625\u0639\u0627\u0642\u0629 \u0648\u0636\u0645\u0627\u0646 \u062d\u0642\u0647\u0645 \u0641\u064a \u0627\u0644\u062a\u0645\u062f\u0631\u0633","\u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0627\u0644\u0645\u062a\u0641\u0648\u0642\u064a\u0646 \u0641\u0642\u0637","\u0627\u0644\u062a\u0643\u0648\u064a\u0646 \u0627\u0644\u0645\u0633\u062a\u0645\u0631 \u0644\u0644\u0623\u0633\u0627\u062a\u0630\u0629","\u0627\u0644\u0628\u0646\u064a\u0629 \u0627\u0644\u062a\u062d\u062a\u064a\u0629 \u0644\u0644\u0645\u0624\u0633\u0633\u0627\u062a \u0641\u0642\u0637","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.ase=new A.c("\u0635\u0639\u0648\u0628\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0639\u0648\u0627\u0626\u0642\u0647",null,"\u062a\u062a\u0639\u0644\u0642 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0627\u0644\u062f\u0627\u0645\u062c\u0629 \u0628\u0635\u0641\u0629 \u062e\u0627\u0635\u0629 \u0628\u0640:",B.YO,0,"\u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0627\u0644\u062f\u0627\u0645\u062c\u0629 \u062a\u0639\u0646\u064a \u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0623\u0634\u062e\u0627\u0635 \u0641\u064a \u0648\u0636\u0639\u064a\u0629 \u0625\u0639\u0627\u0642\u0629 \u0641\u064a \u0625\u0637\u0627\u0631 \u062a\u0631\u0628\u064a\u0629 \u062f\u0627\u0645\u062c\u0629 \u0645\u0646\u0635\u0641\u0629 \u0648\u0646\u0627\u062c\u0639\u0629\u060c \u0643\u0645\u0627 \u0641\u064a \u0631\u0623\u064a \u0627\u0644\u0645\u062c\u0644\u0633 \u0627\u0644\u0623\u0639\u0644\u0649 \u0631\u0642\u0645 4/2019.","\u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0627\u0644\u062f\u0627\u0645\u062c\u0629AR")
B.a_E=s(["\u0625\u0644\u063a\u0627\u0621 \u0645\u0624\u0633\u0633\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0645\u062f\u0631\u0633\u064a \u0627\u0644\u0639\u0645\u0648\u0645\u064a","\u062d\u0635\u0631 \u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0623\u0634\u062e\u0627\u0635 \u0641\u064a \u0648\u0636\u0639\u064a\u0629 \u0625\u0639\u0627\u0642\u0629 \u0641\u064a \u0645\u0624\u0633\u0633\u0627\u062a \u062e\u0627\u0635\u0629","\u0636\u0645\u0627\u0646 \u062d\u0642 \u0627\u0644\u0648\u0644\u0648\u062c \u0625\u0644\u0649 \u0627\u0644\u062a\u0645\u062f\u0631\u0633 \u0628\u0645\u0648\u0627\u0635\u0641\u0627\u062a \u0627\u0644\u062c\u0648\u062f\u0629 \u0644\u0644\u062c\u0645\u064a\u0639","\u062a\u062e\u0635\u064a\u0635 \u0645\u062f\u0627\u0631\u0633 \u0645\u0646\u0641\u0635\u0644\u0629 \u0644\u0643\u0644 \u0625\u0639\u0627\u0642\u0629","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aj3=new A.c("\u0635\u0639\u0648\u0628\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0639\u0648\u0627\u0626\u0642\u0647",null,"\u0645\u0646 \u062a\u0648\u0635\u064a\u0627\u062a \u0631\u0623\u064a \u0627\u0644\u0645\u062c\u0644\u0633 \u0627\u0644\u0623\u0639\u0644\u0649 \u0644\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u062a\u0643\u0648\u064a\u0646 4/2019 \u0628\u0634\u0623\u0646 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0627\u0644\u062f\u0627\u0645\u062c\u0629:",B.a_E,2,"\u0645\u0646 \u062a\u0648\u0635\u064a\u0627\u062a \u0627\u0644\u0631\u0623\u064a: \u062a\u0639\u0644\u064a\u0645 \u062f\u0627\u0645\u062c \u0648\u0645\u0646\u0635\u0641 \u064a\u0636\u0645\u0646 \u062d\u0642 \u0627\u0644\u0648\u0644\u0648\u062c \u0625\u0644\u0649 \u0627\u0644\u062a\u0645\u062f\u0631\u0633 \u0628\u0645\u0648\u0627\u0635\u0641\u0627\u062a \u0627\u0644\u062c\u0648\u062f\u0629 \u0644\u0644\u062c\u0645\u064a\u0639\u060c \u0648\u0648\u0644\u0648\u062c\u0627\u064b \u0625\u0644\u0649 \u0627\u0644\u062a\u0643\u0646\u0648\u0644\u0648\u062c\u064a\u0627\u062a \u0627\u0644\u0631\u0642\u0645\u064a\u0629\u060c \u0648\u062a\u0646\u0645\u064a\u0629 \u0642\u062f\u0631\u0627\u062a \u0627\u0644\u0641\u0627\u0639\u0644\u064a\u0646.","\u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0627\u0644\u062f\u0627\u0645\u062c\u0629AR")
