B.aoa=new A.c("\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0627\u0646",null,"\u064a\u0642\u0648\u0645 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0634\u062e\u064a\u0635\u064a \u0639\u0644\u0649:",B.a04,3,"\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0634\u062e\u064a\u0635\u064a \u064a\u062d\u062f\u062f \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u0642\u0628\u0644 \u0627\u0644\u0634\u0631\u0648\u0639 \u0641\u064a \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a (\u0628\u062f\u0627\u064a\u0629 \u0627\u0644\u0645\u0648\u0633\u0645/\u0627\u0644\u0623\u0633\u062f\u0633/\u0627\u0644\u0648\u062d\u062f\u0629) \u0648\u064a\u0639\u0642\u0628\u0647 \u062f\u0627\u0626\u0645\u0627\u064b \u062f\u0639\u0645 \u0639\u0644\u0627\u062c\u064a \u0639\u0627\u0645 \u0623\u0648 \u062e\u0627\u0635.","\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645 \u0647\u0634\u0627\u0645 \u0642\u0637\u0628\u0627\u0646")
B.a4G=s(["\u062a\u0635\u062d\u064a\u062d \u0645\u0633\u0627\u0631 \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0623\u062e\u0637\u0627\u0621 \u0623\u062b\u0646\u0627\u0621 \u062d\u062f\u0648\u062b\u0647\u0627","\u0625\u0635\u062f\u0627\u0631 \u0642\u0631\u0627\u0631 \u0627\u0644\u0627\u0646\u062a\u0642\u0627\u0644 \u0625\u0644\u0649 \u0633\u0644\u0643 \u0623\u0639\u0644\u0649","\u0645\u0646\u062d \u0627\u0644\u0639\u0644\u0627\u0645\u0627\u062a \u0627\u0644\u0646\u0647\u0627\u0626\u064a\u0629 \u0644\u0644\u0634\u0647\u0627\u062f\u0629","\u0627\u062e\u062a\u064a\u0627\u0631 \u0627\u0644\u0645\u062a\u0641\u0648\u0642\u064a\u0646 \u0644\u0644\u062c\u0648\u0627\u0626\u0632","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aj8=new A.c("\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0627\u0646",null,"\u064a\u062a\u062e\u0644\u0644 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0643\u0648\u064a\u0646\u064a \u0639\u0645\u0644\u064a\u0629 \u0627\u0644\u062a\u062f\u0631\u064a\u0633 \u0628\u0647\u062f\u0641:",B.a4G,0,"\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0643\u0648\u064a\u0646\u064a (\u0627\u0644\u062c\u0632\u0626\u064a/\u0627\u0644\u0645\u0631\u062d\u0644\u064a) \u064a\u062a\u062e\u0644\u0644 \u0627\u0644\u062f\u0631\u0633 \u0623\u0648 \u0627\u0644\u062d\u0635\u0629 \u0644\u062a\u0635\u062d\u064a\u062d \u0645\u0633\u0627\u0631 \u0627\u0644\u062a\u0639\u0644\u0645\u060c \u0648\u0627\u0633\u062a\u062b\u0645\u0627\u0631 \u0627\u0644\u0623\u062e\u0637\u0627\u0621 \u0636\u0631\u0648\u0631\u064a \u0644\u0625\u0646\u062c\u0627\u062d\u0647.","\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645 \u0647\u0634\u0627\u0645 \u0642\u0637\u0628\u0627\u0646")
B.a3A=s(["\u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629 - \u0627\u0644\u0631\u0635\u062f - \u0627\u0644\u0645\u0635\u062f\u0631","\u0627\u0644\u0645\u0635\u062f\u0631 - \u0627\u0644\u0631\u0635\u062f - \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629","\u0627\u0644\u0631\u0635\u062f - \u0627\u0644\u0645\u0635\u062f\u0631 - \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629","\u0627\u0644\u0631\u0635\u062f - \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629 - \u0627\u0644\u0645\u0635\u062f\u0631","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.ar8=new A.c("\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0627\u0646",null,"\u062a\u0645\u0631 \u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u062e\u0637\u0623 \u0641\u064a \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0643\u0648\u064a\u0646\u064a \u0628\u0645\u0631\u0627\u062d\u0644 \u0647\u064a \u0639\u0644\u0649 \u0627\u0644\u062a\u0648\u0627\u0644\u064a:",B.a3A,2,"\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u062e\u0637\u0623 \u062a\u0645\u0631 \u0639\u0628\u0631 \u062b\u0644\u0627\u062b \u0645\u0631\u0627\u062d\u0644: \u0631\u0635\u062f \u0627\u0644\u062e\u0637\u0623\u060c \u062b\u0645 \u062a\u062d\u062f\u064a\u062f \u0645\u0635\u062f\u0631\u0647\u060c \u062b\u0645 \u0645\u0639\u0627\u0644\u062c\u062a\u0647.","\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645 \u0647\u0634\u0627\u0645 \u0642\u0637\u0628\u0627\u0646")
B.a__=s(["\u0627\u0644\u062a\u0634\u062e\u064a\u0635\u064a \u0623\u0648 \u0627\u0644\u0642\u0628\u0644\u064a","\u0627\u0644\u062e\u062a\u0627\u0645\u064a \u0623\u0648 \u0627\u0644\u0646\u0647\u0627\u0626\u064a \u0623\u0648 \u0627\u0644\u062c\u0632\u0627\u0626\u064a","\u0627\u0644\u062a\u0643\u0648\u064a\u0646\u064a \u0623\u0648 \u0627\u0644\u0645\u0631\u062d\u0644\u064a","\u0627\u0644\u0628\u062f\u064a\u0644 \u0623\u0648 \u0627\u0644\u0645\u0633\u062a\u0645\u0631","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.arS=new A.c("\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0627\u0646",null,"\u064a\u064f\u0637\u0644\u0642 \u0639\u0644\u0649 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u0625\u062c\u0645\u0627\u0644\u064a \u0623\u064a\u0636\u0627\u064b \u0627\u0644\u062a\u0642\u0648\u064a\u0645:",B.a__,1,"\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u0625\u062c\u0645\u0627\u0644\u064a (\u0627\u0644\u062e\u062a\u0627\u0645\u064a/\u0627\u0644\u0646\u0647\u0627\u0626\u064a/\u0627\u0644\u062c\u0632\u0627\u0626\u064a) \u064a\u0643\u0648\u0646 \u0641\u064a \u0646\u0647\u0627\u064a\u0629 \u0633\u0644\u0643 \u0623\u0648 \u0633\u0646\u0629 \u062f\u0631\u0627\u0633\u064a\u0629\u060c \u0648\u0645\u0646 \u062a\u062c\u0644\u064a\u0627\u062a\u0647 \u0627\u0644\u0645\u0631\u0627\u0642\u0628\u0629 \u0627\u0644\u0645\u0633\u062a\u0645\u0631\u0629 \u0648\u0627\u0644\u0627\u0645\u062a\u062d\u0627\u0646\u0627\u062a \u0627\u0644\u0625\u0634\u0647\u0627\u062f\u064a\u0629.","\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645 \u0647\u0634\u0627\u0645 \u0642\u0637\u0628\u0627\u0646")
B.aaM=s(["\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u0625\u062f\u0645\u0627\u062c \u0627\u0644\u0643\u0644\u064a \u0641\u0642\u0637","\u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u0645\u0648\u0627\u0632\u064a\u0629","\u0627\u0644\u0627\u0645\u062a\u062d\u0627\u0646\u0627\u062a \u0627\u0644\u0625\u0634\u0647\u0627\u062f\u064a\u0629","\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0639\u062b\u0631\u0627\u062a \u0648\u062f\u0639\u0645\u0647\u0627 \u0648\u062a\u0648\u0644\u064a\u0641\u0647\u0627","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.alW=new A.c("\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0627\u0646",null,"\u064a\u064f\u0639\u062f \u0627\u0644\u0623\u0633\u0628\u0648\u0639 \u0627\u0644\u062e\u0627\u0645\u0633 \u0645\u0646 \u0627\u0644\u0648\u062d\u062f\u0629 \u0627\u0644\u062f\u0631\u0627\u0633\u064a\u0629 \u0632\u0645\u0646\u0627\u064b \u0637\u0628\u064a\u0639\u064a\u0627\u064b \u0644\u062a\u0646\u0641\u064a\u0630:",B.aaM,3,"\u0627\u0644\u0623\u0633\u0628\u0648\u0639 \u0627\u0644\u062e\u0627\u0645\u0633 \u0645\u0646 \u0627\u0644\u0648\u062d\u062f\u0629 \u0647\u0648 \u0623\u0633\u0628\u0648\u0639 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645 \u0648\u0627\u0644\u062a\u0648\u0644\u064a\u0641\u060c \u0627\u0644\u0632\u0645\u0646 \u0627\u0644\u0637\u0628\u064a\u0639\u064a \u0644\u062a\u0646\u0641\u064a\u0630 \u0627\u0644\u062a\u0642\u0648\u064a\u0645\u0627\u062a \u0648\u062f\u0639\u0645 \u0627\u0644\u062a\u0639\u062b\u0631\u0627\u062a.","\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0627\u0644\u0641\u0627\u0631\u0642\u064a\u0629 \u0648\u062a\u0637\u0628\u064a\u0642\u0627\u062a\u0647\u0627 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0629")
