B.anP=new A.c("\u0627\u0644\u0625\u0635\u0644\u0627\u062d \u0627\u0644\u062a\u0631\u0628\u0648\u064a \u0648\u0627\u0644\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629",null,"\u064a\u0633\u062a\u0646\u062f \u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u0625\u0637\u0627\u0631 51.17 \u0641\u064a \u0645\u0631\u062c\u0639\u064a\u062a\u0647 \u0627\u0644\u062f\u0633\u062a\u0648\u0631\u064a\u0629 \u0625\u0644\u0649:",B.aa9,2,"\u0645\u0646 \u0645\u0631\u062c\u0639\u064a\u0627\u062a \u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u0625\u0637\u0627\u0631 (\u0627\u0644\u0641\u0635\u0644\u0627\u0646 31 \u064871): \u0627\u0644\u062a\u0648\u062c\u064a\u0647\u0627\u062a \u0627\u0644\u0645\u0644\u0643\u064a\u0629\u060c \u0627\u0644\u0645\u064a\u062b\u0627\u0642 \u0627\u0644\u0648\u0637\u0646\u064a\u060c \u0627\u0644\u0631\u0624\u064a\u0629 \u0627\u0644\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 2015-2030\u060c \u0648\u0627\u0644\u0645\u0648\u0627\u062b\u064a\u0642 \u0627\u0644\u062f\u0648\u0644\u064a\u0629.","\u0642\u0631\u0627\u0621\u0629 \u0641\u064a \u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u0625\u0637\u0627\u0631 51.17")
B.YA=s(["\u0648\u0632\u0627\u0631\u0629 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0627\u0644\u0648\u0637\u0646\u064a\u0629 \u0648\u062d\u062f\u0647\u0627","\u0627\u0644\u0644\u062c\u0646\u0629 \u0627\u0644\u0645\u0644\u0643\u064a\u0629 \u0627\u0644\u062e\u0627\u0635\u0629 \u0628\u0627\u0644\u062a\u0639\u0644\u064a\u0645","\u0647\u064a\u0626\u0629 \u0627\u0644\u0625\u0646\u0635\u0627\u0641 \u0648\u0627\u0644\u0645\u0635\u0627\u0644\u062d\u0629",u.k,"\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.arq=new A.c("\u0627\u0644\u0625\u0635\u0644\u0627\u062d \u0627\u0644\u062a\u0631\u0628\u0648\u064a \u0648\u0627\u0644\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629",null,"\u0628\u0644\u0648\u0631 \u0627\u0644\u0631\u0624\u064a\u0629 \u0627\u0644\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 2015-2030:",B.YA,3,"\u0627\u0644\u0631\u0624\u064a\u0629 \u0627\u0644\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0644\u0644\u0625\u0635\u0644\u0627\u062d \u0628\u0644\u0648\u0631\u0647\u0627 \u0627\u0644\u0645\u062c\u0644\u0633 \u0627\u0644\u0623\u0639\u0644\u0649 \u0644\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u062a\u0643\u0648\u064a\u0646 \u0648\u0627\u0644\u0628\u062d\u062b \u0627\u0644\u0639\u0644\u0645\u064a \u0633\u0646\u0629 2014\u060c \u0646\u062a\u064a\u062c\u0629 \u0644\u0644\u062a\u0642\u0631\u064a\u0631 \u0627\u0644\u062a\u062d\u0644\u064a\u0644\u064a \u0648\u0627\u0644\u062f\u0639\u0648\u0629 \u0627\u0644\u0645\u0644\u0643\u064a\u0629 \u0644\u0648\u0636\u0639 \u062e\u0627\u0631\u0637\u0629 \u0637\u0631\u064a\u0642 \u0644\u0644\u0625\u0635\u0644\u0627\u062d.","\u0627\u0644\u0631\u0624\u064a\u0629 \u0627\u0644\u0627\u0633\u062a\u0631\u0627\u062a\u062c\u064a\u0629 2030 - 2015")
