B.at0=new A.c("\u0627\u0644\u0625\u0635\u0644\u0627\u062d \u0627\u0644\u062a\u0631\u0628\u0648\u064a \u0648\u0627\u0644\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629",null,"\u0645\u0646 \u0645\u0631\u062c\u0639\u064a\u0627\u062a \xab\u0627\u0644\u0639\u0645\u0644\xbb \u0627\u0644\u062a\u064a \u062a\u0623\u0633\u0633\u062a \u0639\u0644\u064a\u0647\u0627 \u0627\u0644\u0631\u0624\u064a\u0629 \u0627\u0644\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 2015-2030:",B.WO,1,"\u0627\u0644\u0631\u0624\u064a\u0629 \u062a\u062a\u0623\u0633\u0633 \u0639\u0644\u0649 \u0645\u0631\u062c\u0639\u064a\u0627\u062a \u0645\u0648\u062c\u0647\u0629 (\u0627\u0644\u062f\u0633\u062a\u0648\u0631\u060c \u0627\u0644\u062e\u0637\u0628 \u0627\u0644\u0645\u0644\u0643\u064a\u0629\u060c \u0627\u0644\u0645\u064a\u062b\u0627\u0642 \u0627\u0644\u0648\u0637\u0646\u064a) \u0648\u0645\u0631\u062c\u0639\u064a\u0627\u062a \u0639\u0645\u0644 (\u062a\u0642\u0627\u0631\u064a\u0631 \u0648\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u0644\u062c\u0627\u0646 \u0627\u0644\u062f\u0627\u0626\u0645\u0629).","\u0627\u0644\u0631\u0624\u064a\u0629 \u0627\u0644\u0627\u0633\u062a\u0631\u0627\u062a\u062c\u064a\u0629 2030 - 2015")
B.Ui=s(["\u0627\u062b\u0646\u064a \u0639\u0634\u0631 \u0627\u0644\u062a\u0632\u0627\u0645\u0627\u064b \u0645\u0646 \u0623\u062c\u0644 \u0645\u062f\u0631\u0633\u0629 \u0639\u0645\u0648\u0645\u064a\u0629 \u0630\u0627\u062a \u062c\u0648\u062f\u0629","\u0639\u0634\u0631 \u0627\u0644\u062a\u0632\u0627\u0645\u0627\u062a \u0645\u0646 \u0623\u062c\u0644 \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u062e\u0635\u0648\u0635\u064a","\u062e\u0645\u0633\u0629 \u0645\u0634\u0627\u0631\u064a\u0639 \u0644\u0644\u062a\u0643\u0648\u064a\u0646 \u0627\u0644\u0645\u0647\u0646\u064a","\u062b\u0644\u0627\u062b\u064a\u0646 \u062a\u0648\u0635\u064a\u0629 \u0644\u0644\u0645\u062c\u0644\u0633 \u0627\u0644\u0623\u0639\u0644\u0649","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aig=new A.c("\u0627\u0644\u0625\u0635\u0644\u0627\u062d \u0627\u0644\u062a\u0631\u0628\u0648\u064a \u0648\u0627\u0644\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629",null,"\u062e\u0627\u0631\u0637\u0629 \u0627\u0644\u0637\u0631\u064a\u0642 2022-2026 \u0647\u064a \u0648\u062b\u064a\u0642\u0629 \u0625\u0635\u0644\u0627\u062d\u064a\u0629 \u062a\u0642\u0648\u0645 \u0639\u0644\u0649:",B.Ui,0,"\u062e\u0627\u0631\u0637\u0629 \u0627\u0644\u0637\u0631\u064a\u0642 2022-2026 \xab\u0627\u062b\u0646\u0627 \u0639\u0634\u0631 \u0627\u0644\u062a\u0632\u0627\u0645\u0627\u064b \u0645\u0646 \u0623\u062c\u0644 \u0645\u062f\u0631\u0633\u0629 \u0639\u0645\u0648\u0645\u064a\u0629 \u0630\u0627\u062a \u062c\u0648\u062f\u0629\xbb\u060c \u062a\u0631\u062a\u0643\u0632 \u0639\u0644\u0649 \u0627\u0644\u0623\u062b\u0631 \u0648\u062a\u062d\u062f\u062f \u062b\u0644\u0627\u062b\u0629 \u0634\u0631\u0648\u0637 \u0644\u0644\u0646\u062c\u0627\u062d.","\u062e\u0627\u0631\u0637\u0629 \u0627\u0644\u0637\u0631\u064a\u0642 12 \u0625\u0644\u062a\u0632\u0627\u0645")
