B.akr=new A.c("\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643 \u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0639\u0644\u0645\u064a",null,"\u0623\u064a \u062a\u0631\u062a\u064a\u0628 \u0645\u0646 \u0627\u0644\u062a\u0631\u062a\u064a\u0628\u0627\u062a \u0627\u0644\u0622\u062a\u064a\u0629 \u064a\u0639\u0643\u0633 \u0627\u0644\u0645\u0631\u0627\u062d\u0644 \u0627\u0644\u0635\u062d\u064a\u062d\u0629 \u0644\u0646\u0647\u062c \u0627\u0644\u062a\u0642\u0635\u064a \u0641\u064a \u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0639\u0644\u0645\u064a\u061f",B.a3b,0,"\u0645\u0631\u0627\u062d\u0644 \u0646\u0647\u062c \u0627\u0644\u062a\u0642\u0635\u064a \u062a\u0628\u062f\u0623 \u0628\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u0637\u0644\u0627\u0642 \u062b\u0645 \u0635\u064a\u0627\u063a\u0629 \u0627\u0644\u0641\u0631\u0636\u064a\u0627\u062a \u062b\u0645 \u0627\u0644\u062a\u0642\u0635\u064a \u0644\u0627\u062e\u062a\u0628\u0627\u0631\u0647\u0627 \u0628\u0627\u0644\u062a\u062c\u0631\u064a\u0628 \u0623\u0648 \u0627\u0644\u0645\u0646\u0627\u0648\u0644\u0629 \u0623\u0648 \u0627\u0644\u0646\u0645\u0630\u062c\u0629\u060c \u062b\u0645 \u062a\u0642\u062f\u064a\u0645 \u0648\u062a\u0642\u0627\u0633\u0645 \u0627\u0644\u0625\u0646\u062a\u0627\u062c\u0627\u062a \u0641\u0628\u0646\u064a\u0646\u0629 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a (\u0627\u0644\u062a\u0639\u0645\u064a\u0645).",u.j)
B.a_6=s(["\u062a\u0642\u064a\u064a\u0645 \u0645\u0643\u062a\u0633\u0628\u0627\u062a \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u0627\u0644\u0642\u0628\u0644\u064a\u0629 \u0628\u0635\u0641\u0629 \u0646\u0647\u0627\u0626\u064a\u0629","\u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0628\u0645\u0634\u0643\u0644 \u064a\u062b\u064a\u0631 \u0627\u0647\u062a\u0645\u0627\u0645\u0647 \u0648\u0641\u0636\u0648\u0644\u0647 \u0648\u064a\u0648\u0644\u062f \u0644\u062f\u064a\u0647 \u0627\u0644\u062a\u0633\u0627\u0624\u0644\u0627\u062a \u0648\u0627\u0644\u062d\u0627\u062c\u0629 \u0625\u0644\u0649 \u0627\u0644\u0628\u062d\u062b","\u0641\u0631\u0636 \u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0639\u0644\u0645\u064a\u0629 \u0627\u0644\u062c\u0627\u0647\u0632\u0629 \u0639\u0644\u0649 \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u0645\u0646 \u0628\u062f\u0627\u064a\u0629 \u0627\u0644\u062d\u0635\u0629","\u0639\u0631\u0636 \u0627\u0644\u0646\u062a\u0627\u0626\u062c \u0627\u0644\u0646\u0647\u0627\u0626\u064a\u0629 \u0644\u0644\u062a\u062c\u0627\u0631\u0628 \u0639\u0644\u0649 \u0627\u0644\u0633\u0628\u0648\u0631\u0629","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.alE=new A.c("\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643 \u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0639\u0644\u0645\u064a",null,"\u0645\u0627 \u0627\u0644\u0647\u062f\u0641 \u0627\u0644\u0623\u0633\u0627\u0633 \u0627\u0644\u0630\u064a \u062a\u0642\u0648\u0645 \u0639\u0644\u064a\u0647 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u0637\u0644\u0627\u0642 \u0641\u064a \u0646\u0647\u062c \u0627\u0644\u062a\u0642\u0635\u064a\u061f",B.a_6,1,"\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u0637\u0644\u0627\u0642 \u062a\u0642\u062a\u0636\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0644\u0645\u0634\u0643\u0644 \u064a\u062f\u0641\u0639\u0647 \u0625\u0644\u0649 \u0627\u0644\u0625\u062d\u0633\u0627\u0633 \u0628\u0627\u0644\u062d\u0627\u062c\u0629 \u0625\u0644\u0649 \u0627\u0644\u0628\u062d\u062b \u0639\u0646 \u062d\u0644\u0648\u0644\u060c \u0648\u062a\u062e\u0644\u0642 \u0648\u0636\u0639\u064a\u0629 \u0645\u062d\u0641\u0632\u0629 \u062a\u062b\u064a\u0631 \u0641\u0636\u0648\u0644\u0647 \u0648\u062a\u062f\u0641\u0639\u0647 \u0625\u0644\u0649 \u0637\u0631\u062d \u0627\u0644\u062a\u0633\u0627\u0624\u0644\u0627\u062a.",u.j)
B.a63=s(["\u0627\u0644\u0646\u062a\u064a\u062c\u0629 \u0627\u0644\u0646\u0647\u0627\u0626\u064a\u0629 \u0627\u0644\u0645\u0624\u0643\u062f\u0629 \u0639\u0644\u0645\u064a\u0627 \u0627\u0644\u062a\u064a \u0644\u0627 \u062a\u0642\u0628\u0644 \u0627\u0644\u0646\u0642\u0627\u0634","\u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0629 \u0627\u0644\u062d\u0633\u064a\u0629 \u0627\u0644\u0645\u0628\u0627\u0634\u0631\u0629 \u0644\u0644\u0638\u0627\u0647\u0631\u0629 \u0627\u0644\u0645\u062f\u0631\u0648\u0633\u0629","\u062c\u0648\u0627\u0628 \u0623\u0648 \u062a\u0641\u0633\u064a\u0631 \u0623\u0648\u0644\u064a \u0645\u0624\u0642\u062a \u064a\u0642\u062a\u0631\u062d\u0647 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0644\u0638\u0627\u0647\u0631\u0629 \u0623\u0648 \u0645\u0634\u0643\u0644\u0629 \u0648\u064a\u062a\u0645 \u0627\u062e\u062a\u0628\u0627\u0631\u0647 \u0628\u0627\u0644\u062a\u062c\u0631\u064a\u0628","\u0627\u0644\u062e\u0644\u0627\u0635\u0629 \u0627\u0644\u062a\u064a \u064a\u0633\u062a\u062e\u0644\u0635\u0647\u0627 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0648\u062d\u062f\u0647 \u0641\u064a \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u062d\u0635\u0629","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.al1=new A.c("\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643 \u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0639\u0644\u0645\u064a",null,"\u0627\u0644\u0645\u0642\u0635\u0648\u062f \u0628\u0627\u0644\u0641\u0631\u0636\u064a\u0629 \u0641\u064a \u0646\u0647\u062c \u0627\u0644\u062a\u0642\u0635\u064a \u0647\u0648:",B.a63,2,"\u0627\u0644\u0641\u0631\u0636\u064a\u0629 \u062a\u0641\u0633\u064a\u0631 \u0623\u0648\u0644\u064a \u0645\u0624\u0642\u062a \u064a\u0642\u062f\u0645\u0647 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0627\u0646\u0637\u0644\u0627\u0642\u0627 \u0645\u0646 \u062a\u0645\u062b\u0644\u0627\u062a\u0647 \u0648\u0645\u0639\u0627\u0631\u0641\u0647 \u0627\u0644\u0633\u0627\u0628\u0642\u0629 (\u0641\u064a \u0631\u0623\u064a\u064a\u060c \u0623\u0639\u062a\u0642\u062f \u0623\u0646...) \u062b\u0645 \u064a\u062a\u0645 \u0627\u062e\u062a\u0628\u0627\u0631\u0647\u0627 \u062e\u0644\u0627\u0644 \u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u062a\u0642\u0635\u064a \u0644\u0625\u062b\u0628\u0627\u062a\u0647\u0627 \u0623\u0648 \u0646\u0641\u064a\u0647\u0627.",u.j)
B.W1=s(["\u0627\u0644\u0628\u062d\u062b \u0627\u0644\u062a\u0648\u062b\u064a\u0642\u064a \u0641\u064a \u0627\u0644\u0645\u0648\u0633\u0648\u0639\u0627\u062a \u0648\u0627\u0644\u0623\u0646\u062a\u0631\u0646\u064a\u062a","\u0627\u0644\u062a\u062c\u0631\u064a\u0628 \u0627\u0644\u0645\u0628\u0627\u0634\u0631 \u062f\u0627\u062e\u0644 \u0627\u0644\u0645\u062e\u062a\u0628\u0631","\u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0629 \u0627\u0644\u0645\u064a\u062f\u0627\u0646\u064a\u0629 \u062e\u0627\u0631\u062c \u0627\u0644\u0642\u0633\u0645","\u0627\u0644\u0646\u0645\u0630\u062c\u0629 \u0639\u0628\u0631 \u0646\u0645\u0648\u0630\u062c \u064a\u0645\u062b\u0644 \u0627\u0644\u0648\u0636\u0639\u064a\u0629 \u0628\u0637\u0631\u064a\u0642\u0629 \u0645\u0628\u0633\u0637\u0629","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aqq=new A.c("\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643 \u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0639\u0644\u0645\u064a",null,"\u0645\u0627 \u0648\u0633\u064a\u0644\u0629 \u0627\u0644\u062a\u0642\u0635\u064a \u0627\u0644\u0623\u0646\u0633\u0628 \u0644\u062f\u0631\u0627\u0633\u0629 \u0638\u0627\u0647\u0631\u0629 \u064a\u0635\u0639\u0628 \u0645\u0644\u0627\u062d\u0638\u062a\u0647\u0627 \u0645\u0628\u0627\u0634\u0631\u0629\u060c \u0643\u062a\u0641\u0633\u064a\u0631 \u0643\u064a\u0641\u064a\u0629 \u062d\u062c\u0628 \u0627\u0644\u0642\u0645\u0631 \u0644\u0644\u0634\u0645\u0633\u061f",B.W1,3,"\u0627\u0644\u0646\u0645\u0630\u062c\u0629 \u0647\u064a \u0627\u0644\u062a\u0641\u0643\u064a\u0631 \u0641\u064a \u0646\u0645\u0648\u0630\u062c \u0644\u062a\u0645\u062b\u064a\u0644 \u0645\u0628\u0633\u0637 \u0644\u0638\u0648\u0627\u0647\u0631 \u0643\u0628\u0631\u0649 \u064a\u0635\u0639\u0628 \u0645\u0644\u0627\u062d\u0638\u062a\u0647\u0627 \u0645\u0628\u0627\u0634\u0631\u0629 \u0623\u0648 \u0639\u0645\u0644\u064a\u0627\u062a \u062f\u0642\u064a\u0642\u0629 \u063a\u064a\u0631 \u0645\u0631\u0626\u064a\u0629 \u0628\u0627\u0644\u0639\u064a\u0646 \u0627\u0644\u0645\u062c\u0631\u062f\u0629\u060c \u0643\u062a\u0641\u0633\u064a\u0631 \u0643\u064a\u0641\u064a\u0629 \u062d\u062c\u0628 \u0627\u0644\u0642\u0645\u0631 \u0644\u0644\u0634\u0645\u0633.",u.j)
B.Z2=s(["\u0639\u0646\u062f\u0645\u0627 \u064a\u062a\u0639\u0630\u0631 \u0625\u0646\u062c\u0627\u0632 \u0627\u0644\u062a\u062c\u0631\u0628\u0629 \u0627\u0644\u062d\u0642\u064a\u0642\u064a\u0629 \u062f\u0627\u062e\u0644 \u0627\u0644\u0642\u0633\u0645\u060c \u0627\u0639\u062a\u0645\u0627\u062f\u0627 \u0639\u0644\u0649 \u0627\u0644\u0645\u0648\u0627\u0631\u062f \u0627\u0644\u0631\u0642\u0645\u064a\u0629 \u0627\u0644\u0645\u062a\u0627\u062d\u0629","\u0641\u064a \u0643\u0644 \u062d\u0635\u0629 \u062f\u0648\u0646 \u0627\u0633\u062a\u062b\u0646\u0627\u0621 \u0645\u0647\u0645\u0627 \u0623\u0645\u0643\u0646 \u0625\u0646\u062c\u0627\u0632 \u0627\u0644\u062a\u062c\u0631\u0628\u0629 \u0627\u0644\u0641\u0639\u0644\u064a\u0629","\u0639\u0646\u062f\u0645\u0627 \u064a\u0631\u063a\u0628 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0641\u064a \u0627\u0644\u062a\u062e\u0644\u064a \u0639\u0646 \u0625\u0634\u0631\u0627\u0643 \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u0641\u064a \u0627\u0644\u0645\u0646\u0627\u0648\u0644\u0629","\u0639\u0646\u062f\u0645\u0627 \u064a\u0639\u062c\u0632 \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u0648\u0646 \u0639\u0646 \u0635\u064a\u0627\u063a\u0629 \u0641\u0631\u0636\u064a\u0627\u062a","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aoi=new A.c("\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643 \u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0639\u0644\u0645\u064a",null,"\u0645\u062a\u0649 \u064a\u0645\u0643\u0646 \u0627\u0644\u0644\u062c\u0648\u0621 \u0625\u0644\u0649 \u0627\u0644\u062a\u062c\u0627\u0631\u0628 \u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a\u0629 \u0641\u064a \u062a\u062f\u0628\u064a\u0631 \u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0639\u0644\u0645\u064a\u061f",B.Z2,0,"\u064a\u0645\u0643\u0646 \u0627\u0644\u0627\u0633\u062a\u0639\u0627\u0646\u0629 \u0628\u0627\u0644\u062a\u062c\u0627\u0631\u0628 \u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a\u0629 \u0627\u0644\u0648\u0627\u0631\u062f\u0629 \u0641\u064a \u0627\u0644\u0645\u0648\u0627\u0631\u062f \u0627\u0644\u0631\u0642\u0645\u064a\u0629 \u0639\u0646\u062f\u0645\u0627 \u062a\u062a\u0639\u0630\u0631 \u0627\u0644\u062a\u062c\u0631\u0628\u0629 \u0627\u0644\u0641\u0639\u0644\u064a\u0629\u060c \u0645\u0639 \u0627\u0644\u062d\u0631\u0635 \u0639\u0644\u0649 \u0625\u0634\u0631\u0627\u0643 \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u0641\u064a \u0627\u0644\u0645\u0646\u0627\u0648\u0644\u0629 \u0627\u0644\u0639\u0644\u0645\u064a\u0629.",u.j)
B.a_p=s(["\u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u0627\u0633\u062a\u0646\u062a\u0627\u062c \u0627\u0644\u0646\u0647\u0627\u0626\u064a \u0642\u0628\u0644 \u0639\u0631\u0636 \u0646\u062a\u0627\u0626\u062c \u0627\u0644\u0645\u062c\u0645\u0648\u0639\u0627\u062a","\u062a\u0646\u0634\u064a\u0637 \u0627\u0644\u0646\u0642\u0627\u0634 \u0648\u0627\u0644\u0627\u0647\u062a\u0645\u0627\u0645 \u0628\u0627\u0644\u062a\u0645\u062b\u0644\u0627\u062a \u0648\u0627\u0644\u0623\u062e\u0637\u0627\u0621 \u0645\u0646 \u0623\u062c\u0644 \u062a\u0635\u062d\u064a\u062d\u0647\u0627","\u062a\u0635\u062d\u064a\u062d \u0643\u0644 \u062e\u0637\u0623 \u0641\u0648\u0631\u0627 \u062f\u0648\u0646 \u0625\u0641\u0633\u0627\u062d \u0627\u0644\u0645\u062c\u0627\u0644 \u0644\u0644\u0646\u0642\u0627\u0634","\u0627\u0644\u0627\u0643\u062a\u0641\u0627\u0621 \u0628\u062c\u0645\u0639 \u0627\u0644\u0625\u0646\u062a\u0627\u062c\u0627\u062a \u062f\u0648\u0646 \u0645\u0646\u0627\u0642\u0634\u062a\u0647\u0627","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aiK=new A.c("\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643 \u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0639\u0644\u0645\u064a",null,"\u062e\u0644\u0627\u0644 \u0645\u0631\u062d\u0644\u0629 \u062a\u0642\u062f\u064a\u0645 \u0648\u062a\u0642\u0627\u0633\u0645 \u0627\u0644\u0625\u0646\u062a\u0627\u062c\u0627\u062a \u0641\u064a \u0646\u0647\u062c \u0627\u0644\u062a\u0642\u0635\u064a\u060c \u064a\u062a\u0645\u062b\u0644 \u0627\u0644\u062f\u0648\u0631 \u0627\u0644\u0631\u0626\u064a\u0633 \u0644\u0644\u0645\u062f\u0631\u0633(\u0629) \u0641\u064a:",B.a_p,1,"\u062e\u0644\u0627\u0644 \u062a\u0642\u0627\u0633\u0645 \u0627\u0644\u0625\u0646\u062a\u0627\u062c\u0627\u062a \u064a\u0639\u0631\u0636 \u0645\u0645\u062b\u0644\u0648 \u0627\u0644\u0645\u062c\u0645\u0648\u0639\u0627\u062a \u0646\u062a\u0627\u0626\u062c \u0627\u0644\u062a\u0642\u0635\u064a \u0648\u062a\u0646\u0627\u0642\u0634 \u0648\u062a\u0642\u0627\u0631\u0646 \u0628\u0627\u0644\u0641\u0631\u0636\u064a\u0627\u062a\u060c \u0628\u064a\u0646\u0645\u0627 \u064a\u0642\u0648\u0645 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0628\u0627\u0644\u062a\u0646\u0634\u064a\u0637 \u0648\u0627\u0644\u0627\u0647\u062a\u0645\u0627\u0645 \u0628\u0627\u0644\u062a\u0645\u062b\u0644\u0627\u062a \u0623\u0648 \u0627\u0644\u0623\u062e\u0637\u0627\u0621 \u0644\u062a\u0635\u062d\u064a\u062d\u0647\u0627.",u.j)
B.a7u=s(["\u0625\u0639\u0627\u062f\u0629 \u062a\u0646\u0641\u064a\u0630 \u0627\u0644\u062a\u062c\u0627\u0631\u0628 \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0639\u0644\u0649 \u0646\u0641\u0633 \u0627\u0644\u0638\u0627\u0647\u0631\u0629","\u062a\u0648\u0632\u064a\u0639 \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u0639\u0644\u0649 \u0645\u062c\u0645\u0648\u0639\u0627\u062a \u063a\u064a\u0631 \u0645\u062a\u062c\u0627\u0646\u0633\u0629","\u062a\u062f\u062e\u0644 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0644\u0628\u0646\u0627\u0621 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u0629 \u0648\u062a\u0648\u062b\u064a\u0642\u0647\u0627 \u0641\u064a \u0627\u0633\u062a\u0646\u062a\u0627\u062c\u0627\u062a \u0623\u0648 \u062c\u062f\u0627\u0648\u0644 \u0623\u0648 \u062e\u0637\u0627\u0637\u0627\u062a","\u0637\u0631\u062d \u0623\u0633\u0626\u0644\u0629 \u062c\u062f\u064a\u062f\u0629 \u062d\u0648\u0644 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u0637\u0644\u0627\u0642","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
