B.art=new A.c("\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643 \u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0639\u0644\u0645\u064a",null,"\u0623\u064a \u0645\u0646 \u0627\u0644\u0622\u062a\u064a \u064a\u0639\u0643\u0633 \u062a\u0635\u0646\u064a\u0641 \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0627\u062a \u0627\u0644\u0639\u0644\u0645\u064a\u0629 \u0641\u064a \u0645\u0646\u0647\u0627\u062c \u0645\u0627\u062f\u0629 \u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0639\u0644\u0645\u064a\u061f",B.aa6,2,"\u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0627\u062a \u0627\u0644\u0639\u0644\u0645\u064a\u0629 \u062a\u0634\u0645\u0644 \u0623\u0646\u0634\u0637\u0629 \u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u0641\u0647\u0648\u0645 (\u0646\u0647\u062c \u0627\u0644\u062a\u0642\u0635\u064a \u0641\u064a \u0627\u0644\u0639\u0644\u0648\u0645 \u0648\u0646\u0647\u062c \u062d\u0644 \u0627\u0644\u0645\u0634\u0643\u0644\u0627\u062a \u0641\u064a \u0645\u0648\u0627\u0636\u064a\u0639 \u0627\u0644\u062a\u0643\u0646\u0648\u0644\u0648\u062c\u064a\u0627) \u0648\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0648\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645 \u0648\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u0627\u0633\u062a\u062b\u0645\u0627\u0631 \u0648\u0627\u0644\u0627\u0645\u062a\u062f\u0627\u062f.",u.j)
