B.anq=new A.c("\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643 \u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0639\u0644\u0645\u064a",null,"\u0623\u064a \u0645\u0646 \u0627\u0644\u0622\u062a\u064a \u064a\u0639\u062f \u0645\u0646 \u0645\u0631\u062a\u0643\u0632\u0627\u062a \u0645\u0646\u0647\u0627\u062c \u0645\u0627\u062f\u0629 \u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0639\u0644\u0645\u064a \u0648\u0641\u0642 \u0627\u0644\u0645\u0646\u0647\u0627\u062c \u0627\u0644\u062f\u0631\u0627\u0633\u064a \u0644\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a\u061f",B.X3,0,"\u0645\u0631\u062a\u0643\u0632\u0627\u062a \u0645\u0646\u0647\u0627\u062c \u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0639\u0644\u0645\u064a \u0647\u064a \u0645\u0647\u0627\u0631\u0627\u062a \u0627\u0644\u0642\u0631\u0646 \u0627\u0644\u062d\u0627\u062f\u064a \u0648\u0627\u0644\u0639\u0634\u0631\u064a\u0646 \u0648\u0627\u0644\u062b\u0642\u0627\u0641\u0629 \u0627\u0644\u0639\u0644\u0645\u064a\u0629 \u0648\u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0645\u0633\u062a\u062f\u0627\u0645\u0629 \u0648\u0627\u0644\u062a\u0647\u064a\u0626\u0629 \u0627\u0644\u0644\u063a\u0648\u064a\u0629 (\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0627\u0644\u0644\u063a\u0648\u064a).",u.j)
B.a6J=s(["\u062c\u0645\u064a\u0639 \u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a\u0629 \u0645\u0646\u0630 \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0623\u0648\u0644","\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u064a\u0646 \u0627\u0644\u062e\u0627\u0645\u0633 \u0648\u0627\u0644\u0633\u0627\u062f\u0633 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u064a\u0646 \u0627\u0644\u0623\u0648\u0644 \u0648\u0627\u0644\u062b\u0627\u0646\u064a \u0641\u0642\u0637","\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a \u0627\u0644\u0625\u0639\u062f\u0627\u062f\u064a\u0629 \u062d\u0635\u0631\u064a\u0627","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.as8=new A.c("\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643 \u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0639\u0644\u0645\u064a",null,"\u0628\u0631\u0646\u0627\u0645\u062c \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u064a\u0627\u062a (\u062a\u0639\u0644\u0645 \u0627\u0644\u0628\u0631\u0645\u062c\u0629 \u0628\u0648\u0627\u0633\u0637\u0629 Scratch) \u0641\u064a \u0625\u0637\u0627\u0631 \u0645\u0627\u062f\u0629 \u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0639\u0644\u0645\u064a \u064a\u062f\u0631\u062c \u0636\u0645\u0646:",B.a6J,1,"\u0628\u0631\u0646\u0627\u0645\u062c \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u064a\u0627\u062a \u064a\u062f\u0631\u062c \u0641\u064a \u0627\u0644\u0645\u0633\u062a\u0648\u064a\u064a\u0646 \u0627\u0644\u062e\u0627\u0645\u0633 \u0648\u0627\u0644\u0633\u0627\u062f\u0633 \u0627\u0628\u062a\u062f\u0627\u0626\u064a\u060c \u0648\u064a\u062a\u0636\u0645\u0646 \u062a\u0639\u0644\u0645 \u0627\u0644\u0628\u0631\u0645\u062c\u0629 \u0628\u0648\u0627\u0633\u0637\u0629 Scratch.",u.Q)
B.a9V=s(["\u062f\u0641\u0627\u062a\u0631 \u0627\u0644\u0646\u0635\u0648\u0635 \u0648\u0627\u0644\u0625\u0646\u0634\u0627\u0621 \u0641\u0642\u0637","\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u0634\u0641\u0648\u064a \u0644\u0645\u062d\u0641\u0648\u0638\u0627\u062a \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646","\u062f\u0641\u0627\u062a\u0631 \u0627\u0644\u062a\u0642\u0635\u064a \u0648\u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0627\u062a \u0627\u0644\u0645\u0628\u0627\u0634\u0631\u0629 \u0648\u0627\u0644\u062d\u0642\u064a\u0628\u0629 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0629 (Portfolio) \u0648\u0627\u0644\u0645\u0634\u0627\u0631\u064a\u0639","\u0627\u0644\u0627\u0645\u062a\u062d\u0627\u0646\u0627\u062a \u0627\u0644\u0645\u0648\u062d\u062f\u0629 \u0627\u0644\u0625\u0642\u0644\u064a\u0645\u064a\u0629 \u0648\u062d\u062f\u0647\u0627","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aoe=new A.c("\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643 \u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0639\u0644\u0645\u064a",null,"\u0623\u064a \u0645\u0646 \u0627\u0644\u0622\u062a\u064a \u064a\u0639\u062f \u0645\u0646 \u0623\u062f\u0648\u0627\u062a \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u0645\u0639\u062a\u0645\u062f\u0629 \u0641\u064a \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0635\u0641\u064a\u0629 \u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u0639\u0644\u0649 \u0646\u0647\u062c \u0627\u0644\u062a\u0642\u0635\u064a\u061f",B.a9V,2,"\u0645\u0646 \u0623\u062f\u0648\u0627\u062a \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0641\u064a \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0635\u0641\u064a\u0629 \u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u0639\u0644\u0649 \u0646\u0647\u062c \u0627\u0644\u062a\u0642\u0635\u064a: \u062f\u0641\u0627\u062a\u0631 \u0627\u0644\u062a\u0642\u0635\u064a \u0648\u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0627\u062a \u0627\u0644\u0645\u0628\u0627\u0634\u0631\u0629 \u0648\u0627\u0644\u0645\u0634\u0627\u0631\u064a\u0639 \u0648\u0627\u0644\u0645\u0646\u0627\u0642\u0634\u0627\u062a \u0648\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0646\u0645\u0627\u0630\u062c \u0648\u0627\u0644\u062d\u0642\u064a\u0628\u0629 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0629.",u.j)
