B.aqO=new A.c("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,"\u0627\u0644\u0646\u0638\u0631\u064a\u0629 \u0627\u0644\u0628\u0646\u0627\u0626\u064a\u0629 (\u0627\u0644\u062a\u0643\u0648\u064a\u0646\u064a\u0629) \u062a\u0642\u0648\u0645 \u0639\u0644\u0649 \u0623\u0646:",B.Vj,1,"\u0627\u0644\u0646\u0638\u0631\u064a\u0629 \u0627\u0644\u0628\u0646\u0627\u0626\u064a\u0629 \u0645\u0646 \u0627\u0644\u0646\u0638\u0631\u064a\u0627\u062a \u0627\u0644\u062d\u062f\u064a\u062b\u0629 \u0638\u0647\u0631\u062a \u0641\u064a \u0633\u062a\u064a\u0646\u064a\u0627\u062a \u0648\u0633\u0628\u0639\u064a\u0646\u064a\u0627\u062a \u0627\u0644\u0642\u0631\u0646 \u0627\u0644\u0645\u0627\u0636\u064a\u060c \u0648\u062a\u0642\u0648\u0645 \u0639\u0644\u0649 \u0623\u0646 \u0627\u0644\u062a\u0639\u0644\u0645 \u0641\u0639\u0644 \u0646\u0634\u064a\u0637\u060c \u0648\u0623\u0646 \u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u0639\u0627\u0631\u0641 \u064a\u062a\u0645 \u0627\u0633\u062a\u0646\u0627\u062f\u0627\u064b \u0625\u0644\u0649 \u0627\u0644\u0645\u0639\u0627\u0631\u0641 \u0627\u0644\u0633\u0627\u0628\u0642\u0629\u060c \u0648\u062c\u0639\u0644 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0645\u062d\u0648\u0631 \u0627\u0644\u0639\u0645\u0644\u064a\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629 \u0627\u0644\u062a\u0639\u0644\u0645\u064a\u0629.",null)
B.SI=s(["\u0627\u0644\u0633\u0644\u0648\u0643\u0627\u062a \u0627\u0644\u062e\u0627\u0631\u062c\u064a\u0629 \u0627\u0644\u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u0645\u0644\u0627\u062d\u0638\u0629","\u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a \u0627\u0644\u062f\u0627\u062e\u0644\u064a\u0629 \u0644\u0644\u0639\u0642\u0644 \u0643\u0627\u0644\u0641\u0647\u0645 \u0648\u0627\u0644\u062a\u0641\u0643\u064a\u0631 \u0648\u0627\u0644\u0625\u062f\u0631\u0627\u0643 \u0648\u0627\u0644\u0630\u0627\u0643\u0631\u0629 \u0648\u062d\u0644 \u0627\u0644\u0645\u0634\u0643\u0644\u0627\u062a","\u0627\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0627\u062a \u0627\u0644\u0627\u0646\u0639\u0643\u0627\u0633\u064a\u0629 \u0627\u0644\u0622\u0644\u064a\u0629","\u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0627\u0644\u0628\u062f\u0646\u064a\u0629 \u0648\u0627\u0644\u062d\u0631\u0643\u064a\u0629"],t.s)
B.aqQ=new A.c("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,"\u062a\u0647\u062a\u0645 \u0627\u0644\u0646\u0638\u0631\u064a\u0629 \u0627\u0644\u0645\u0639\u0631\u0641\u064a\u0629 \u0641\u064a \u0627\u0644\u062a\u0639\u0644\u0645 \u0623\u0633\u0627\u0633\u0627\u064b \u0628\u0640:",B.SI,1,"\u0627\u0644\u0646\u0638\u0631\u064a\u0629 \u0627\u0644\u0645\u0639\u0631\u0641\u064a\u0629 \u062a\u0647\u062a\u0645 \u0628\u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a \u0627\u0644\u062f\u0627\u062e\u0644\u064a\u0629 \u0644\u0644\u0639\u0642\u0644: \u0627\u0644\u0641\u0647\u0645 \u0648\u0627\u0644\u062a\u0641\u0643\u064a\u0631 \u0648\u0627\u0644\u0627\u0646\u062a\u0628\u0627\u0647 \u0648\u0627\u0644\u0625\u062f\u0631\u0627\u0643 \u0648\u0627\u0644\u0630\u0627\u0643\u0631\u0629 \u0648\u062d\u0644 \u0627\u0644\u0645\u0634\u0643\u0644\u0627\u062a\u060c \u0648\u062a\u0642\u0648\u0645 \u0639\u0644\u0649 \u0641\u0647\u0645 \u0627\u0644\u0645\u0639\u0646\u0649 \u0628\u062f\u0644 \u0627\u0644\u062d\u0641\u0638 \u0648\u0627\u0644\u062a\u0644\u0642\u064a\u0646\u060c \u0648\u062a\u0633\u062a\u062b\u0645\u0631 \u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0627\u0644\u062c\u062f\u064a\u062f\u0629 \u0628\u0627\u0644\u062e\u0628\u0631\u0627\u062a \u0627\u0644\u0633\u0627\u0628\u0642\u0629.",null)
B.a5y=s(["\u062d\u0641\u0632 \u0631\u0648\u062d \u0627\u0644\u0645\u0628\u0627\u062f\u0631\u0629 \u0648\u0627\u0644\u062a\u0641\u0648\u0642 \u0641\u064a \u0627\u0644\u0645\u0624\u0633\u0633\u0629 \u0627\u0644\u062b\u0627\u0646\u0648\u064a\u0629 \u0648\u0641\u064a \u0627\u0644\u062c\u0627\u0645\u0639\u0629","\u0627\u0644\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u0641\u0639\u0644\u064a \u0644\u0625\u0644\u0632\u0627\u0645\u064a\u0629 \u0627\u0644\u062a\u0645\u062f\u0631\u0633 \u0625\u0644\u0649 \u063a\u0627\u064a\u0629 15 \u0633\u0646\u0629","\u062a\u0648\u0641\u064a\u0631 \u0648\u0633\u0627\u0626\u0644 \u0627\u0644\u0646\u062c\u0627\u062d","\u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0625\u0634\u0643\u0627\u0644\u0627\u062a \u0627\u0644\u0623\u0641\u0642\u064a\u0629 \u0644\u0644\u0645\u0646\u0638\u0648\u0645\u0629 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0629"],t.s)
B.aqW=new A.c("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,"\u0627\u0644\u0647\u062f\u0641 \u0627\u0644\u0623\u0648\u0644 \u0645\u0646 \u0627\u0644\u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u0623\u0631\u0628\u0639\u0629 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0644\u0644\u0628\u0631\u0646\u0627\u0645\u062c \u0627\u0644\u0627\u0633\u062a\u0639\u062c\u0627\u0644\u064a (2009-2012) \u0647\u0648:",B.a5y,1,"\u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u0628\u0631\u0646\u0627\u0645\u062c \u0627\u0644\u0627\u0633\u062a\u0639\u062c\u0627\u0644\u064a \u0627\u0644\u0623\u0631\u0628\u0639\u0629: \u0627\u0644\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u0641\u0639\u0644\u064a \u0644\u0625\u0644\u0632\u0627\u0645\u064a\u0629 \u0627\u0644\u062a\u0645\u062f\u0631\u0633 \u0625\u0644\u0649 \u063a\u0627\u064a\u0629 15 \u0633\u0646\u0629\u060c \u062d\u0641\u0632 \u0631\u0648\u062d \u0627\u0644\u0645\u0628\u0627\u062f\u0631\u0629 \u0648\u0627\u0644\u062a\u0641\u0648\u0642 \u0641\u064a \u0627\u0644\u062b\u0627\u0646\u0648\u064a\u0629 \u0648\u0627\u0644\u062c\u0627\u0645\u0639\u0629\u060c \u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0625\u0634\u0643\u0627\u0644\u0627\u062a \u0627\u0644\u0623\u0641\u0642\u064a\u0629 \u0644\u0644\u0645\u0646\u0638\u0648\u0645\u0629 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0629\u060c \u0648\u062a\u0648\u0641\u064a\u0631 \u0648\u0633\u0627\u0626\u0644 \u0627\u0644\u0646\u062c\u0627\u062d.",null)
B.a5b=s(['\u0627\u0639\u062a\u0642\u0627\u062f \u0623\u0646 \u0627\u0644\u062a\u064a\u0627\u0631 "\u064a\u064f\u0633\u062a\u0647\u0644\u0643" \u062a\u062f\u0631\u064a\u062c\u064a\u0627\u064b \u0641\u064a \u0627\u0644\u062f\u0627\u0631\u0629 \u0643\u0633\u0627\u0626\u0644 \u064a\u0646\u0641\u062f',"\u0641\u0647\u0645 \u0635\u062d\u064a\u062d \u062f\u0627\u0626\u0645\u0627\u064b \u0644\u0645\u0641\u0647\u0648\u0645 \u0627\u0644\u062a\u064a\u0627\u0631 \u0645\u0646\u0630 \u0627\u0644\u0628\u062f\u0627\u064a\u0629","\u0639\u062f\u0645 \u0645\u0639\u0631\u0641\u0629 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 \u0627\u0644\u0645\u0648\u0635\u0644 \u0648\u0627\u0644\u0639\u0627\u0632\u0644 \u0641\u0642\u0637","\u0627\u0644\u062e\u0644\u0637 \u0628\u064a\u0646 \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0621 \u0648\u0627\u0644\u0645\u063a\u0646\u0627\u0637\u064a\u0633\u064a\u0629 \u062d\u0635\u0631\u0627\u064b"],t.s)
B.aqZ=new A.c("\u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0639\u0644\u0645\u064a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0633\u0627\u062f\u0633",'\u0641\u064a \u062a\u062f\u0631\u064a\u0633 \u0645\u0641\u0647\u0648\u0645 "\u0627\u0644\u062f\u0627\u0631\u0629 \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0626\u064a\u0629"\u060c \u0627\u0644\u062e\u0637\u0623 \u0627\u0644\u0634\u0627\u0626\u0639 \u0644\u062f\u0649 \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u0647\u0648:',B.a5b,0,'\u0645\u0646 \u0627\u0644\u062a\u0645\u062b\u0644\u0627\u062a \u0627\u0644\u062e\u0627\u0637\u0626\u0629 \u0627\u0644\u0634\u0627\u0626\u0639\u0629 \u0644\u062f\u0649 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u062a\u0635\u0648\u0651\u0631 \u0627\u0644\u062a\u064a\u0627\u0631 \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0626\u064a \u0643\u0633\u0627\u0626\u0644 "\u064a\u064f\u0633\u062a\u0647\u0644\u0643" \u0623\u062b\u0646\u0627\u0621 \u0645\u0631\u0648\u0631\u0647 \u0641\u064a \u0627\u0644\u062f\u0627\u0631\u0629\u060c \u0628\u064a\u0646\u0645\u0627 \u0627\u0644\u0635\u062d\u064a\u062d \u0623\u0646 \u0634\u062f\u0629 \u0627\u0644\u062a\u064a\u0627\u0631 \u062a\u0628\u0642\u0649 \u062b\u0627\u0628\u062a\u0629 \u0641\u064a \u0627\u0644\u062f\u0627\u0631\u0629 \u0627\u0644\u0628\u0633\u064a\u0637\u0629 \u0639\u0644\u0649 \u0627\u0644\u062a\u0648\u0627\u0644\u064a (\u0642\u0628\u0644 \u0627\u0644\u0641\u0631\u0648\u0639).',null)
B.YZ=s(["\u0644\u0627 \u0641\u0631\u0642 \u0628\u064a\u0646\u0647\u0645\u0627\u060c \u0648\u0647\u0645\u0627 \u0645\u062a\u0631\u0627\u062f\u0641\u0627\u0646","\u0627\u0644\u0642\u062f\u0631\u0629 \u0625\u0645\u0643\u0627\u0646\u064a\u0629 \u0630\u0647\u0646\u064a\u0629 \u0639\u0627\u0645\u0629\u060c \u0628\u064a\u0646\u0645\u0627 \u0627\u0644\u0643\u0641\u0627\u064a\u0629 \u062a\u0639\u0628\u0626\u0629 \u0645\u0646\u062f\u0645\u062c\u0629 \u0644\u0645\u0648\u0627\u0631\u062f \u0644\u062d\u0644 \u0648\u0636\u0639\u064a\u0629 \u0645\u0639\u0642\u062f\u0629","\u0627\u0644\u0643\u0641\u0627\u064a\u0629 \u0641\u0637\u0631\u064a\u0629 \u0648\u0627\u0644\u0642\u062f\u0631\u0629 \u0645\u0643\u062a\u0633\u0628\u0629 \u0641\u0642\u0637","\u0627\u0644\u0642\u062f\u0631\u0629 \u062a\u062e\u0635 \u0641\u0642\u0637 \u0627\u0644\u0645\u0648\u0627\u062f \u0627\u0644\u0639\u0644\u0645\u064a\u0629 \u062f\u0648\u0646 \u0627\u0644\u0623\u062f\u0628\u064a\u0629"],t.s)
